INSERT INTO [dbo].[Banner] ([Id], [Name], [ClassActive], [Template], [Status], [Delete], [Language], [Type], [Code], [PortalId], [Content]) VALUES (11, N'Home Slider Dấu Ấn', NULL, N'<style>
   #WhatWe{background:url(/Data/Banner/bg-what.jpg) no-repeat center;background-size:cover;background-position:center center;}#WhatWe h2{color:#fff}#WhatWe .number{color:#fff}#WhatWe .number{font-weight:700;}#WhatWe .desc{font-weight:500;font-size:16px;color:#fff}#WhatWe .btn-about{background:#fff;color:var(--primary-color);width:284px;height:50px;font-size:24px;border-radius:2em}.logo-slider{width:100%;overflow:hidden;position:relative}.logo-track{display:flex;width:calc(200px * 14);animation:scroll 40s linear infinite}.logo-slider:hover .logo-track{animation-play-state:paused}.logo-track .slide{height:auto;width:auto;display:grid;place-items:center;padding:10px;margin:0 15px;background:#fff;box-sizing:content-box;border-radius:10px}.logo-track .slide:hover{filter:grayscale(0%);opacity:1;transform:scale(1.1)}@keyframes scroll{0%{transform:translateX(0)}100%{transform:translateX(calc(-200px * 7))}}
  
.img-box {
  background-color: #fff;
  padding: 20px;
  height: 100px; /* hoặc chiều cao bạn muốn */
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 8px; /* bo góc nhẹ cho đẹp */
  box-shadow: 0 2px 8px rgba(0,0,0,0.05); /* đổ bóng nhẹ */
}

.img-parner {
    object-fit: unset;
	width:500px;
    margin: 0 0;
    background: #fff;
    padding: 6px;
    border-radius: 13px;
    max-width:100%;
}
.text-dt
  {
font-size: 25px;
    color: #fff;
    font-weight: 500;
    text-transform: uppercase;
  }
</style>
<section id="WhatWe" class="py-5">
    <div class="container home-style">
        <div class="row">
            <h2 class="price-title mb-5 text-center">FiinGroup và Dấu ấn phát triển</h2>
            <div class="col-sm-4 mb-5 text-center">
                <p class="number">
                    <span class="counter">1000</span>+
                </p>
                <p class="desc">Khách hàng tổ chức trên toàn cầu</p>
            </div>
            <div class="col-sm-4 mb-4 text-center">
                <p class="number">
                    <span class="counter">25.000</span>+
                </p>
                <p class="desc">Phân tích và báo cáo mỗi năm</p>
            </div>
            <div class="col-sm-4 mb-4 text-center">
                <p class="number">
                    <span class="counter">20</span>+
                </p>
                <p class="desc">Ngành chủ chốt</p>
            </div>
            <div class="col-sm-4 mb-4 text-center">
                <p class="number">
                    <span class="counter">30</span>%
                </p>
                <p class="desc">Tăng trưởng doanh thu (CAGR) <br> 10 năm qua</p>
            </div>
            <div class="col-sm-4 mb-4 text-center">
                <p class="number">
                    <span class=""></span>
                </p>
                <p class="desc"></p>
            </div>
            <div class="col-sm-4 mb-4 text-center">
                <p class="number">
                    <span class="">Hàng triệu </span>
                </p>
                <p class="desc">Người sử dụng platform dữ liệu mỗi ngày</p>
            </div>
                      <div class="col-sm-12 my-3 mt-4">
             <div class=''text-center mt-2 text-dt''>Đối tác chiến lược</div>
           </div>
           <div class="col-sm-12 my-3 mt-2">
           	<div class=''text-center''>
            [For]
              <img class="img-parner" src="[Img]" alt="[Name]" loading="lazy">
            [/For]
          	</div>
           </div>
            <div class="text-center">
                <a class="btn btn-light btn-about mt-5" href="/vi/gioi-thieu.html">Về chúng tôi</a>
            </div>
        </div>
    </div>
</section>', 1, 0, N'vi', 0, N'HomeSliderDauAn', 2, N'<style>
   #WhatWe{background:url(/Data/Banner/bg-what.jpg) no-repeat center;background-size:cover;background-position:center center;}#WhatWe h2{color:#fff}#WhatWe .number{color:#fff}#WhatWe .number{font-weight:700;}#WhatWe .desc{font-weight:500;font-size:16px;color:#fff}#WhatWe .btn-about{background:#fff;color:var(--primary-color);width:284px;height:50px;font-size:24px;border-radius:2em}.logo-slider{width:100%;overflow:hidden;position:relative}.logo-track{display:flex;width:calc(200px * 14);animation:scroll 40s linear infinite}.logo-slider:hover .logo-track{animation-play-state:paused}.logo-track .slide{height:auto;width:auto;display:grid;place-items:center;padding:10px;margin:0 15px;background:#fff;box-sizing:content-box;border-radius:10px}.logo-track .slide:hover{filter:grayscale(0%);opacity:1;transform:scale(1.1)}@keyframes scroll{0%{transform:translateX(0)}100%{transform:translateX(calc(-200px * 7))}}
  
.img-box {
  background-color: #fff;
  padding: 20px;
  height: 100px; /* hoặc chiều cao bạn muốn */
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 8px; /* bo góc nhẹ cho đẹp */
  box-shadow: 0 2px 8px rgba(0,0,0,0.05); /* đổ bóng nhẹ */
}

.img-parner {
    object-fit: unset;
	width:500px;
    margin: 0 0;
    background: #fff;
    padding: 6px;
    border-radius: 13px;
    max-width:100%;
}
.text-dt
  {
font-size: 25px;
    color: #fff;
    font-weight: 500;
    text-transform: uppercase;
  }
</style>
<section id="WhatWe" class="py-5">
    <div class="container home-style">
        <div class="row">
            <h2 class="price-title mb-5 text-center">FiinGroup và Dấu ấn phát triển</h2>
            <div class="col-sm-4 mb-5 text-center">
                <p class="number">
                    <span class="counter">1000</span>+
                </p>
                <p class="desc">Khách hàng tổ chức trên toàn cầu</p>
            </div>
            <div class="col-sm-4 mb-4 text-center">
                <p class="number">
                    <span class="counter">25.000</span>+
                </p>
                <p class="desc">Phân tích và báo cáo mỗi năm</p>
            </div>
            <div class="col-sm-4 mb-4 text-center">
                <p class="number">
                    <span class="counter">20</span>+
                </p>
                <p class="desc">Ngành chủ chốt</p>
            </div>
            <div class="col-sm-4 mb-4 text-center">
                <p class="number">
                    <span class="counter">30</span>%
                </p>
                <p class="desc">Tăng trưởng doanh thu (CAGR) <br> 10 năm qua</p>
            </div>
            <div class="col-sm-4 mb-4 text-center">
                <p class="number">
                    <span class=""></span>
                </p>
                <p class="desc"></p>
            </div>
            <div class="col-sm-4 mb-4 text-center">
                <p class="number">
                    <span class="">Hàng triệu </span>
                </p>
                <p class="desc">Người sử dụng platform dữ liệu mỗi ngày</p>
            </div>
                      <div class="col-sm-12 my-3 mt-4">
             <div class=''text-center mt-2 text-dt''>Đối tác chiến lược</div>
           </div>
           <div class="col-sm-12 my-3 mt-2">
           	<div class=''text-center''>
            
              <img class="img-parner" src="/Data/Banner/Partner/logo%20%C4%91%E1%BB%91i%20t%C3%A1c.png" alt="logo" loading="lazy">
            
          	</div>
           </div>
            <div class="text-center">
                <a class="btn btn-light btn-about mt-5" href="/vi/gioi-thieu.html">Về chúng tôi</a>
            </div>
        </div>
    </div>
</section>');
