INSERT INTO [dbo].[Banner] ([Id], [Name], [ClassActive], [Template], [Status], [Delete], [Language], [Type], [Code], [PortalId], [Content]) VALUES (19, N'Solution - Slide Featured', NULL, N'<section id="Insights" class="py-5 mb-5">
            <style>
                .show-all {
                    background-color: #ffffff;
                    color: #0066cc;
                    padding: 8px 60px;
                    border-radius: 25px;
                    cursor: pointer;
                    margin-top: 20px;
                    display: inline-block;
                    border: 1px solid #0066cc;
                }
            </style>
            <div class="container">
                <div class="row">
                    <div class="col-sm-8">
                        <h2 class="price-title mb-5">Our <span style="color: #0066CC;">Featured & Insights</span></h2>
                    </div>
