INSERT INTO [dbo].[Banner] ([Id], [Name], [ClassActive], [Template], [Status], [Delete], [Language], [Type], [Code], [PortalId], [Content]) VALUES (53, N'AboutUs - WordEnvironment', NULL, N'<section id="WordEnvironment" class="py-3 mb-5">
            <style>
