INSERT INTO [dbo].[Banner] ([Id], [Name], [ClassActive], [Template], [Status], [Delete], [Language], [Type], [Code], [PortalId], [Content]) VALUES (64, N'AboutUs - WordEnvironment', NULL, N'<section id="WordEnvironment" class="py-5 mb-5">
