INSERT INTO [dbo].[BannerItem] ([Id], [BannerId], [Name], [Href], [Target], [Content], [Template], [Banner], [Banner1], [Banner2], [Order], [Status], [Content1], [Content2]) VALUES (33, 12, N'F88', N'#', N'_blank', N'Các nghiên cứu chuyên sâu do FiinGroup thực hiện về thị trường tài chính thay thế đã mang lại cho chúng tôi không chỉ dữ liệu thực tiễn có giá trị, mà còn giúp thị trường hiểu  rõ sự khác biệt giữa mô hình cầm đồ truyền thống và định hướng minh bạch, chuyên nghiệp mà F88 đang theo đuổi', NULL, N'/Data/%E1%BA%A3nh%20s%E1%BA%A3n%20ph%E1%BA%A9m/Case%20study/F88.jpg', N'/Data/%E1%BA%A3nh%20s%E1%BA%A3n%20ph%E1%BA%A9m/Case%20study/Logo%20-%20F88.png', NULL, 1, 1, N'Ông Phùng Anh Tuấn', N'Nhà sáng lập kiêm Chủ tịch Hội đồng Quản trị F88');
INSERT INTO [dbo].[BannerItem] ([Id], [BannerId], [Name], [Href], [Target], [Content], [Template], [Banner], [Banner1], [Banner2], [Order], [Status], [Content1], [Content2]) VALUES (34, 12, N'Cathay Life', N'#', N'_blank', N'Chúng tôi đánh giá cao năng lực cung cấp dữ liệu sâu, kịp thời, minh bạch và khả năng tùy biến theo nhu cầu thực tiễn từ FiinGroup - một đối tác dữ liệu uy tín, đồng hành cùng Cathay Life trên hành trình phát triển bền vững.', NULL, N'/Data/%E1%BA%A3nh%20s%E1%BA%A3n%20ph%E1%BA%A9m/Case%20study/Cathay%20Life.png', N'/Data/Banner/Partner/Cathay%20Lifee.png', NULL, 2, 1, N'Ông James Wu,', N'Tổng Giám đốc Điều hành Cathay Life Việt Nam');
INSERT INTO [dbo].[BannerItem] ([Id], [BannerId], [Name], [Href], [Target], [Content], [Template], [Banner], [Banner1], [Banner2], [Order], [Status], [Content1], [Content2]) VALUES (35, 12, N'Atradius', N'#', N'_blank', N'Nhờ nguồn thông tin đầy đủ và chính xác về hơn 2 triệu doanh nghiệp Việt và hàng triệu doanh nghiệp tại hơn 190 quốc gia được tích hợp trong nền tảng FiinGate, chúng tôi có cơ sở vững chắc để nâng cao hiệu quả và hiệu suất quá trình phân tích, thẩm định đối tác, dự báo sớm rủi ro tín dụng.', NULL, N'/Data/%E1%BA%A3nh%20s%E1%BA%A3n%20ph%E1%BA%A9m/Case%20study/Atradius.png', N'/Data/Banner/Partner/Atradius.png', NULL, 3, 1, N'Bà Vũ Thị Đức Hạnh', N'Giám đốc Quốc gia của Atradius Việt Nam');
