INSERT INTO [dbo].[BannerItem] ([Id], [BannerId], [Name], [Href], [Target], [Content], [Template], [Banner], [Banner1], [Banner2], [Order], [Status], [Content1], [Content2]) VALUES (47, 46, N'F88', N'#', N'_blank', N'FiinGroup’s in-depth research on the alternative financial market has not only provided us with valuable data, but also helped the market differentiate the traditional pawnshop model and the transparent, professional direction that F88 is pursuing', NULL, N'/Data/%E1%BA%A3nh%20s%E1%BA%A3n%20ph%E1%BA%A9m/Case%20study/F88.jpg', N'/Data/%E1%BA%A3nh%20s%E1%BA%A3n%20ph%E1%BA%A9m/Case%20study/Logo%20-%20F88.png', NULL, 1, 1, N'Mr. Phung Anh Tuan, ', N'Founder and Chairman of the Board');
INSERT INTO [dbo].[BannerItem] ([Id], [BannerId], [Name], [Href], [Target], [Content], [Template], [Banner], [Banner1], [Banner2], [Order], [Status], [Content1], [Content2]) VALUES (48, 46, N'Cathay Life', N'#', N'_blank', N'We highly value FiinGroup’s capability to deliver deep, timely, and transparent data, along with its flexible adaptability to our practical needs. FiinGroup is a trusted data partner accompanying Cathay Life in our sustainable development.', NULL, N'/Data/%E1%BA%A3nh%20s%E1%BA%A3n%20ph%E1%BA%A9m/Case%20study/Cathay%20Life.png', N'/Data/Banner/Partner/Cathay%20Lifee.png?time=1765267100303', NULL, 2, 1, N'Mr. James Wu,', N'Chief Executive Officer of Cathay Life Vietnam');
INSERT INTO [dbo].[BannerItem] ([Id], [BannerId], [Name], [Href], [Target], [Content], [Template], [Banner], [Banner1], [Banner2], [Order], [Status], [Content1], [Content2]) VALUES (49, 46, N'Astradius', N'#', N'_blank', N'With comprehensive and accurate information on more than two million Vietnamese enterprises and millions of businesses across over 190 countries on FiinGate, we now have a solid foundation to enhance the efficiency of our partner analysis, due diligence, and early credit-risk alerts', NULL, N'/Data/%E1%BA%A3nh%20s%E1%BA%A3n%20ph%E1%BA%A9m/Case%20study/Atradius.png', N'/Data/Banner/Partner/Atradius.png?time=1765267138303', NULL, 3, 1, N'Ms. Vu Thi Duc Hanh,', N'Country Director of Atradius Vietnam');
