INSERT INTO [dbo].[BannerItem] ([Id], [BannerId], [Name], [Href], [Target], [Content], [Template], [Banner], [Banner1], [Banner2], [Order], [Status], [Content1], [Content2]) VALUES (72, 51, N'BIDV', N'#', N'_blank', N'Sau khi đánh giá độc lập (SPO) ban đầu, chúng tôi đã thành công chào bán 2.500 tỷ đồng trái phiếu xanh và 3.000 tỷ đồng trái phiếu bền vững theo tiêu chuẩn ICMA. Đặc biệt, báo cáo phân bổ sử dụng vốn từ trái phiếu xanh của BIDV đã được FiinRatings đánh giá độc lập, khẳng định việc lựa chọn dự án và phân bổ vốn trái phiếu xanh hoàn toàn tuân thủ các quy định tại Khung trái phiếu xanh.', NULL, N'/Data/%E1%BA%A3nh%20s%E1%BA%A3n%20ph%E1%BA%A9m/Case%20study/bidv.png', N'/Data/%E1%BA%A3nh%20s%E1%BA%A3n%20ph%E1%BA%A9m/Logo%20kh%C3%A1ch%20h%C3%A0ng%20theo%20gi%E1%BA%A3i%20ph%C3%A1p/RA/BIDV%20Logo.png', NULL, 1, 1, N'Ông Trần Long', N'Phó Tổng Giám đốc BIDV');
INSERT INTO [dbo].[BannerItem] ([Id], [BannerId], [Name], [Href], [Target], [Content], [Template], [Banner], [Banner1], [Banner2], [Order], [Status], [Content1], [Content2]) VALUES (73, 51, N'BIWASE', N'#', N'_blank', N'Việc có được xếp hạng tín nhiệm của một đơn vị độc lập và uy tín như FiinRatings đã góp phần cho sự thành công của giao dịch phát hành lô trái phiếu này. Chúng tôi đánh giá cao sự hợp tác và hỗ trợ của FiinRatings trong việc cung cấp không chỉ kết quả điểm xếp hạng tín nhiệm mà cả những thông tin phân tích chuyên sâu và độc lập về triển vọng của ngành nước sạch nói chung và dự án BIWASE Long An nói riêng.', NULL, N'/Data/%E1%BA%A3nh%20s%E1%BA%A3n%20ph%E1%BA%A9m/Case%20study/biwase.png', N'/Data/%E1%BA%A3nh%20s%E1%BA%A3n%20ph%E1%BA%A9m/Logo%20kh%C3%A1ch%20h%C3%A0ng%20theo%20gi%E1%BA%A3i%20ph%C3%A1p/RA/Biwase.png', NULL, 2, 1, N'Ông Trần Tấn Đức', N'Phó Tổng Giám đốc kiêm Giám đốc Tài chính BIWASE');
INSERT INTO [dbo].[BannerItem] ([Id], [BannerId], [Name], [Href], [Target], [Content], [Template], [Banner], [Banner1], [Banner2], [Order], [Status], [Content1], [Content2]) VALUES (74, 51, N'Home Credit VN', N'#', N'_blank', N'Việc FiinRatings - đối tác chiến lược của S&P Global xếp hạng A với triển vọng ổn định là minh chứng cho hành trình xây dựng tăng trưởng bền vững của Home Credit Việt Nam. Với nền tảng tài chính vững chắc cùng khả năng quản lý rủi ro và dữ liệu hàng đầu, Home Credit đã đạt được các mục tiêu tăng trưởng trong năm 2024.', NULL, N'/Data/%E1%BA%A3nh%20s%E1%BA%A3n%20ph%E1%BA%A9m/Case%20study/homecredit.png', N'/Data/%E1%BA%A3nh%20s%E1%BA%A3n%20ph%E1%BA%A9m/Logo%20kh%C3%A1ch%20h%C3%A0ng%20theo%20gi%E1%BA%A3i%20ph%C3%A1p/RA/Homecredit.png', NULL, 3, 1, N'Ông Pham Ngoc Khang', N'Tổng Giám đốc Home Credit Việt Nam');
