INSERT INTO [dbo].[BannerItem] ([Id], [BannerId], [Name], [Href], [Target], [Content], [Template], [Banner], [Banner1], [Banner2], [Order], [Status], [Content1], [Content2]) VALUES (80, 56, N'Slide 1', N'https://fiinratings.vn/', N'_blank', N'FiinRatings - Công ty thành viên của FiinGroup và là đối tác chiến lược của S&P Global.', NULL, N'/Data/%E1%BA%A3nh%20s%E1%BA%A3n%20ph%E1%BA%A9m/Website%20Banner%20-%20RA%20(2).png', NULL, NULL, 1, 1, N'FiinRatings cung cấp hệ sinh thái dịch vụ toàn diện, bao gồm xếp hạng tín nhiệm, phân tích rủi ro, xác nhận và đánh giá độc lập trái phiếu xanh, đáp ứng nhu cầu của các nhà phát hành và nhà đầu tư tại Việt Nam. 

Với các đánh giá độc lập và chuẩn hóa, FiinRatings đóng vai trò nguồn tham chiếu khách quan trong đánh giá rủi ro tín dụng, hỗ trợ nâng cao minh bạch, hiệu quả và sự phát triển bền vững của thị trường vốn Việt Nam.', NULL);
INSERT INTO [dbo].[BannerItem] ([Id], [BannerId], [Name], [Href], [Target], [Content], [Template], [Banner], [Banner1], [Banner2], [Order], [Status], [Content1], [Content2]) VALUES (81, 56, N'Slide 2', N'https://fiinratings.vn/', N'_blank', N'Dịch vụ cho Tổ chức phát hành và Nhà đầu tư', NULL, N'/Data/%E1%BA%A3nh%20s%E1%BA%A3n%20ph%E1%BA%A9m/%E1%BA%A3nh%20RA.jpg', NULL, NULL, 2, 1, N'FiinRatings đồng hành cùng các tổ chức phát hành trong việc nâng cao khả năng tiếp cận vốn, mở rộng kênh huy động và tối ưu chi phí vốn; đồng thời hỗ trợ nhà đầu tư đánh giá rủi ro và ra quyết định đầu tư hiệu quả trên thị trường vốn Việt Nam.', NULL);
INSERT INTO [dbo].[BannerItem] ([Id], [BannerId], [Name], [Href], [Target], [Content], [Template], [Banner], [Banner1], [Banner2], [Order], [Status], [Content1], [Content2]) VALUES (82, 57, N'Slide 1', N'#', N'_blank', N'FiinRatings - A member company of FiinGroup and A strategic partner of S&P Global.', NULL, N'/Data/%E1%BA%A3nh%20s%E1%BA%A3n%20ph%E1%BA%A9m/Website%20Banner%20-%20RA.png', NULL, NULL, 1, 1, N'FiinRatings provides credit ratings, risk analysis, and independent verification and assessment of green bonds for issuers and investors in Vietnam.
Through independent and standardized assessments, FiinRatings serves as an objective reference in credit risk evaluation, contributing to greater transparency, efficiency, and the sustainable development of Vietnam’s capital market.', NULL);
INSERT INTO [dbo].[BannerItem] ([Id], [BannerId], [Name], [Href], [Target], [Content], [Template], [Banner], [Banner1], [Banner2], [Order], [Status], [Content1], [Content2]) VALUES (83, 57, N'Slide 2', N'#', N'_blank', N'Issuer-Pay and Investor-Pay Services', NULL, N'/Data/%E1%BA%A3nh%20s%E1%BA%A3n%20ph%E1%BA%A9m/%E1%BA%A3nh%20RA.jpg', NULL, NULL, 2, 1, N'FiinRatings’ Issuer-Pay services support Vietnamese companies in improving access to funding, diversifying financing options, and optimizing funding costs, while its Investor-Pay services help investors operate in Vietnam with confidence by strengthening internal credit assessments and enabling consistent benchmarking of credit quality across investment options.', NULL);
