INSERT INTO [dbo].[BannerItem] ([Id], [BannerId], [Name], [Href], [Target], [Content], [Template], [Banner], [Banner1], [Banner2], [Order], [Status], [Content1], [Content2]) VALUES (99, 62, N'BIDV', N'#', N'_blank', N'Following the initial second party opinion (SPO), we successfully issued VND 2,500 billion in green bonds and VND 3,000 billion in sustainability bonds in accordance with ICMA standards. Notably, BIDV’s Green Bond Allocation Report underwent an independent assessment by FiinRatings, confirming that the project selection and allocation of green bond proceeds fully complied with the guidelines outlined in the Green Bond Framework.', NULL, N'/Data/%E1%BA%A3nh%20s%E1%BA%A3n%20ph%E1%BA%A9m/Case%20study/bidv.png', N'/Data/%E1%BA%A3nh%20s%E1%BA%A3n%20ph%E1%BA%A9m/Logo%20kh%C3%A1ch%20h%C3%A0ng%20theo%20gi%E1%BA%A3i%20ph%C3%A1p/RA/BIDV%20Logo.png', NULL, 1, 1, N'Mr. Long Tran', N'Deputy CEO of BIDV');
INSERT INTO [dbo].[BannerItem] ([Id], [BannerId], [Name], [Href], [Target], [Content], [Template], [Banner], [Banner1], [Banner2], [Order], [Status], [Content1], [Content2]) VALUES (100, 62, N'BIWASE', N'#', N'_blank', N'The successful issuance of the VND 700 billion AAA-rated bond is a significant milestone in BIWASE Long An’s development, reaffirming company’s financial strength and commitment to sustainability. This achievement strengthens investor confidence and opens avenues for long-term capital mobilization to support clean water infrastructure and service. ', NULL, N'/Data/%E1%BA%A3nh%20s%E1%BA%A3n%20ph%E1%BA%A9m/Case%20study/biwase.png', N'/Data/%E1%BA%A3nh%20s%E1%BA%A3n%20ph%E1%BA%A9m/Logo%20kh%C3%A1ch%20h%C3%A0ng%20theo%20gi%E1%BA%A3i%20ph%C3%A1p/RA/Biwase.png', NULL, 2, 1, N'Mr. Duc Tan Tran', N'Deputy General Director of BIWASE');
INSERT INTO [dbo].[BannerItem] ([Id], [BannerId], [Name], [Href], [Target], [Content], [Template], [Banner], [Banner1], [Banner2], [Order], [Status], [Content1], [Content2]) VALUES (101, 62, N'Home Credit VN', N'#', N'_blank', N'The “A” rating with a stable outlook from FiinRatings - a strategic partner of S&P Global - reflects Home Credit Viet Nam’s journey to create sustainable and profitable growth. Thanks to the foundation of a solid balance sheet and best in class risk and data management, Home Credit Vietnam achieved its growth targets in 2024.', NULL, N'/Data/%E1%BA%A3nh%20s%E1%BA%A3n%20ph%E1%BA%A9m/Case%20study/homecredit.png', N'/Data/%E1%BA%A3nh%20s%E1%BA%A3n%20ph%E1%BA%A9m/Logo%20kh%C3%A1ch%20h%C3%A0ng%20theo%20gi%E1%BA%A3i%20ph%C3%A1p/RA/Homecredit.png', NULL, 3, 1, N'Mr. Pham Ngoc Khang', N'General Director of Home Credit Vietnam');
