INSERT INTO [dbo].[BannerItem] ([Id], [BannerId], [Name], [Href], [Target], [Content], [Template], [Banner], [Banner1], [Banner2], [Order], [Status], [Content1], [Content2]) VALUES (112, 67, N'Slide 1', N'https://fiingroup.vn/', N'_blank', N'FiinGroup - Đơn vị tiên phong cung cấp giải pháp công nghệ dữ liệu và phân tích tài chính', NULL, N'/Data/FR/Banner/Gioi-thieu-FG-Banner.png', NULL, NULL, 1, 1, N'Thành lập từ năm 2008, FiinGroup luôn kiên định với sứ mệnh nâng cao tính minh bạch và chất lượng ra quyết định trên thị trường. Từ nền tảng ban đầu là thị trường chứng khoán, FiinGroup không ngừng mở rộng phạm vi hoạt động sang các lĩnh vực trọng yếu như FDI, thị trường nợ và tín dụng, thương mại và các dòng giao dịch xuyên biên giới, phản ánh niềm tin rằng dữ liệu giá trị cần theo sát toàn bộ vòng đời của dòng vốn.', NULL);
INSERT INTO [dbo].[BannerItem] ([Id], [BannerId], [Name], [Href], [Target], [Content], [Template], [Banner], [Banner1], [Banner2], [Order], [Status], [Content1], [Content2]) VALUES (113, 67, N'Slide 2', N'https://fiingroup.vn/', N'_blank', N'Hệ sinh thái giải pháp phân tích và công nghệ dữ liệu tài chính của FiinGroup', NULL, N'/Data/FR/Banner/Gioi-thieu-FG-Banner.png', NULL, NULL, 2, 1, N'Hiện nay, FiinGroup vận hành như một nền tảng DataTech, đồng thời từng bước tiến tới mô hình AI-first. Hệ sinh thái của FiinGroup giúp các tổ chức và doanh nghiệp lớn điều hướng sự phức tạp của thị trường với sự rõ ràng, độ tin cậy và tốc độ cao hơn.
Được dẫn dắt bởi triết lý “Soi sáng thị trường”, FiinGroup không ngừng phát triển nhằm thúc đẩy tính minh bạch, niềm tin và việc ra quyết định có cơ sở. Từ dữ liệu đến trí tuệ, từ nhận định chuyên sâu đến hành động, FiinGroup là đối tác đáng tin cậy, hỗ trợ thị trường ra quyết định một cách sáng suốt.', NULL);
INSERT INTO [dbo].[BannerItem] ([Id], [BannerId], [Name], [Href], [Target], [Content], [Template], [Banner], [Banner1], [Banner2], [Order], [Status], [Content1], [Content2]) VALUES (114, 68, N'Slide 1', N'https://fiingroup.vn/en', N'_blank', N'FiinGroup - A pioneer in data analytics and data technology solutions', NULL, N'/Data/FR/Banner/Gioi-thieu-FG-Banner.png', NULL, NULL, 1, 1, N'Founded in 2008, FiinGroup has remained steadfast in its mission to enhance market transparency and improve the quality of decision-making. Building on its initial foundation in the securities market, FiinGroup has continuously expanded its scope of operations to cover key areas such as foreign direct investment (FDI), debt and credit markets, trade, and cross-border transaction flows - reflecting a strong belief that valuable data and analytics should accompany the entire lifecycle of capital.', NULL);
INSERT INTO [dbo].[BannerItem] ([Id], [BannerId], [Name], [Href], [Target], [Content], [Template], [Banner], [Banner1], [Banner2], [Order], [Status], [Content1], [Content2]) VALUES (115, 68, N'Slide 2', N'https://fiingroup.vn/en', N'_blank', N'FiinGroup’s financial data analytics and data technology solutions ecosystem', NULL, N'/Data/FR/Banner/Gioi-thieu-FG-Banner.png', NULL, NULL, 2, 1, N'Today, FiinGroup operates as a DataTech platform, steadily advancing toward an AI-first model. Our ecosystem enables institutions and enterprises to navigate complexity with greater clarity, reliability, and speed.

Guided by the philosophy of “Enlighten the market,” FiinGroup continues to evolve to advance transparency, trust, and informed decision-making. From data to intelligence, and from insight to action, FiinGroup is a trusted enabler of informed decision-making in the market.', NULL);
