INSERT INTO [dbo].[ContentPage] ([Id], [ServiceId], [CategoryId], [Name], [Summary], [Content], [Banner], [Language], [Type], [Author], [DatePosted], [Status], [Price], [IsHome], [StartDate], [EndDate], [PortalId], [Times], [Address], [Pages], [Extentions], [FilePath], [DeliveryTime], [IsSale], [Topic], [CategoryType], [SlugType], [TimeFromTo], [Input1], [Input2], [Input3], [Input4], [Input5], [Input6], [Input8], [Input7], [Input9], [Input10], [Input11], [Input12], [IsShowHeaderContent], [Order], [NewsId], [Input13], [Input14], [Input15]) VALUES (10074, 0, 2076, N'test event bản full', NULL, N'<main role="main" class="new-layout"><div class="event"><div class="new-event"><!--Hero Event Banner (Single)-->

<div class="hero section d-md-block d-none" style="background-image: url(https://cdn.fiingroup.vn/medialib/261746/F/2025/07/01/15155858203640700_August-22_Event-1.png);background-position: center;">
    <div class="container px-24 d-flex flex-column h-100">
        <div class="row">
            <div class="col-md-8 col">
                <h1 class="mb-24 fw-bold" style="font-size: 32px; color: #fff">
                    Vietnam Debt Capital Market Forum 2025:<br>Financing the Private Sector for a New Era of Growth
                </h1>
            </div>
            <div class="col-md-7 col">
                <p class="mb-16 event-paragraph" style="text-align: justify;font-size: 15px;font-weight: 500;color: #fff;">
                    Building on the success of the Vietnam Debt Capital Market Forum 2024, FiinRatings – A Strategic Partner of S&P Global – is pleased to co-host the upcoming event in collaboration with the Credit Guarantee and Investment Facility (CGIF), a trust fund of the Asian Development Bank (ADB): "Vietnam Debt Capital Market Forum 2025: Financing the Private Sector for a New Era of Growth".
                    <br><br>
                    As Resolution No. 68-NQ/TW positions the private sector as a key driver of economic growth, the expansion of medium- and long-term funding channels beyond the banking system is now recognized as a strategic imperative. New regulations on credit ratings, private placements, and information transparency are gradually shaping a more standardized and sustainable capital market.
                    <br><br>
                    Vietnam Capital Market Forum 2025 is a high-level platform gathering policymakers, investors, issuers, and both domestic and international experts to exchange insights and co-develop solutions for advancing Vietnam''s debt capital market in a more sound, efficient, and sustainable manner. The event also aims to strengthen the financial capacity and resilience of Vietnamese enterprises, contributing to the realization of Vietnam''s economic growth objectives in this new era of growth.
                </p>

                <p class="mb-16" style="font-size: 16px; font-weight: 500; color: #fff">
                    Time: 8:00 AM – 12:00 PM ICT, Friday, August 22, 2025<br>Venue: Sofitel Saigon Plaza Hotel, Ho Chi Minh City, Vietnam<br>
                </p>
            </div>
        </div>

        <div class="flex-fill d-flex flex-column justify-content-end">
            <div class="mb-16">
                <a class="white-button d-inline-block text-uppercase" href="https://forms.office.com/r/hC7HbFxEVe">Register now</a>
            </div>
        </div>
    </div>
</div>

<script>

        $(document).ready(function () {
            //let countDownDate = new Date(2024, 10, 20, 8, 50).getTime();
            let countDownDate = new Date(''2024-11-18T10:00:00'').getTime();
            console.log(countDownDate);
            let $now = new Date().getTime();
            if ($now > countDownDate) {
                $(''#countdown'').addClass(''d-none'');
                return;
            };
            // Find the distance between now and the count down date
            let $distance = countDownDate - $now;

            // Time calculations for days, hours, minutes and seconds
            let $days = Math.floor($distance / (1000 * 60 * 60 * 24));
            let $hours = Math.floor(($distance % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
            let $minutes = Math.floor(($distance % (1000 * 60 * 60)) / (1000 * 60));
            let $seconds = Math.floor(($distance % (1000 * 60)) / 1000);

            // Display the result in the element with id="demo"
            $(''#countdown .days'').text($days);
            $(''#countdown .hours'').text($hours);
            $(''#countdown .minutes'').text($minutes);
            $(''#countdown .seconds'').text($seconds);
            // Update the count down every 1 second
            var x = setInterval(function () {

                // Get today''s date and time
                var now = new Date().getTime();

                // Find the distance between now and the count down date
                var distance = countDownDate - now;

                // Time calculations for days, hours, minutes and seconds
                var days = Math.floor(distance / (1000 * 60 * 60 * 24));
                var hours = Math.floor((distance % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
                var minutes = Math.floor((distance % (1000 * 60 * 60)) / (1000 * 60));
                var seconds = Math.floor((distance % (1000 * 60)) / 1000);

                // Display the result in the element with id="demo"
                $(''#countdown .days'').text(days);
                $(''#countdown .hours'').text(hours);
                $(''#countdown .minutes'').text(minutes);
                $(''#countdown .seconds'').text(seconds);

                // If the count down is finished, write some text
                if (distance < 0) {
                    clearInterval(x);
                    document.getElementById("demo").innerHTML = "EXPIRED";
                }
            }, 1000);
        });

    </script>

