INSERT INTO [dbo].[ContentPageRelated] ([Id], [ParentId], [ContentPageId], [Order], [Note]) VALUES (12, 6, 7, 1, N'Cung cấp cơ sở dữ liệu tài chính chuyên sâu và toàn diện, được thiết kế dành riêng cho các nhà nghiên cứu, chuyên viên phân tích và tổ chức đầu tư chuyên nghiệp.');
INSERT INTO [dbo].[ContentPageRelated] ([Id], [ParentId], [ContentPageId], [Order], [Note]) VALUES (13, 6, 8, 2, N'Cung cấp dữ liệu chứng khoán trực tuyến cùng phân tích dữ liệu chuyên sâu thị trường Việt Nam cho chuyên viên môi giới, giao dịch viên và nhà đầu tư chuyên nghiệp.');
INSERT INTO [dbo].[ContentPageRelated] ([Id], [ParentId], [ContentPageId], [Order], [Note]) VALUES (14, 6, 9, 3, N'Giúp truy cập, xử lý và phân tích dữ liệu thị trường Việt Nam nhanh chóng, chính xác và linh hoạt. Được thiết kế riêng cho nhà đầu tư/phân tích và lập trình viên tài chính.');
INSERT INTO [dbo].[ContentPageRelated] ([Id], [ParentId], [ContentPageId], [Order], [Note]) VALUES (15, 6, 10, 4, N'Cung cấp dữ liệu chuẩn hóa, cập nhật nhanh và chính xác, dễ dàng tích hợp vào hệ thống nội bộ và nền tảng tài chính số cho Ngân hàng, CTCK, Quỹ, Bảo hiểm và Fintech.');
INSERT INTO [dbo].[ContentPageRelated] ([Id], [ParentId], [ContentPageId], [Order], [Note]) VALUES (16, 24, 15, 1, N'Báo cáo ngành cung cấp thông tin toàn diện, phân tích sâu về các lĩnh vực trọng điểm tại Việt Nam, hỗ trợ đánh giá sức hấp dẫn và tiềm năng thị trường.');
INSERT INTO [dbo].[ContentPageRelated] ([Id], [ParentId], [ContentPageId], [Order], [Note]) VALUES (17, 24, 16, 2, N'Nghiên cứu chuyên sâu theo yêu cầu của khách hàng trong hơn 50 lĩnh vực nghiên cứu và ngành nghề tại Việt Nam, hỗ trợ các quyết định kinh doanh, mở rộng và am hiểu thị trường.');
INSERT INTO [dbo].[ContentPageRelated] ([Id], [ParentId], [ContentPageId], [Order], [Note]) VALUES (19, 27, 11, 8, N'Hỗ trợ các ngân hàng giải quyết hiệu quả bài toán tiếp cận, thẩm định, giám sát khách hàng doanh nghiệp một cách nhanh chóng, chính xác và tiết kiệm nguồn lực.');
INSERT INTO [dbo].[ContentPageRelated] ([Id], [ParentId], [ContentPageId], [Order], [Note]) VALUES (20, 27, 19, 5, N'Đánh giá mức độ xếp hạng tín nhiệm của ngân hàng và các công cụ nợ, giúp nâng cao uy tín, minh bạch và mở rộng tiếp cận nhà đầu tư trong và ngoài nước.');
INSERT INTO [dbo].[ContentPageRelated] ([Id], [ParentId], [ContentPageId], [Order], [Note]) VALUES (21, 27, 9, 4, N'Xây dựng các hệ thống phân tích tự động, dashboard real-time, mô hình đầu tư định lượng hoặc chiến lược giao dịch theo thuật toán.');
INSERT INTO [dbo].[ContentPageRelated] ([Id], [ParentId], [ContentPageId], [Order], [Note]) VALUES (23, 27, 10, 3, N'Cung cấp thông tin dữ liệu thị trường hằng ngày với dữ liệu chính xác và cập nhật nhanh chóng, đặc biệt hỗ trợ đắc lực cho các Ngân hàng lưu ký - giám sát.');
INSERT INTO [dbo].[ContentPageRelated] ([Id], [ParentId], [ContentPageId], [Order], [Note]) VALUES (26, 25, 22, 2, N'Chấm điểm rủi ro doanh nghiệp là công cụ hữu ích cho thẩm định tín dụng, quản trị rủi ro và đánh giá nhà cung cấp, khách hàng, đối tác.');
INSERT INTO [dbo].[ContentPageRelated] ([Id], [ParentId], [ContentPageId], [Order], [Note]) VALUES (27, 26, 12, 2, N'Cung cấp đánh giá chuyên sâu về hồ sơ doanh nghiệp, sức khỏe tài chính và hoạt động kinh doanh​.');
INSERT INTO [dbo].[ContentPageRelated] ([Id], [ParentId], [ContentPageId], [Order], [Note]) VALUES (28, 26, 13, 3, N'Giúp các doanh nghiệp B2B xác định chính xác được tệp khách hàng tiềm năng dựa trên khu vực, ngành nghề, quy mô công ty, và nhiều yếu tố khác.');
INSERT INTO [dbo].[ContentPageRelated] ([Id], [ParentId], [ContentPageId], [Order], [Note]) VALUES (29, 25, 19, 1, N'Cung cấp đánh giá mức độ xếp hạng tín nhiệm của tổ chức phát hành và các công cụ nợ, giúp nâng cao uy tín, minh bạch và mở rộng tiếp cận nhà đầu tư trong và ngoài nước.');
INSERT INTO [dbo].[ContentPageRelated] ([Id], [ParentId], [ContentPageId], [Order], [Note]) VALUES (31, 27, 7, 1, N'Hỗ trợ phân tích tài chính, tự động cảnh báo sớm rủi ro tín dụng, đánh giá rủi ro ngành & hệ thống với dữ liệu thị trường real-time.');
INSERT INTO [dbo].[ContentPageRelated] ([Id], [ParentId], [ContentPageId], [Order], [Note]) VALUES (33, 27, 23, 9, N'Cung cấp dữ liệu giúp số hóa quy trình tín dụng, quản lý rủi ro.');
INSERT INTO [dbo].[ContentPageRelated] ([Id], [ParentId], [ContentPageId], [Order], [Note]) VALUES (34, 27, 22, 10, N'Chỉ số đánh giá rủi ro tổng thể doanh nghiệp, công cụ hữu ích cho thẩm định tín dụng, quản trị rủi ro và đánh giá nhà cung cấp, khách hàng, đối tác.​');
INSERT INTO [dbo].[ContentPageRelated] ([Id], [ParentId], [ContentPageId], [Order], [Note]) VALUES (35, 27, 15, 11, N'Báo cáo ngành cung cấp thông tin toàn diện, phân tích sâu về các lĩnh vực trọng điểm tại Việt Nam, hỗ trợ đánh giá sức hấp dẫn và tiềm năng thị trường.');
INSERT INTO [dbo].[ContentPageRelated] ([Id], [ParentId], [ContentPageId], [Order], [Note]) VALUES (36, 6, 21, 5, N'Dịch vụ tính giá trị thị trường trái phiếu doanh nghiệp với lợi thế từ nguồn dữ liệu lớn, đội ngũ giàu chuyên môn, áp dụng phương pháp luận tiêu chuẩn, đáp ứng tiêu chuẩn Việt Nam và Quốc tế.');
INSERT INTO [dbo].[ContentPageRelated] ([Id], [ParentId], [ContentPageId], [Order], [Note]) VALUES (37, 24, 18, 4, N'Đồng hành cùng khách hàng trong toàn bộ quy trình M&A – từ đánh giá cơ hội, tìm kiếm đối tác đến triển khai giao dịch – nhằm tối ưu hoá giá trị thương vụ và kiểm soát rủi ro hiệu quả.');
INSERT INTO [dbo].[ContentPageRelated] ([Id], [ParentId], [ContentPageId], [Order], [Note]) VALUES (39, 35, 11, 1, N'Cung cấp thông tin chi tiết về doanh nghiệp, hỗ trợ tư vấn cho các tổ chức bảo hiểm tín dụng trong quá trình thẩm định và đánh giá rủi ro.');
INSERT INTO [dbo].[ContentPageRelated] ([Id], [ParentId], [ContentPageId], [Order], [Note]) VALUES (40, 35, 22, 4, N'Hỗ trợ thẩm định tín dụng của doanh nghiệp và nhận cảnh báo sớm khi có biến động về rủi ro tín dụng, giúp tối ưu hiệu suất và hạn chế rủi ro đầu tư.');
INSERT INTO [dbo].[ContentPageRelated] ([Id], [ParentId], [ContentPageId], [Order], [Note]) VALUES (41, 26, 11, 1, N'Tìm kiếm và phân tích hồ sơ doanh nghiệp, cơ cấu cổ đông, công ty liên quan, thông tin báo cáo tài chính, báo cáo phân tích tự động trên cơ cơ sở dữ liệu minh bạch​.');
INSERT INTO [dbo].[ContentPageRelated] ([Id], [ParentId], [ContentPageId], [Order], [Note]) VALUES (42, 26, 14, 4, N'Phân tích xu hướng của ngành, so sánh hiệu suất của công ty với ngành và tìm kiếm cơ hội kinh doanh giữa các ngành.');
INSERT INTO [dbo].[ContentPageRelated] ([Id], [ParentId], [ContentPageId], [Order], [Note]) VALUES (44, 25, 23, 3, N'Quyền truy cập vào dữ liệu kinh doanh mới nhất được thu thập từ các nguồn đáng tin cậy, bạn có thể đưa ra quyết định một cách nhanh chóng.');
INSERT INTO [dbo].[ContentPageRelated] ([Id], [ParentId], [ContentPageId], [Order], [Note]) VALUES (45, 30, 7, 1, N'Cung cấp cho bộ phận phân tích, môi giới và IB dữ liệu vĩ mô, ngành, doanh nghiệp niêm yết; xây mô hình định giá, khuyến nghị và tư vấn đầu tư. Hỗ trợ tư vấn phát hành và đầu tư trái phiếu, định giá, phục vụ hoạt động IB và quản trị rủi ro.');
INSERT INTO [dbo].[ContentPageRelated] ([Id], [ParentId], [ContentPageId], [Order], [Note]) VALUES (47, 30, 10, 3, N'Tích hợp dữ liệu thời gian thực vào hệ thống BI, CRM, trading platform; tự động hóa báo cáo, tối ưu vận hành và hạn chế sai lệch thủ công.');
INSERT INTO [dbo].[ContentPageRelated] ([Id], [ParentId], [ContentPageId], [Order], [Note]) VALUES (48, 30, 9, 4, N'Thư viện dữ liệu chứng khoán chuyên sâu giúp xây dựng hệ thống phân tích, mô hình đầu tư định lượng và chiến lược giao dịch theo thuật toán.');
INSERT INTO [dbo].[ContentPageRelated] ([Id], [ParentId], [ContentPageId], [Order], [Note]) VALUES (49, 30, 19, 5, N'Đánh giá mức độ xếp hạng tín nhiệm của công ty chứng khoán và các công cụ nợ, giúp nâng cao uy tín, minh bạch và tối ưu khả năng huy động vốn trên thị trường.');
INSERT INTO [dbo].[ContentPageRelated] ([Id], [ParentId], [ContentPageId], [Order], [Note]) VALUES (50, 30, 11, 8, N'Cung cấp thông tin toàn diện về doanh nghiệp, giúp phân tích tài chính, xác định triển vọng và hỗ trợ chiến lược đầu tư của công ty chứng khoán.');
INSERT INTO [dbo].[ContentPageRelated] ([Id], [ParentId], [ContentPageId], [Order], [Note]) VALUES (51, 32, 7, 1, N'Cung cấp dữ liệu chi tiết về các doanh nghiệp niêm yết và thị trường trái phiếu, hỗ trợ đánh giá cơ hội đầu tư, quản lý danh mục và phân tích rủi ro.');
INSERT INTO [dbo].[ContentPageRelated] ([Id], [ParentId], [ContentPageId], [Order], [Note]) VALUES (53, 32, 10, 3, N'Cho phép quỹ quản lý tài sản tích hợp dữ liệu thị trường thời gian thực, tối ưu hóa việc quản lý danh mục đầu tư và đưa ra quyết định nhanh chóng.');
INSERT INTO [dbo].[ContentPageRelated] ([Id], [ParentId], [ContentPageId], [Order], [Note]) VALUES (54, 32, 11, 6, N'Cung cấp thông tin chi tiết về các doanh nghiệp, phục vụ tư vấn về chiến lược đầu tư, phát triển và chuyển đổi doanh nghiệp.');
INSERT INTO [dbo].[ContentPageRelated] ([Id], [ParentId], [ContentPageId], [Order], [Note]) VALUES (55, 27, 46, 6, N'Phân tích và giám sát độc lập danh mục đầu tư hoặc cho vay, giúp ngân hàng nhận diện sớm rủi ro, chuẩn hóa mô hình quản trị và nâng cao hiệu quả tín dụng.');
INSERT INTO [dbo].[ContentPageRelated] ([Id], [ParentId], [ContentPageId], [Order], [Note]) VALUES (56, 27, 47, 7, N'Đánh giá độc lập các công cụ tài chính bền vững, khung công cụ và giao dịch vốn nợ theo chuẩn quốc tế (ICMA/CBI), hỗ trợ ngân hàng huy động vốn dài hạn.');
