INSERT INTO [dbo].[ContentPageRelated] ([Id], [ParentId], [ContentPageId], [Order], [Note]) VALUES (70, 28, 19, 4, N'Đánh giá mức độ xếp hạng tín nhiệm của doanh nghiệp FDI và các công cụ nợ, giúp nâng cao minh bạch, đáp ứng yêu cầu của ngân hàng và đối tác, đồng thời mở rộng khả năng huy động vốn tại Việt Nam.');
