INSERT INTO [dbo].[Menu] ([Id], [Code], [Name], [Template], [Template1], [Template2], [Template3], [HasChildrentClass1], [HasChildrentClass2], [HasChildrentClass3], [Status], [Delete], [Language], [Content], [PortalId]) VALUES (4, N'MenuMobile', N'Menu Mobile', N'<div class="modal fade" id="menumore" role="dialog">
    <div class="modal-dialog">
        <div class="modal-content">
            <div class="modal-header">
                <h4 class="modal-title">Finngroup</h4>
                <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close"></button>
            </div>
            <div class="modal-body">
                <div class="mobile-menu">
                    <ul class="menu-level-1">
                         [Content]
                    </ul>
                </div>
                <style>
                    .mobile-menu {
                        width: 100%;
                        color: #fff;
                        font-family: Arial, sans-serif;
                    }
                    .menu-header {
                        padding: 15px;
                        background: #1abc9c;
                        font-size: 18px;
                        font-weight: bold;
                        cursor: pointer;
                    }
                    .mobile-menu ul {
                        list-style: none;
                        margin: 0;
                        padding: 0;
                    }

                    .mobile-menu li {
                        border-bottom: 1px solid rgba(255,255,255,0.1);
                    }

                    .mobile-menu a {
                        color: #fff;
                        padding: 14px 0px;
                        display: flex;
                        justify-content: space-between;
                        text-decoration: none;
                    }

                    /* Sub menu */
                    .menu-level-2{
                        padding: 0 0 0 15px !important;
                    }
                    .menu-level-3 {
                        padding: 0 0 0 30px !important;
                    }
                    .menu-level-2,
                    .menu-level-3 {
                        display: none;
                        background: #34495e;
                    }

                    .menu-level-3 {
                        background: #3b5770;
                    }
                    .has-sub > a::after {
                        content: "›";
                        transform: rotate(90deg);
                    }
                </style>
                <script>
                    document.querySelectorAll(''.has-sub > a'').forEach(item => {
                        item.addEventListener(''click'', function (e) {
                            e.preventDefault();
                            const submenu = this.nextElementSibling;

                            submenu.style.display =
                                submenu.style.display === ''block'' ? ''none'' : ''block'';
                        });
                    });
                </script>
            </div>
        </div>
    </div>
</div>', N'[For] 
