INSERT INTO [dbo].[StaticInformation] ([Id], [Name], [Content], [Status], [Language], [Delete], [ParentId], [Code], [Data], [PortalId]) VALUES (1024, N'Product - FiinPro-X Có Gì', N'<section id="FiinProX">
