INSERT INTO [dbo].[StaticInformation] ([Id], [Name], [Content], [Status], [Language], [Delete], [ParentId], [Code], [Data], [PortalId]) VALUES (1027, N'Product - Nền tảng', N'<section id="FiinCard">
    <style>
        .box-card {
            text-align: center;
            align-items: center;
        }

        .box-left,
        .box-right {
            background-color: #fafbfe;
            border-radius: 15px;
            padding: 55px;
            box-shadow: 0 4px 8px #0000001a;
            text-align: center;
            margin: 45px 0;
            transition: transform 0.3s;
        }

        .box-center {
            position: relative;
            border-radius: 15px;
            background-color: #fff;
            padding: 50px;
            text-align: center;
            box-shadow: 0 4px 8px #0000001a;
            overflow: hidden;
        }

        .box-center::before {
            content: "";
            position: absolute;
            inset: 0;
            border-radius: 15px;
            padding: 2px;
            /* độ dày border */
            background: linear-gradient(to right, #034EA2, #53DFFF);
            -webkit-mask:
                linear-gradient(#fff 0 0) content-box,
                linear-gradient(#fff 0 0);
            -webkit-mask-composite: xor;
            mask-composite: exclude;
            pointer-events: none;
        }

        .box-left:hover,
        .box-center:hover,
        .box-right:hover {
            transform: translateY(-5px);
        }

        .tilte-card {
            font-size: 23px;
            font-weight: bold;
            color: #0066CC;
            margin-bottom: 10px;
        }

        .tilte-card-center {
            font-size: 28px;
            font-weight: bold;
            color: #0066CC;
            margin-bottom: 10px;
        }

        .money-card {
            font-size: 30px;
            color: #80b3e5;
            margin-bottom: 5px;
        }

        .number-card {
            color: #0066CC;
            font-weight: 600;
        }

        .id-card {
            font-size: 15px;
            color: #1D2939;
            margin-bottom: 20px;
            text-align: right;
            padding: 0 20px;
        }

        .id-card-center {
            font-size: 15px;
            color: #1D2939;
            margin-bottom: 20px;
            text-align: right;
            padding: 0px 15px;
        }

        .noted-card {
            border-radius: 8px;
        }

        .feature-item {
            display: flex;
            align-items: flex-start;
            margin-bottom: 10px;
        }

        .feature-item i.fas.fa-check-circle {
            color: #28a745;
            margin-right: 15px;
            font-size: 16px;
            line-height: 1;
        }

        .feature-item span {
            color: #000;
            font-size: 12px;
            line-height: 1.5;
            text-align: left;
        }

        .feature-item span span {
            color: #1D2939;
            font-weight: bold;
        }

        .fa.fa-check-circle {
            color: #28a745;
            margin-right: 8px;
            padding-top: 5px;
            text-align: left;
        }

        .dang-ky-card {
            background-color: #ffffff;
            color: #0066cc;
            padding: 7px 70px;
            border-radius: 25px;
            cursor: pointer;
            margin-top: 20px;
            display: inline-block;
            border: 1px solid #0066cc;
        }

        .dang-ky-card-center {
            background-color: #0066cc;
            color: #ffffff;
            padding: 7px 70px;
            border-radius: 25px;
            cursor: pointer;
            display: inline-block;
        }


        .box-center img {
            max-width: 165px;
            margin: 0 50px auto;
        }

        .box-center .corner-decor {
            position: absolute;
            top: 0;
            right: -50px;
            width: 70px;
            height: auto;
            pointer-events: none;
            opacity: 1;
            transition: opacity 0.3s ease-in-out;
            z-index: 2;
        }

        .box-center:hover .corner-decor {
            opacity: 1;
        }
    </style>
    <div class="container">
        <div class="row box-card">
            <div class="col-sm-4">
                <div class="box-left">
                    <div class="tilte-card">Nền tảng FinnPro-X</div>
                    <div class="money-card"><span class="number-card">9.000.000</span> VND</div>
                    <div class="id-card">ID/tháng</div>
                    <div class="noted-card">
                        <div class="feature-item">
                            <i class="fa fa-check-circle"></i>
                            <span>Dữ liệu giao dịch <span style="color: #1D2939;">theo thời gian thực</span> &
                                lịch
                                sử, kinh tế vĩ mô Việt Nam, tin tức cập nhật</span>
                        </div>
                        <div class="feature-item">
                            <i class="fa fa-check-circle"></i>
                            <span>Thông tin của <span style="color: #1D2939;">hơn 3.500 doanh nghiệp </span>
                                niêm
                                yết trên HOSE, HNX, UPCoM, OTC và hơn 500 doanh nghiệp tư nhân</span>
                        </div>
                        <div class="feature-item">
                            <i class="fa fa-check-circle"></i>
                            <span>Công cụ lọc cổ phiếu <span style="color: #1D2939;">thông minh</span>, biểu đồ
                                tài
                                chính <span style="color: #1D2939;">mạnh mẽ</span></span>
                        </div>
                    </div>
                    <div class="dang-ky-card">
                        Đăng ký ngay
                    </div>
                </div>
            </div>
            <div class="col-sm-4">
                <div class="box-center">
                    <img src="../Data/product_right2.png" alt="Decor" class="corner-decor">
                    <div class="tilte-card-center">FinnPro-X & <br /> Báo cáo Trái Phiếu</div>
                    <div class="money-card"><span class="number-card">12.900.000</span> VND</div>
                    <div class="id-card-center">ID/tháng</div>
                    <div class="noted-card">
                        <div class="feature-item">
                            <i class="fa fa-check-circle"></i>
                            <span><span style="color: #1D2939;">Truy cập không giới
                                    hạn</span> vào toàn bộ bộ dữ
                                liệu và công cụ chuyên sâu, bao gồm nền tảng FiinPro-X và Bond Portal.</span>
                        </div>
                    </div>
                    <div>
                        <img src="../Data/product_robot.png" class="d-block w-100" alt="Báo cáo Trái phiếu" />
                    </div>
                    <div class="dang-ky-card-center">
                        Đăng ký ngay
                    </div>
                </div>
            </div>
            <div class="col-sm-4">
                <div class="box-right">
                    <div class="tilte-card">Báo cáo Trái phiếu</div>
                    <div class="money-card"><span class="number-card">4.900.000</span> VND</div>
                    <div class="id-card">ID/tháng</div>
                    <div class="noted-card">
                        <div class="feature-item">
                            <i class="fa fa-check-circle"></i>
                            <span><span style="color: #1D2939;">Cập nhật hàng
                                    ngày</span>: Tổng quan thị trường
                                phát hành, mua lại, trả lãi, đáo hạn</span>
                        </div>
                        <div class="feature-item">
                            <i class="fa fa-check-circle"></i>
                            <span>Công cụ định giá trái phiếu <span style="color: #1D2939;">chuyên
                                    nghiệp</span></span>
                        </div>
                    </div>
                    <div class="dang-ky-card" style="margin-top:90px">
                        Đăng ký ngay
                    </div>
                </div>
            </div>
        </div>

    </div>
</section>', 1, N'vi', 1, 0, N'ProductNenTang', NULL, 2);
