INSERT INTO [dbo].[StaticInformation] ([Id], [Name], [Content], [Status], [Language], [Delete], [ParentId], [Code], [Data], [PortalId]) VALUES (1029, N'Solution - FiinGroup thấu hiểu', N'<section id="FiinGroup">
            <style>
                .navbarfin {
                    padding: 50px 0;
                }

                .navbarfin a {
                    color: #093461;
                    text-decoration: none;
                    font-size: 18px;
                    padding: 5px 40px;
                    transition: color 0.3s;
                    cursor: pointer;
                }

                .navbarfin a.active {
                    color: #0066CC;
                    border-bottom: 3px solid #093461;
                }

                .box-fingroup {
                    position: relative;
                    border-radius: 15px;
                    margin: 10px 0;
                    box-shadow: 0 4px 8px #0000001a;
                    transition: transform 0.3s;
                    max-width: 31%;
                    min-width: 350px;

                    /* border gradient bo góc mượt */
                    border: 1px solid transparent;
                    background-image: linear-gradient(#f5f9ff, #f2f7ff), 
                      linear-gradient(to right, #E6E6E600, #034EA2);
                    background-origin: border-box;
                    background-clip: padding-box, border-box;
                }

                .box-fingroup:hover {
                    transform: translateY(-5px);
                }
            </style>
            <div class="container">
