INSERT INTO [dbo].[StaticInformation] ([Id], [Name], [Content], [Status], [Language], [Delete], [ParentId], [Code], [Data], [PortalId]) VALUES (1030, N'Solution - Giải pháp hỗ trợ', N' <section id="GiaiPhap" class="py-5">
            <style>
                .overlay-card {
                    position: relative;
                    overflow: hidden;
                    border-radius: 12px;
                    cursor: pointer;
                    transition: transform 0.3s ease;
                }

                .overlay-card:hover {
                    transform: translateY(-5px);
                }

                .overlay-card .card-img {
                    width: 100%;
                    height: 100%;
                    object-fit: cover;
                    display: block;
                    filter: brightness(0.6);
                    transition: filter 0.3s ease;
                    border-radius: 12px;
                    height: 240px;
                    width: 330px !important;
                }

                .overlay-card:hover .card-img {
                    filter: brightness(0.8);
                }

                .overlay-card .card-content {
                    position: absolute;
                    top: 0;
                    left: 0;
                    color: #fff;
                    padding: 25px;
                    width: 100%;
                    height: 100%;
                    display: flex;
                    flex-direction: column;
                    justify-content: space-between;
                }

                .overlay-card h3 {
                    font-size: 20px;
                    font-weight: 700;
                    margin: 0;
                }

                .overlay-card p {
                    font-size: 15px;
                    margin: 0 0 100px;
                    opacity: 0.9;
                    max-width: 75%;
                }

                .overlay-card .show-more {
                    color: #fff;
                    font-weight: 500;
                    font-size: 14px;
                    text-decoration: none;
                    display: inline-flex;
                    align-items: center;
                    gap: 5px;
                    transition: all 0.3s ease;
                }

                .overlay-card .show-more i {
                    transition: transform 0.3s ease;
                }

                .overlay-card .show-more:hover i {
                    transform: translateX(4px);
                }

                #GiaiPhap .show-more i {
                    color: #fff !important;
                }
                
            </style>
            <div class="container">
                <h2 class="price-title mb-5">Giải pháp hỗ trợ <span style="color: #0066CC;"> từ FiinGroup</span>
                </h2>
                <div class="owl-carousel owl-theme" id="owlour">
                    <div class="item">
                        <div class="overlay-card">
                            <img src="../Data/solution_giaiphap1.png" alt="FiinPro-X" class="card-img">
                            <div class="card-content">
                                <h3>FiinPro-X</h3>
                                <p>Nền tảng Dữ liệu Tài chính và Cổng thông tin Trái phiếu</p>
                                <a href="#" class="show-more">Show more <i class="fas fa-arrow-right"></i></a>
                            </div>
                        </div>

                    </div>
                    <div class="item">
                        <div class="overlay-card">
                            <img src="../Data/solution_giaiphap2.png" alt="Bond Pricing" class="card-img">
                            <div class="card-content">
                                <h3>Bond Pricing</h3>
                                <p>Dịch vụ tính giá trái phiếu</p>
                                <a href="#" class="show-more">Show more <i class="fas fa-arrow-right"></i></a>
                            </div>
                        </div>
                    </div>
                    <div class="item">
                        <div class="overlay-card">
                            <img src="../Data/solution_giaiphap3.png" alt="Bond Pricing" class="card-img">
                            <div class="card-content">
                                <h3>API Datafeed</h3>
                                <p>Giải pháp Dữ liệu Chứng khoán​</p>
                                <a href="#" class="show-more">Show more <i class="fas fa-arrow-right"></i></a>
                            </div>
                        </div>
                    </div>
                    <div class="item">
                        <div class="overlay-card">
                            <img src="../Data/solution_giaiphap4.png" alt="Bond Pricing" class="card-img">
                            <div class="card-content">
                                <h3>FiinQuant</h3>
                                <p>Thư viện dữ liệu Chứng khoán bằng ngôn ngữ Python</p>
                                <a href="#" class="show-more">Show more <i class="fas fa-arrow-right"></i></a>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
            <script>
                $("#owlour").owlCarousel({
                    items: 4,
                    loop: true,
