INSERT INTO [dbo].[StaticInformation] ([Id], [Name], [Content], [Status], [Language], [Delete], [ParentId], [Code], [Data], [PortalId]) VALUES (1037, N'AboutUs - UserTeam', N'  <section id="UserTeam" class="py-5">
            <style>
                .price-title {
                    margin-bottom: 20px;
                }

                .tab-container {
                    display: inline-flex;
                    justify-content: center;
                    border: 1px solid #0078d4;
                    border-radius: 6px;
                    overflow: hidden;
                    font-family: Arial, sans-serif;
                    font-size: 14px;
                }

                .tab {
                    padding: 8px 20px;
                    border: none;
                    background: white;
                    color: #0078d4;
                    cursor: pointer;
                    transition: all 0.2s ease;
                    min-width: 250px;
                }

                .tab.active {
                    background: #0078d4;
                    color: white;
                }

                .tab:not(.active):hover {
                    background: #e6f0fb;
                }

                /* Team Grid */

                .team-grid {
                    display: grid;
                    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
                    gap: 30px;
                    justify-content: center;
                    align-items: start;
                }

                .member-card {
                    align-items: center;
                    text-align: center;
                    padding: 15px;
                    border-radius: 16px;
                    overflow: hidden;
                    transition: transform 0.3s ease, box-shadow 0.3s ease;
                    width: 100%;
                    height: 100%;
                    /* border gradient bo góc mượt */
                    border: 1px solid transparent;
                }

                .member-card:hover {
                    transform: translateY(-8px);
                    box-shadow: 0 12px 24px rgba(0, 0, 0, 0.12);
                }

                .member-card img {
                    max-width: 100%;
                }

                .member-info {
                    padding: 26px 0;
                    text-align: left;
                }

                .member-name {
                    font-size: 19px;
                    font-weight: 600;
                    color: #0066CC;
                    margin-bottom: 6px;
                }

                .member-title {
                    font-size: 16px;
                    font-weight: 500;
                }
              
              	.member-desc {
                    margin-top: 10px;
                    text-align: justify;
                    font-style: italic;
                }
            </style>

            <div class="container">
                <h2 id="team-title" style="text-align: center;" class="price-title mb-5">Đội ngũ quản lý</h2>
                <div style="text-align: center;">
                    <div class="tab-container mb-5">
                        <button class="tab active">Hội đồng quản trị</button>
                        <button class="tab">Ban điều hành</button>
                    </div>
                </div>
                <!-- Hội đồng quản trị -->
                <div id="hdqt" class="tab-content">
                    <div class="team-grid">
                        <div class="member-card">
                            <img src="../Data/Banner/about_us1.png" alt="why" />
                            <div class="member-info">
                                <div class="member-name">Nguyễn Quang Thuân, MBA, FCCA</div>
                                <div class="member-title">Chủ tịch HĐQT</div>
                              	<div class="member-desc">
                                  Đồng sáng lập FiinGroup. Trước đây, ông từng làm Giám đốc Đầu tư tại Vietnam Holding Asset Management Ltd và Giám đốc tại PwC Việt Nam & Sydney (Úc).
                              </div>
                            </div>
                        </div>

                        <div class="member-card">
                            <img src="../Data/Banner/about_us2.png" alt="why" />
                            <div class="member-info">
                                <div class="member-name">Nguyễn Hữu Hiệu, MBA</div>
                                <div class="member-title">Tổng Giám Đốc</div>
                              	<div class="member-desc">
                                  Đồng sáng lập FiinGroup. Trước đây, ông từng làm Cố vấn Quản trị tại Bộ Phát triển Quốc tế của Anh (DFID), Cán bộ Phát triển Khu vực Công tại IFC (Ngân hàng Thế giới) và Quản lý Tư vấn tại PwC Việt Nam.
                              </div>
                            </div>
                        </div>

                        <div class="member-card">
                            <img src="../Data/Banner/about_us3.png" alt="why" />
                            <div class="member-info">
                                <div class="member-name">Mạc Quang Huy, CPA, FCCA</div>
                                <div class="member-title">Thành viên HĐQT</div>
                              	<div class="member-desc">
                                 Ông là một nhà tài chính nổi tiếng từng làm việc tại Lehman Brothers và KPMG. Ông có 6 năm giữ chức Giám đốc điều hành của KB Securities (Việt Nam). Hiện tại, ông là chủ tịch của 4 quỹ mở do VCBF quản lý, đồng thời là thành viên hội đồng quản trị của một số công ty.
                              </div>
                            </div>
                        </div>

                        <div class="member-card">
                            <img src="../Data/Banner/about_us4.png" alt="why" />
                            <div class="member-info">
                                <div class="member-name">Hisatsugu Nagao</div>
                                <div class="member-title">Thành viên HĐQT</div>
                              	<div class="member-desc">
                                  Ông là đại diện của NIKKEI Inc. tại FiinGroup. Hiện ông đang giữ chức Giám đốc Phát triển Kinh doanh tại Đơn vị Kinh doanh Toàn cầu của Nikkei Inc. Trước đó, ông từng làm nhà báo tại Bangkok và Hồng Kông.
                              </div>
                            </div>
                        </div>

                        <div class="member-card">
                            <img src="../Data/Banner/about_us5.png" alt="why" />
                            <div class="member-info">
                                <div class="member-name">Chiharu Kawai</div>
                                <div class="member-title">Thành viên HĐQT</div>
                              	<div class="member-desc">
                                	Đại diện từ QUICK Corp tại FiinGroup. Hiện ông đang giữ chức Giám đốc Văn phòng Kinh doanh Toàn cầu tại QUICK Corp. 
                              </div>
                            </div>
                        </div>
                    </div>
                </div>

                <!-- Ban điều hành (có thể thêm sau) -->
                <div id="ban-dieu-hanh" class="tab-content" style="display: none;">
                    <div class="team-grid">
                        <div class="member-card">
                            <img src="../Data/Banner/about_us6.png" alt="why" />
                            <div class="member-info">
                                <div class="member-name">Trương Minh Trang, MBA</div>
                                <div class="member-title">Giám đốc điều hành, Khối dịch vụ thông tin tài chính
                                </div>
                            </div>
                        </div>


                        <div class="member-card">
                            <img src="../Data/Banner/about_us8.png" alt="why" />
                            <div class="member-info">
                                <div class="member-name">Vũ Thị Hoàn</div>
                                <div class="member-title">Giám đốc Tài chính</div>
                            </div>
                        </div>

                        <div class="member-card">
                            <img src="../Data/Banner/about_us9.png" alt="why" />
                            <div class="member-info">
                                <div class="member-name">Bùi Thành Trung</div>
                                <div class="member-title">Phó Giám đốc Công nghệ</div>
                            </div>
                        </div>

                        <div class="member-card">
                            <img src="../Data/Banner/about_us10.png" alt="why" />
                            <div class="member-info">
                                <div class="member-name">Nguyễn Hà Vy</div>
                                <div class="member-title">Trưởng phòng Marketing </div>
                            </div>
                        </div>


                        <div class="member-card">
                            <img src="../Data/Banner/about_us11.png" alt="why" />
                            <div class="member-info">
                                <div class="member-name">Nguyễn Thu Quyên</div>
                                <div class="member-title">Trưởng phòng Nhân sự </div>
                            </div>
                        </div>
                    </div>
                </div>

                <script>
                    const tabs = document.querySelectorAll(''.tab'');
                    const contents = {
                        ''Hội đồng quản trị'': document.getElementById(''hdqt''),
                        ''Ban điều hành'': document.getElementById(''ban-dieu-hanh'')
                    };
                    const title = document.getElementById(''team-title'');

                    tabs.forEach(tab => {
                        tab.addEventListener(''click'', () => {
                            // Xóa trạng thái active cũ
                            tabs.forEach(t => t.classList.remove(''active''));
                            Object.values(contents).forEach(content => content.style.display = ''none'');

                            // Kích hoạt tab hiện tại
                            tab.classList.add(''active'');

                            // Hiển thị nội dung tương ứng với nút được bấm
                            const selected = tab.textContent.trim();
                            if (contents[selected]) {
                                contents[selected].style.display = ''block'';
                            }
                            if (selected === ''Hội đồng quản trị'') {
                                title.innerHTML = ''Đội ngũ quản lý'';
                            } else if (selected === ''Ban điều hành'') {
                                title.innerHTML = ''Đội ngũ quản lý'';
                            }
                        });
                    });
                </script>
            </div>
        </section>', 1, N'vi', 0, 0, N'AboutUsUserTeam', NULL, 2);
INSERT INTO [dbo].[StaticInformation] ([Id], [Name], [Content], [Status], [Language], [Delete], [ParentId], [Code], [Data], [PortalId]) VALUES (1038, N'AboutUs - WordEnvironment', N'        <section id="WordEnvironment" class="py-5 mb-5">
