INSERT INTO [dbo].[StaticInformation] ([Id], [Name], [Content], [Status], [Language], [Delete], [ParentId], [Code], [Data], [PortalId]) VALUES (1041, N'Business - Major', N'  <section id="Major">
            <style>
                .narbarstory {
                    padding: 50px 0;
                    display: flex;
                    justify-content: space-around;
                    align-items: center;
                }

                .narbarstory a {
                    color: #093461;
                    text-decoration: none;
                    font-size: 18px;
                    padding: 8px 0;
                    display: flex;
                    justify-content: center;
                    min-width: 25%;
                    transition: color 0.3s, border-bottom 0.3s;
                    cursor: pointer;
                    border-bottom: 3px solid transparent;
                }

                .narbarstory a.active,
                .narbarstory a:hover {
                    color: #0066CC;
                    border-bottom: 3px solid #093461;
                }

                .about-main-box {
                    padding: 15px 20px;
                    border-radius: 12px;
                    margin-bottom: 40px;

                    border: 1px solid transparent;
                    background-image: linear-gradient(#f5f9ff, #f2f7ff), linear-gradient(to right, #E6E6E600, #034EA2);
                    background-origin: border-box;
                    background-clip: padding-box, border-box;
                }


                .about-main-box::before {
                    content: "";
                    position: absolute;
                    inset: 0;
                    border-radius: inherit;
                    z-index: -1;
                }

                .about-main-box {
                    position: relative;
                    z-index: 1;
                    /* border và nội dung */
                }

                .about-main-box p {
                    margin-bottom: 12px;
                    line-height: 1.6;
                    color: #093461;
                    font-size: 15px;
                    padding-top: 20px;
                    text-align: justify;
                }

                .about-wrap {
                    position: relative;
                    z-index: 1;
                }

                .corner-decor {
                    position: absolute;
                    top: -65px;
                    right: 17%;
                    width: 110px;
                    z-index: 3;
                    /* CAO HƠN border */
                    /* đảm bảo nằm trên */
                    pointer-events: none;
                }
            </style>
            <div class="container">
                <div class="narbarstory">
                    <a href="#Major" class="active">Cổ đông lớn</a>
                    <a href="#Report">Báo cáo Tài chính</a>
                    <a href="#Report">Quy định nội bộ</a>
                    <a href="#Report">Văn bản Pháp lý</a>
                </div>
                <div class="why pb-4">
                    <h2 class="price-title mb-5"><span style="color: #0066CC;"> Cổ đông lớn </span></h2>
                    <div class="about-wrap">
                        <img src="../Data/Banner/product_vector1.png" class="corner-decor" alt="">

                        <div class="about-main-box">
                            <img src="../Data/Banner/story_icon1.png" alt="why" />
                            <p>
                                Kể từ ngày 01/08/2022 Công ty Cổ phần FiinGroup thay đổi từ mười cổ đông (bao gồm hai cổ
                                đông tổ chức là Nikkei Inc. và QUICK Corp.) sang bốn cổ đông bao gồm Công ty Cổ phần
                                FiinGroup Việt Nam (sở hữu 99,96%) và ba cá nhân bao gồm ông Nguyễn Quang Thuân (Chủ
                                tịch kiêm Tổng Giám đốc, sở hữu 0,018%), ông Nguyễn Hữu Hiệu (Giám đốc Hoạt động, sở hữu
                                0,018%) và bà Vũ Thị Hoàn (Giám đốc Tài chính, sở hữu 0,004%).
                            </p>

                        </div>
                    </div>

                </div>
            </div>
            <script>
                document.addEventListener(''DOMContentLoaded'', () => {
                  const links = document.querySelectorAll(''.narbarstory a'');
                  links.forEach(link => {
                      link.addEventListener(''click'', (e) => {
                          e.preventDefault();
                          // Xóa class active
                          links.forEach(l => l.classList.remove(''active''));
                          link.classList.add(''active'');
                          // Lấy ID mục tiêu
                          const targetId = link.getAttribute(''href'')?.trim();
                          // Nếu href null hoặc không phải id hợp lệ thì thoát
                          if (!targetId || !targetId.startsWith("#")) {
                              return;
                          }
                          const targetEl = document.querySelector(targetId);
                          if (targetEl) {
                              targetEl.scrollIntoView({
                                  behavior: "smooth",
                                  block: "start"
                              });
                          }
                      });
                  });
              });
            </script>
        </section>', 1, N'vi', 0, 0, N'BusinessMajor', NULL, 2);
INSERT INTO [dbo].[StaticInformation] ([Id], [Name], [Content], [Status], [Language], [Delete], [ParentId], [Code], [Data], [PortalId]) VALUES (1042, N'Business - ShareholderTable', N'   <section id="ShareholderTable">
            <style>
                .shareholder-table {
                    width: 100%;
                    border-collapse: collapse;
                    font-family: "Inter", sans-serif;
                    font-size: 14px;
                    text-align: center;
                    background-color: #fff;
                    box-shadow: 0 2px 8px rgba(3, 78, 162, 0.1);
                    border-radius: 8px;
                    overflow: hidden;
                }

                /* Header */
                .shareholder-table .header-row th {
                    background-color: #0066CC;
                    color: #fff;
                    font-weight: 600;
                    padding: 10px 8px;
                }

                .shareholder-table .sub-header th {
                    background-color: #ebedf0;
                    color: #034ea2;
                    font-weight: 600;
                    font-size: 13px;
                    padding: 10px 8px;
                }

                /* Ô dữ liệu */
                .shareholder-table td {
                    padding: 18px 8px;
                    color: #093461;
                    border-bottom: 1px solid #e5ebf5;
                }

                .shareholder-table .col-name {
                    text-align: left;
                    padding-left: 15px;
                    font-weight: 500;
                }

