INSERT INTO [dbo].[StaticInformation] ([Id], [Name], [Content], [Status], [Language], [Delete], [ParentId], [Code], [Data], [PortalId]) VALUES (1047, N'Event - Deliver', N'<section id="Deliver" class="mb-5 d-none d-lg-block">
