INSERT INTO [dbo].[StaticInformation] ([Id], [Name], [Content], [Status], [Language], [Delete], [ParentId], [Code], [Data], [PortalId]) VALUES (3001024, N'Product - FiinPro-X Có Gì', N'<section id="FiinProX">
    <style>
        .finnpro {
            padding-top: 50px;
        }

        .finx-title {
            text-align: center;
        }

        .group-num {
            display: flex;
            justify-content: space-around;
            align-items: center;
            padding: 20px;
            flex-wrap: wrap;
            /* Allow wrapping on smaller screens */
        }

        .stat-box {
            padding: 20px;
            max-width: 180px;
            /* Limit width for better wrapping */
        }

        .number {
            display: block;
            font-size: 24px;
            font-weight: bold;
            color: #1e3a8a;
            margin-bottom: 5px;
        }

        .desc {
            display: block;
            font-size: 14px;
            color: #2d5ba9;
            white-space: nowrap;
        }

        /* SVG Line Styling */
        .stat-box svg {
            width: 100%;
            height: 2px;
            margin: 5px 0;
        }

        .stat-box rect {
            fill: url(#paint0_linear_4337_26784);
        }
    </style>
    <div class="container">
        <div class="finnpro">
            <h2 class="finx-title price-title mb-5"><span style="color: #0066CC;">FiinPro-X</span> có gì?
            </h2>
        </div>
        <div id="bg2" class="row group-num">
            <div class="stat-box">
                <p class="number">
                    <span class="counter">100</span> +
                </p>
              	<img src="/Data/Icon/icon-line.svg" alt="line"/>
                <p class="desc">Chỉ số thị trường</p>
            </div>
            <div class="stat-box">
                <p class="number">
                    <span class="counter">1.000</span> +
                </p>
                <img src="/Data/Icon/icon-line.svg" alt="line"/>
                <p class="desc">Tin tức thị trường vĩ mô</p>
            </div>
            <div class="stat-box">
                <p class="number">
                    <span class="counter">3.800</span> +
                </p>
                <img src="/Data/Icon/icon-line.svg" alt="line"/>
                <p class="desc">Doanh nghiệp đại chúng</p>
            </div>
            <div class="stat-box">
                <p class="number">
                    <span class="counter">1.000</span> +
                </p>
                <img src="/Data/Icon/icon-line.svg" alt="line"/>
                <p class="desc">Tổ chức phát hành</p>
            </div>
            <div class="stat-box">
                <p class="number">
                    <span class="counter">8.000</span> +
                </p>
                <img src="/Data/Icon/icon-line.svg" alt="line"/>
                <p class="desc">Mã trái phiếu</p>
            </div>
