INSERT INTO [dbo].[StaticInformation] ([Id], [Name], [Content], [Status], [Language], [Delete], [ParentId], [Code], [Data], [PortalId]) VALUES (3001029, N'Solution - FiinGroup thấu hiểu', N'<section id="FiinGroup">
            <style>
                .navbarfin {
                    padding: 50px 0;
                }

                .navbarfin a {
                    color: #093461;
                    text-decoration: none;
                    font-size: 18px;
                    padding: 5px 40px;
                    transition: color 0.3s;
                    cursor: pointer;
                }

                .navbarfin a.active {
                    color: #0066CC;
                    border-bottom: 3px solid #093461;
                }

                .box-fingroup {
                    position: relative;
                    border-radius: 15px;
                    margin: 10px 0;
                    box-shadow: 0 4px 8px #0000001a;
                    transition: transform 0.3s;
                    max-width: 31%;
                    min-width: 350px;

                    /* border gradient bo góc mượt */
                    border: 1px solid transparent;
                    background-image: linear-gradient(#f5f9ff, #f2f7ff), 
                      linear-gradient(to right, #E6E6E600, #034EA2);
                    background-origin: border-box;
                    background-clip: padding-box, border-box;
                }

                .box-fingroup:hover {
                    transform: translateY(-5px);
                }
            </style>
            <div class="container">
                <div class="navbarfin">
                    <a href="#overview" class="active">Overview</a>
                    <a href="#products">Products</a>
                    <a href="#featured-insights">Featured Insights</a>
                    <a href="#webinars">Webinars</a>
                </div>
                <div class="why pb-4">
                    <h2 class="text-center price-title mb-5">FinnGroup <span style="color: #0066CC;"> thấu
                            hiểu</span> nhu cầu khách hàng</h2>
                    <div class="row" style="justify-content: space-between;">
                        <div class="mb-5 box-fingroup">
                            <img src="../Data/solution_why.png" alt="why" />
                            <div class="why-title">Ra quyết định nhanh và <br>chính xác</div>
                            <svg width="156" height="2" viewBox="0 0 156 2" fill="none"
                                xmlns="http://www.w3.org/2000/svg">
                                <rect x="0.666626" width="156" height="4" fill="url(#paint0_linear_4337_26784)" />
                                <defs>
                                    <linearGradient id="paint0_linear_4337_26784" x1="-22.7334" y1="0.7" x2="-22.0174"
                                        y2="14.2709" gradientUnits="userSpaceOnUse">
                                        <stop offset="0.384615" stop-color="#034EA2" />
                                        <stop offset="1" stop-color="#53DFFF" />
                                    </linearGradient>
                                </defs>
                            </svg>
                            <p class="why-desc">Cần dữ liệu realtime, thống nhất để phản ứng kịp thị trường
                            </p>
                        </div>
                        <div class="mb-5 box-fingroup pr-2">
                            <img src="../Data/solution_why2.png" alt="why" />
                            <div class="why-title">Giám sát, Quản trị rủi ro toàn diện</div>
                            <svg width="156" height="2" viewBox="0 0 156 2" fill="none"
                                xmlns="http://www.w3.org/2000/svg">
                                <rect x="0.666626" width="156" height="4" fill="url(#paint0_linear_4337_26784)" />
                                <defs>
                                    <linearGradient id="paint0_linear_4337_26784" x1="-22.7334" y1="0.7" x2="-22.0174"
                                        y2="14.2709" gradientUnits="userSpaceOnUse">
                                        <stop offset="0.384615" stop-color="#034EA2" />
                                        <stop offset="1" stop-color="#53DFFF" />
                                    </linearGradient>
                                </defs>
                            </svg>
                            <p class="why-desc">Giám sát tín dụng, chấm điểm doanh nghiệp, giảm nợ xấu
                        </div>
                        <div class="mb-5 box-fingroup">
                            <img src="../Data/solution_why3.png" alt="why" />
                            <div class="why-title">Định giá tài sản minh bạch
                            </div>
                            <svg width="156" height="2" viewBox="0 0 156 2" fill="none"
                                xmlns="http://www.w3.org/2000/svg">
                                <rect x="0.666626" width="156" height="4" fill="url(#paint0_linear_4337_26784)" />
                                <defs>
                                    <linearGradient id="paint0_linear_4337_26784" x1="-22.7334" y1="0.7" x2="-22.0174"
                                        y2="14.2709" gradientUnits="userSpaceOnUse">
                                        <stop offset="0.384615" stop-color="#034EA2" />
                                        <stop offset="1" stop-color="#53DFFF" />
                                    </linearGradient>
                                </defs>
                            </svg>
                            <p class="why-desc">Xác định giá trị trái phiếu, cổ phiếu theo giá thị trường
                            </p>
                        </div>

                        <div class="mb-5 box-fingroup">
                            <img src="../Data/solution_why4.png" alt="why" />
                            <div class="why-title">Hệ thống tích hợp dữ liệu linh hoạt</div>
                            <svg width="156" height="2" viewBox="0 0 156 2" fill="none"
                                xmlns="http://www.w3.org/2000/svg">
                                <rect x="0.666626" width="156" height="4" fill="url(#paint0_linear_4337_26784)" />
                                <defs>
                                    <linearGradient id="paint0_linear_4337_26784" x1="-22.7334" y1="0.7" x2="-22.0174"
                                        y2="14.2709" gradientUnits="userSpaceOnUse">
                                        <stop offset="0.384615" stop-color="#034EA2" />
                                        <stop offset="1" stop-color="#53DFFF" />
                                    </linearGradient>
                                </defs>
                            </svg>
                            <p class="why-desc">Dễ dàng kết nối vào hệ thống nội bộ
                            </p>
                        </div>
                        <div class="mb-5 box-fingroup">
                            <img src="../Data/solution_why5.png" alt="why" />
                            <div class="why-title">Thấu hiểu khách hàng doanh nghiệp</div>
                            <svg width="156" height="2" viewBox="0 0 156 2" fill="none"
                                xmlns="http://www.w3.org/2000/svg">
                                <rect x="0.666626" width="156" height="4" fill="url(#paint0_linear_4337_26784)" />
                                <defs>
                                    <linearGradient id="paint0_linear_4337_26784" x1="-22.7334" y1="0.7" x2="-22.0174"
                                        y2="14.2709" gradientUnits="userSpaceOnUse">
                                        <stop offset="0.384615" stop-color="#034EA2" />
                                        <stop offset="1" stop-color="#53DFFF" />
                                    </linearGradient>
                                </defs>
                            </svg>
                            <p class="why-desc">Phân tích tài chính & tín dụng hỗ trợ thẩm định hiệu quả</p>
                        </div>
                        <div class="mb-5 box-fingroup">
                            <img src="../Data/solution_why6.png" alt="why" />
                            <div class="why-title">Nâng cao hiệu suất vận hành</div>
                            <svg width="156" height="2" viewBox="0 0 156 2" fill="none"
                                xmlns="http://www.w3.org/2000/svg">
                                <rect x="0.666626" width="156" height="4" fill="url(#paint0_linear_4337_26784)" />
                                <defs>
                                    <linearGradient id="paint0_linear_4337_26784" x1="-22.7334" y1="0.7" x2="-22.0174"
                                        y2="14.2709" gradientUnits="userSpaceOnUse">
                                        <stop offset="0.384615" stop-color="#034EA2" />
                                        <stop offset="1" stop-color="#53DFFF" />
                                    </linearGradient>
                                </defs>
                            </svg>
                            <p class="why-desc">Tự động hóa phân tích, tiết kiệm thời gian và nguồn lực</p>
                        </div>
                    </div>

                </div>

            </div>
            <script>
                document.addEventListener(''DOMContentLoaded'', () => {
                    const links = document.querySelectorAll(''.navbarfin a'');
                    links.forEach(link => {
                        link.addEventListener(''click'', (e) => {
                            e.preventDefault();
                            links.forEach(l => l.classList.remove(''active''));
                            link.classList.add(''active'');
                        });
                    });
                });
            </script>
        </section>', 1, N'en', 1, 0, N'SolutionFiinGroup', NULL, 2);
INSERT INTO [dbo].[StaticInformation] ([Id], [Name], [Content], [Status], [Language], [Delete], [ParentId], [Code], [Data], [PortalId]) VALUES (3001030, N'Solution - Giải pháp hỗ trợ', N' <section id="GiaiPhap" class="py-5">
            <style>
                .overlay-card {
                    position: relative;
                    overflow: hidden;
                    border-radius: 12px;
                    cursor: pointer;
                    transition: transform 0.3s ease;
                }

                .overlay-card:hover {
                    transform: translateY(-5px);
                }

                .overlay-card .card-img {
                    width: 100%;
                    height: 100%;
                    object-fit: cover;
                    display: block;
                    filter: brightness(0.6);
                    transition: filter 0.3s ease;
                    border-radius: 12px;
                    height: 240px;
                    width: 330px !important;
                }

                .overlay-card:hover .card-img {
                    filter: brightness(0.8);
                }

                .overlay-card .card-content {
                    position: absolute;
                    top: 0;
                    left: 0;
                    color: #fff;
                    padding: 25px;
                    width: 100%;
                    height: 100%;
                    display: flex;
                    flex-direction: column;
                    justify-content: space-between;
                }

                .overlay-card h3 {
                    font-size: 20px;
                    font-weight: 700;
                    margin: 0;
                }

                .overlay-card p {
                    font-size: 15px;
                    margin: 0 0 100px;
                    opacity: 0.9;
                    max-width: 75%;
                }

                .overlay-card .show-more {
                    color: #fff;
                    font-weight: 500;
                    font-size: 14px;
                    text-decoration: none;
                    display: inline-flex;
                    align-items: center;
                    gap: 5px;
                    transition: all 0.3s ease;
                }

                .overlay-card .show-more i {
                    transition: transform 0.3s ease;
                }

                .overlay-card .show-more:hover i {
                    transform: translateX(4px);
                }

                #GiaiPhap .show-more i {
                    color: #fff !important;
                }
                
            </style>
            <div class="container">
                <h2 class="price-title mb-5">Giải pháp hỗ trợ <span style="color: #0066CC;"> từ FiinGroup</span>
                </h2>
                <div class="owl-carousel owl-theme" id="owlour">
                    <div class="item">
                        <div class="overlay-card">
                            <img src="../Data/solution_giaiphap1.png" alt="FiinPro-X" class="card-img">
                            <div class="card-content">
                                <h3>FiinPro-X</h3>
                                <p>Nền tảng Dữ liệu Tài chính và Cổng thông tin Trái phiếu</p>
                                <a href="#" class="show-more">Show more <i class="fas fa-arrow-right"></i></a>
                            </div>
                        </div>

                    </div>
                    <div class="item">
                        <div class="overlay-card">
                            <img src="../Data/solution_giaiphap2.png" alt="Bond Pricing" class="card-img">
                            <div class="card-content">
                                <h3>Bond Pricing</h3>
                                <p>Dịch vụ tính giá trái phiếu</p>
                                <a href="#" class="show-more">Show more <i class="fas fa-arrow-right"></i></a>
                            </div>
                        </div>
                    </div>
                    <div class="item">
                        <div class="overlay-card">
                            <img src="../Data/solution_giaiphap3.png" alt="Bond Pricing" class="card-img">
                            <div class="card-content">
                                <h3>API Datafeed</h3>
                                <p>Giải pháp Dữ liệu Chứng khoán​</p>
                                <a href="#" class="show-more">Show more <i class="fas fa-arrow-right"></i></a>
                            </div>
                        </div>
                    </div>
                    <div class="item">
                        <div class="overlay-card">
                            <img src="../Data/solution_giaiphap4.png" alt="Bond Pricing" class="card-img">
                            <div class="card-content">
                                <h3>FiinQuant</h3>
                                <p>Thư viện dữ liệu Chứng khoán bằng ngôn ngữ Python</p>
                                <a href="#" class="show-more">Show more <i class="fas fa-arrow-right"></i></a>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
            <script>
                $("#owlour").owlCarousel({
                    items: 4,
                    loop: true,
                    margin: 20,
                    autoplay: true,
                    dots: true,
                    center: true
                });
            </script>
        </section>', 1, N'en', 1, 0, N'SolutionHelp', NULL, 2);
