INSERT INTO [dbo].[StaticInformation] ([Id], [Name], [Content], [Status], [Language], [Delete], [ParentId], [Code], [Data], [PortalId]) VALUES (3001033, N'AboutUs - Banner', N'    <section id="StockEconomy" class="aban-section">
            <style>
                #StockEconomy {
                    background: url(''../Data/Banner/about_banner.png'') no-repeat top;
                    background-size: cover;
                }

                .aban-content {
                    color: #fff;
                    max-width: 89%;
                    z-index: 2;
                    padding-bottom: 50px;
                }

                .aban-subtitle {
                    display: inline-block;
                    font-size: 40px;
                    font-weight: 500;
                    color: #fff;
                    padding-top: 90px;
                }

                .aban-title {
                    font-size: 60px;
                    font-weight: 700;
                    line-height: 1.4;
                    margin-bottom: 160px;
                }

                .aban-text {
                    font-size: 19px;
                    line-height: 1.7;
                    color: #d7e9ff;
                    text-align: justify;
                    position: relative;
                    padding-left: 25px;
                }

                .aban-text::before {
                    content: "";
                    position: absolute;
                    left: 0;
                    top: 0;
                    width: 5px;
                    height: 100%;
                    background: linear-gradient(to bottom, #5086c0, #E2F2FB7A, #badcf1);
                    border-radius: 2px;
                }
            </style>
            <div class="aban-overlay">
                <div class="container">
                    <div class="aban-content">
                        <span class="aban-subtitle">We are</span>
                        <h1 class="aban-title"> FiinGroup</h1>
                        <p class="aban-text">
                         
                        </p>
                    </div>
                </div>
