INSERT INTO [dbo].[StaticInformation] ([Id], [Name], [Content], [Status], [Language], [Delete], [ParentId], [Code], [Data], [PortalId]) VALUES (3001037, N'AboutUs - UserTeam', N'  <section id="UserTeam" class="py-5">
            <style>
                .price-title {
                    margin-bottom: 20px;
                }

                .tab-container {
                    display: inline-flex;
                    justify-content: center;
                    border: 1px solid #0078d4;
                    border-radius: 6px;
                    overflow: hidden;
                    font-family: Arial, sans-serif;
                    font-size: 14px;
                }

                .tab {
                    padding: 8px 20px;
                    border: none;
                    background: white;
                    color: #0078d4;
                    cursor: pointer;
                    transition: all 0.2s ease;
                    min-width: 250px;
                }

                .tab.active {
                    background: #0078d4;
                    color: white;
                }

                .tab:not(.active):hover {
                    background: #e6f0fb;
                }

                /* Team Grid */

                .team-grid {
                    display: grid;
                    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
                    gap: 30px;
                    justify-content: center;
                    align-items: start;
                }

                .member-card {
                    align-items: center;
                    text-align: center;
                    padding: 15px;
                    border-radius: 16px;
                    overflow: hidden;
                    transition: transform 0.3s ease, box-shadow 0.3s ease;
                    width: 100%;
                    height: 100%;
                    /* border gradient bo góc mượt */
                    border: 1px solid transparent;
                }

                .member-card:hover {
                    transform: translateY(-8px);
                    box-shadow: 0 12px 24px rgba(0, 0, 0, 0.12);
                }

                .member-card img {
                    max-width: 100%;
                }

                .member-info {
                    padding: 26px 0;
                    text-align: left;
                }

                .member-name {
                    font-size: 19px;
                    font-weight: 600;
                    color: #0066CC;
                    margin-bottom: 6px;
                }

                .member-title {
                    font-size: 16px;
                    font-weight: 500;
                }
              
              	.member-desc {
                    margin-top: 10px;
                    text-align: justify;
                    font-style: italic;
                }
            </style>

            <div class="container">
                <h2 id="team-title" style="text-align: center;" class="price-title mb-5">Our Leadership</h2>
                <div style="text-align: center;">
                    <div class="tab-container mb-5">
                        <button class="tab active">Board of Directors</button>
                        <button class="tab">Board of Management</button>
                    </div>
                </div>
                <!-- Hội đồng quản trị -->
                <div id="hdqt" class="tab-content">
                    <div class="team-grid">
                        <div class="member-card">
                            <img src="../Data/Banner/about_us1.png" alt="why" />
                            <div class="member-info">
                                <div class="member-name">Nguyen Quang Thuan, MBA, FCCA</div>
                                <div class="member-title">Chairman</div>
                              	<div class="member-desc">
                                 Co-founder of FiinGroup. Previously, he worked as an Investment Manager of Vietnam Holding Asset Management Ltd and Manager at PwC Vietnam & Sydney (Australia).
                              </div>
                            </div>
                        </div>

                        <div class="member-card">
                            <img src="../Data/Banner/about_us2.png" alt="why" />
                            <div class="member-info">
                                <div class="member-name">Nguyen Huu Hieu, MBA</div>
                                <div class="member-title">CEO</div>
                              	<div class="member-desc">
                                  Co-founder of FiinGroup. Previously, he worked as a Governance Advisor in the Department for International Development of UK (DFID), Public Sector Development Officer at IFC (World Bank) and Consulting Manager at PwC Vietnam.
                              </div>
                            </div>
                        </div>

                        <div class="member-card">
                            <img src="../Data/Banner/about_us3.png" alt="why" />
                            <div class="member-info">
                                <div class="member-name">Huy Mac, CPA, FCCA</div>
                                <div class="member-title">Board Member</div>
                              	<div class="member-desc">
                                 A well-known financier with Lehman Brothers and KPMG. He had six years as CEO of KB Securities (Vietnam). Currently, he is the chairman to 4 open-ended funds as managed by VCBF as well as sitting in the Board of several companies.
                              </div>
                            </div>
                        </div>

                        <div class="member-card">
                            <img src="../Data/Banner/about_us4.png" alt="why" />
                            <div class="member-info">
                                <div class="member-name">Hisatsugu Nagao</div>
                                <div class="member-title">Board Member</div>
                              	<div class="member-desc">
                                 The representative of NIKKEI Inc. at FiinGroup. He is currently Manager of Business Development Group at Global Business Unit, Nikkei Inc. Prior to that, he worked as a journalist based in Bangkok and Hong Kong.
                              </div>
                            </div>
                        </div>

                        <div class="member-card">
                            <img src="../Data/Banner/about_us5.png" alt="why" />
                            <div class="member-info">
                                <div class="member-name">Chiharu Kawai</div>
                                <div class="member-title">Board Member</div>
                              	<div class="member-desc">
                                	Representative from QUICK Corp at FiinGroup. He is currently Principal of Global Business Office at QUICK Corp.
                              </div>
                            </div>
                        </div>
                    </div>
                </div>

                <!-- Ban điều hành (có thể thêm sau) -->
                <div id="ban-dieu-hanh" class="tab-content" style="display: none;">
                    <div class="team-grid">
                        <div class="member-card">
                            <img src="../Data/Banner/about_us6.png" alt="why" />
                            <div class="member-info">
                                <div class="member-name">Truong Minh Trang, MBA</div>
                                <div class="member-title">Managing Director, Financial Information Division
                                </div>
                            </div>
                        </div>

                        <div class="member-card">
                            <img src="../Data/Banner/about_us8.png" alt="why" />
                            <div class="member-info">
                                <div class="member-name">Vu Thi Hoan</div>
                                <div class="member-title">Chief Financial Officier</div>
                            </div>
                        </div>

                        <div class="member-card">
                            <img src="../Data/Banner/about_us9.png" alt="why" />
                            <div class="member-info">
                                <div class="member-name">Bui Thanh Trung</div>
                                <div class="member-title">Deputy Chief Technology Officier</div>
                            </div>
                        </div>

                        <div class="member-card">
                            <img src="../Data/Banner/about_us10.png" alt="why" />
                            <div class="member-info">
                                <div class="member-name">Nguyen Ha Vy</div>
                                <div class="member-title">Marketing Manager</div>
                            </div>
                        </div>


                        <div class="member-card">
                            <img src="../Data/Banner/about_us11.png" alt="why" />
                            <div class="member-info">
                                <div class="member-name">Nguyen Thu Quyen</div>
                                <div class="member-title">Human Resources Manager</div>
                            </div>
                        </div>
                    </div>
                </div>

                <script>
                    const tabs = document.querySelectorAll(''.tab'');
                    const contents = {
                        ''Board of Directors'': document.getElementById(''hdqt''),
                        ''Board of Managers'': document.getElementById(''ban-dieu-hanh'')
                    };
                    const title = document.getElementById(''team-title'');

                    tabs.forEach(tab => {
                        tab.addEventListener(''click'', () => {
                            // Xóa trạng thái active cũ
                            tabs.forEach(t => t.classList.remove(''active''));
                            Object.values(contents).forEach(content => content.style.display = ''none'');

                            // Kích hoạt tab hiện tại
                            tab.classList.add(''active'');

                            // Hiển thị nội dung tương ứng với nút được bấm
                            const selected = tab.textContent.trim();
                            if (contents[selected]) {
                                contents[selected].style.display = ''block'';
                            }
                            if (selected === ''Board of Directors'') {
                                title.innerHTML = ''Leadership'';
                            } else if (selected === ''Board of Managers'') {
                                title.innerHTML = ''Leadership'';
                            }
                        });
                    });
                </script>
            </div>
        </section>', 1, N'en', 0, 0, N'AboutUsUserTeam', NULL, 2);
INSERT INTO [dbo].[StaticInformation] ([Id], [Name], [Content], [Status], [Language], [Delete], [ParentId], [Code], [Data], [PortalId]) VALUES (3001038, N'AboutUs - WordEnvironment', N'        <section id="WordEnvironment" class="py-5 mb-5">
