INSERT INTO [dbo].[StaticInformation] ([Id], [Name], [Content], [Status], [Language], [Delete], [ParentId], [Code], [Data], [PortalId]) VALUES (3001041, N'Business - Major', N'  <section id="Major">
            <style>
                .narbarstory {
                    padding: 50px 0;
                    display: flex;
                    justify-content: space-around;
                    align-items: center;
                }

                .narbarstory a {
                    color: #093461;
                    text-decoration: none;
                    font-size: 18px;
                    padding: 8px 0;
                    display: flex;
                    justify-content: center;
                    min-width: 25%;
                    transition: color 0.3s, border-bottom 0.3s;
                    cursor: pointer;
                    border-bottom: 3px solid transparent;
                }

                .narbarstory a.active,
                .narbarstory a:hover {
                    color: #0066CC;
                    border-bottom: 3px solid #093461;
                }

                .about-main-box {
                    padding: 15px 20px;
                    border-radius: 12px;
                    margin-bottom: 40px;

                    border: 1px solid transparent;
                    background-image: linear-gradient(#f5f9ff, #f2f7ff), linear-gradient(to right, #E6E6E600, #034EA2);
                    background-origin: border-box;
                    background-clip: padding-box, border-box;
                }


                .about-main-box::before {
                    content: "";
                    position: absolute;
                    inset: 0;
                    border-radius: inherit;
                    z-index: -1;
                }

                .about-main-box {
                    position: relative;
                    z-index: 1;
                    /* border và nội dung */
                }

                .about-main-box p {
                    margin-bottom: 12px;
                    line-height: 1.6;
                    color: #093461;
                    font-size: 15px;
                    padding-top: 20px;
                    text-align: justify;
                }

                .about-wrap {
                    position: relative;
                    z-index: 1;
                }

                .corner-decor {
                    position: absolute;
                    top: -65px;
                    right: 17%;
                    width: 110px;
                    z-index: 3;
                    /* CAO HƠN border */
                    /* đảm bảo nằm trên */
                    pointer-events: none;
                }
            </style>
            <div class="container">
                <div class="narbarstory">
                    <a href="#Major" class="active">Major Shareholders</a>
                    <a href="#Report">Financial Statements</a>
                    <a href="#Report">Internal Policies</a>
                    <a href="#Report">Corporate Legal Documents</a>
                </div>
                <div class="why pb-4">
                    <h2 class="price-title mb-5"><span style="color: #0066CC;">Major Shareholders </span></h2>
                    <div class="about-wrap">
                        <img src="../Data/Banner/product_vector1.png" class="corner-decor" alt="">

                        <div class="about-main-box">
                            <img src="../Data/Banner/story_icon1.png" alt="why" />
                            <p>
                                Since August 1st 2022, FiinGroup Joint Stock Company changed in major shareholders from ten shareholders (including two institutional shareholders: Nikkei Inc. and QUICK Corp.) to four shareholders including Vietnam FiinGroup Joint Stock Company (owning 99.96%) and three individual shareholders: Mr. Nguyen Quang Thuan (Chairman & CEO, owning 0.018%), Mr. Nguyen Huu Hieu (Chief Operations Officer, owning 0.018%) and Ms. Vu Thi Hoan (Chief Finance Officer, owning 0.004%).
                            </p>

                        </div>
                    </div>

                </div>
            </div>
            <script>
                document.addEventListener(''DOMContentLoaded'', () => {
                  const links = document.querySelectorAll(''.narbarstory a'');
                  links.forEach(link => {
                      link.addEventListener(''click'', (e) => {
                          e.preventDefault();
                          // Xóa class active
                          links.forEach(l => l.classList.remove(''active''));
                          link.classList.add(''active'');
                          // Lấy ID mục tiêu
                          const targetId = link.getAttribute(''href'')?.trim();
                          // Nếu href null hoặc không phải id hợp lệ thì thoát
                          if (!targetId || !targetId.startsWith("#")) {
                              return;
                          }
                          const targetEl = document.querySelector(targetId);
                          if (targetEl) {
                              targetEl.scrollIntoView({
                                  behavior: "smooth",
                                  block: "start"
                              });
                          }
                      });
                  });
              });
            </script>
        </section>', 1, N'en', 0, 0, N'BusinessMajor', NULL, 2);
INSERT INTO [dbo].[StaticInformation] ([Id], [Name], [Content], [Status], [Language], [Delete], [ParentId], [Code], [Data], [PortalId]) VALUES (3001042, N'Business - ShareholderTable', N'   <section id="ShareholderTable">
