                background: url(../Data/anpham-bg.jpg) no-repeat top;
                background-size: cover;
                height: 396px;
            }

                #Banner h1 {
                    font-style: normal;
                    font-weight: 700;
                    font-size: 36px;
                    line-height: 150%;
                    margin: 10% 0 0 0;
                }

                #Banner h2 {
                    font-weight: 700;
                    font-size: 24px;
                    line-height: 28px;
                }

                #Banner img {
                    border-radius: 16px;
                }

            .item-date {
                font-weight: 400;
                font-size: 18px;
                line-height: 150%;
                display: flex;
                align-items: center;
                color: #fff;
            }

                .item-date i {
                    padding: 0 10px 0 0;
                    width: 30px;
                }

                .item-date .item-label {
                    padding: 0 10px 0 0;
                    width: 126px;
                }

            #NewButton {
                align-items: center;
                justify-content: center;
                margin: -3.5% 0 0 0;
            }

            .btn-active {
                display: flex;
                flex-direction: row;
                justify-content: center;
                align-items: center;
                padding: 12px 40px;
                gap: 40px;
                width: 302px;
                height: 72px;
                background: #FFFFFF;
                box-shadow: 0px 4px 20px rgba(0, 0, 0, 0.08);
                border-radius: 12px;
                font-size: 24px;
                font-weight: 500;
                color: #093461;
                margin: 0 10px;
            }

                .btn-active:hover {
                    background: #f6f6f6;
                }

            .btn-noactive {
                display: flex;
                flex-direction: row;
                justify-content: center;
                align-items: center;
                padding: 12px 40px;
                gap: 40px;
                width: 302px;
                height: 72px;
                background: #0066CC;
                box-shadow: 0px 8px 20px rgba(0, 102, 204, 0.12), 0px -8px 20px rgba(255, 255, 255, 0.2);
                border-radius: 12px;
                font-size: 24px;
                font-weight: 500;
                color: #fff;
            }

                .btn-noactive:hover {
                    background: #0f65ba;
                    color: #fff;
                }

            .btn-reset {
                color: #0066CC;
            }

            #search #search-input {
                display: flex;
                flex-direction: column;
                align-items: flex-start;
                padding: 12px;
                gap: 10px;
                width: 485px;
                height: 38px;
                background: #FFFFFF;
                border: 1px solid #034EA2;
                border-radius: 4px;
            }

            #search {
                position: relative;
                font-size: 18px;
            }

                #search label {
                    position: absolute;
                    right: 8px;
                    top: 6px;
                    color: #034EA2;
                }

            .mr-2 {
                margin: 0 1rem 0;
            }

            .btn-search {
                display: flex;
                flex-direction: row;
                justify-content: center;
                align-items: center;
                padding: 10px 50px;
                height: 40px;
                background: #0066CC;
                border-radius: 200px;
            }

            .pub-title {
                font-weight: 700;
                font-size: 28px;
                height: 80px;
                line-height: 120%;
                display: flex;
                align-items: center;
                color: #1D2939;
                flex: none;
                order: 0;
                align-self: stretch;
                flex-grow: 0;
                overflow: hidden;
            }

            .price {
                font-weight: 700;
                font-size: 32px;
                line-height: 120%;
                color: #0066CC;
            }

            .price-format {
                font-weight: 500;
                font-size: 28px;
                line-height: 120%;
                color: #0066CC;
                opacity: 0.5;
            }

            .show-download {
                color: #0066CC;
                text-decoration: underline;
            }

            .news-tag-item {
                font-weight: 500;
                font-size: 14px;
                line-height: 150%;
                color: #093461;
            }

                .news-tag-item .date {
                    color: #0066CC
                }

                .news-tag-item span {
                    padding: 0 10px 0 0;
                }
            .pub-list-tag button{
                margin:0 10px 0 0;
            }
            .btn-tag {
                display: flex;
                flex-direction: row;
                justify-content: center;
                align-items: center;
                padding: 12px 16px;
                gap: 8px;
                width: 148px;
                height: 40px;
                background: #e9f0fb;
                border-radius: 8px;
            }
            .btn-tag-active {
                background: #E1F4FD !important;
            }
            .input-select {
                display: flex;
                flex-direction: column;
                align-items: flex-start;
                padding: 8px 12px;
                gap: 10px;
                width: 292.33px;
                height: 38px;
                background: #FFFFFF;
                border: 1px solid #034EA2;
                border-radius: 4px;
                margin:0 15px 0 0;
            }
        </style>
        <section id="Banner">
            <div class="container">
                <div class="row">
                    <h1 class="text-white">Khám phá báo cáo, phân tích và nhận định chuyên sâu do đội ngũ FiinGroup thực hiện.</h1>
                </div>
            </div>
        </section>', 1, N'en', 1, 0, N'PubliscationsBanner', NULL, 2);
