INSERT INTO [dbo].[StaticInformation] ([Id], [Name], [Content], [Status], [Language], [Delete], [ParentId], [Code], [Data], [PortalId]) VALUES (3001055, N'Publiscations - Deliver', N'<section id="Deliver" class="mb-5">
