INSERT INTO [dbo].[StaticInformation] ([Id], [Name], [Content], [Status], [Language], [Delete], [ParentId], [Code], [Data], [PortalId]) VALUES (3001056, N'Publiscations - Detail - ReportDetail', N'        <section id="ReportDetail" class="py-5">
            <style>
                /* --- HEADER --- */
                .report-header {
                    display: flex;
                    flex-wrap: wrap;
                    align-items: flex-start;
                    gap: 30px;
                    margin-bottom: 40px;
                }

                .report-header img {
                    width: 380px;
                    border-radius: 12px;
                    box-shadow: 0 4px 10px rgba(0, 64, 128, 0.15);
                }

                .report-info {
                    flex: 1;
                    min-width: 300px;
                }

                .news-meta {
                    display: flex;
                    gap: 20px;
                    color: #0066CC;
                    font-size: 14px;
                }

                .news-meta p {
                    margin: 0;
                    position: relative;
                }

                .news-sers {
                    color: #093461;
                }

                .news-sers i {
                    color: #0066CC;
                    font-size: 7px;
                    vertical-align: middle;
                }

                .report-info h2 {
                    font-size: 28px;
                    font-weight: 700;
                    margin-bottom: 15px;
                    color: #002d72;
                    border-bottom: 1px solid #F0F0F0;
                    padding: 10px 0;
                }

                .report-meta-table {
                    display: grid;
                    grid-template-columns: 140px 1fr;
                    row-gap: 6px;
                    font-size: 15px;
                    margin-bottom: 20px;
                }

                .report-meta-table p {
                    margin: 0;
                }

                .report-meta-row {
                    display: flex;
                    justify-content: space-between;
                    align-items: flex-start;
                    flex-wrap: wrap;
                    gap: 30px;
                }

                .meta-item {
                    flex: 1;
                    min-width: 120px;
                }

                .meta-label {
                    font-size: 14px;
                    color: #1D2939;
                    margin-bottom: 5px;
                }

                .meta-value {
                    font-size: 15px;
                    font-weight: 600;
                    color: #1d2939;
                }

                .report-price {
                    font-size: 28px;
                    color: #0066CC;
                    font-weight: 700;
                    margin: 10px 0 20px 0;
                }

                .report-buttons {
                    display: flex;
                    gap: 12px;
                    flex-wrap: wrap;
                }

                .report-buttons a {
                    padding: 10px 0 0 0;
                    border-bottom: 2px solid;
                    color: #0066CC;
                }

                .btn-buy {
                    background: #0066cc;
                    color: white;
                    padding: 10px 62px;
                    border: none;
                    border-radius: 30px;
                    cursor: pointer;
                    transition: all 0.3s ease;
                }

                .btn-buy:hover {
                    background: #0078d4;
                }

                .btn-outline {
                    background: transparent;
                    border: 1.5px solid #0078d4;
                    color: #0078d4;
                    padding: 10px 25px;
                    border-radius: 30px;
                    transition: 0.3s;
                }

                .btn-outline:hover {
                    background: #0078d4;
                    color: #fff;
                }

                /* --- TABS --- */
                .report-tabs {
                    display: flex;
                    gap: 40px;
                    border-bottom: 2px solid #e0e8f5;
                    margin: 40px 0 20px;
                }

                .report-tab {
                    font-size: 18px;
                    font-weight: 600;
                    /* color: #093461; */
                    padding-bottom: 10px;
                    cursor: pointer;
                    border-bottom: 2px solid transparent;
                    width: 200px;
                    text-align: center;
                }

                .report-tab.active {
                    color: #034ea2;
                    border-color: #034ea2;
                }

                /* --- CONTENT --- */
                .report-content {
                    margin-bottom: 40px;
                }

                .report-content p {
                    line-height: 1.7;
                    margin-bottom: 5px;
                    font-size: 16px;
                    text-align: justify;
                    color: #093461;
                }

                .report-content h3 {
                    color: #093461;
                    font-size: 20px;
                    margin: 20px 0 10px;
                    font-weight: 700;
                }

                .report-content ul {
                    padding-left: 30px;
                    margin-bottom: 20px;
                }

                .report-content ul li {
                    list-style: disc;
                    margin-bottom: 10px;
                    line-height: 1.6;
                }

                .report-content ul li b {
                    color: #093461;
                }

                /* --- CONTACT --- */
                .report-contact {
                    margin-top: 40px;
                }

                .report-contact h4 {
                    color: #002d72;
                    font-size: 30px;
                    margin-bottom: 15px;
                    font-weight: 600;
                }

                .contact-grid {
                    display: grid;
                    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
                    gap: 60px;
                }

                .contact-box {
                    border-radius: 10px;
                    border: 1px solid #d5e4ff;
                    padding: 20px;
                    box-shadow: 0 2px 10px rgba(0, 64, 128, 0.05);
                    /* border gradient bo góc mượt */
                    border: 1px solid transparent;
                    background-image: linear-gradient(#f5f9ff, #f2f7ff), linear-gradient(to right, #0018A8, #166BF2, #3B7EEE);
                    background-origin: border-box;
                    background-clip: padding-box, border-box;
                }

                .contact-box h5 {
                    color: #034ea2;
                    margin-bottom: 10px;
                }

                .contact-box p {
                    color: #034ea2;
                    font-size: 14px;
                    margin-bottom: 6px;
                }

                .contact-box a {
                    color: #034ea2;
                    border-bottom: 1px solid;
                }

                .contact-box p i {
                    padding-right: 5px;
                }

                .vnd {
                    font-weight: 400;
                    color: #88b8e7;
                }

                .pdt20 {
                    padding-top: 20px;
                }

                .tag {
                    color: #0066CC !important;
                    padding: 20px 0 10px;
                    border-bottom: 1px solid #ccc;
                }
            </style>

            <div class="container">
                <div class="report-header">
                    <img src="../Data/publis-detail.png" alt="Vietnam Credit Card Market Report" />
                    <div class="report-info">
                        <div class="news-meta">
                            <p class="news-time">March 01 2025</p>
                            <p class="news-sers">FiinResearch <i class="fas fa-circle pd5"></i> 18 pages</p>
                        </div>
                        <h2>Vietnam Credit Card Market Report 2025</h2>
                        <div class="report-meta-row">
                            <div class="meta-item">
                                <p class="meta-label">Tổng trang</p>
                                <p class="meta-value">70 trang</p>
                            </div>
                            <div class="meta-item">
                                <p class="meta-label">Định dạng</p>
                                <p class="meta-value">PDF (.pdf)</p>
                            </div>
                            <div class="meta-item">
                                <p class="meta-label">Chủ đề</p>
                                <p class="meta-value">Financial Service</p>
                            </div>
                            <div class="meta-item">
                                <p class="meta-label">Giao hàng</p>
                                <p class="meta-value">Dưới 1 ngày</p>
                            </div>
                        </div>
                        <div class="report-price">65.000.000 <span class="vnd">VND</span></div>
                        <div class="report-buttons">
                            <button class="btn-buy">Mua báo cáo</button>
                            <a href="#">Download Preview</a>
                        </div>
                    </div>
                </div>

                <div class="report-tabs">
                    <div class="report-tab active">Tổng hợp</div>
                    <div class="report-tab">Danh mục</div>
                </div>

                <div class="report-content">
                    <p class="pdt20">
                        FiinGroup proudly presents our latest industry report: Vietnam Credit Card Market Report 2025.
                    </p>

                    <p class="pdt20">
                        This publication provides a comprehensive review of Vietnam’s evolving credit card market,
                        highlighting key developments in 2024 and early 2025 and offering forward-looking insights into
                        the structural trends shaping its outlook. The transition toward a cashless economy is
                        accelerating, with consumers embracing digital-first financial habits and banks leading the
                        charge in expanding credit card penetration. Supported by rapid infrastructure growth,
                        regulatory initiatives, and shifting consumer behavior, credit cards are emerging as a
                        cornerstone of Vietnam’s digital finance ecosystem.
                    </p>
                    <h3 class="pdt20">Key highlights from the report:</h3>
                    <ul>
                        <li><b>Credit card adoption accelerating:</b> Debit cards remain dominant in volume, but credit
                            cards are increasingly favored for lifestyle and digital transactions, particularly among
                            urban and tech-savvy consumers.</li>
                        <li><b>Banks solidify leadership:</b> Commercial banks have overtaken finance companies as
                            market leaders, embedding credit cards into digital ecosystems and focusing on long-term
                            customer value, while finance companies are shifting attention toward portfolio risk
                            management.</li>
                        <li><b>Infrastructure enabling growth:</b> Expansion of QR code acceptance and mobile POS
                            devices, already surpassing government targets, has enhanced payment accessibility for both
                            consumers and merchants.</li>
                        <li><b>Network dynamics reshaping competition:</b> NAPAS leads domestic transactions with low
                            fees and strong local integration, while VISA and Mastercard continue to dominate in
                            cross-border and online segments.</li>
                        <li><b>Structural drivers underpin momentum:</b> Government initiatives, fintech innovation,
                            e-commerce growth and rising financial literacy are fueling sustainable long-term growth in
                            Vietnam’s credit card market.</li>
                    </ul>

                    <p class="pdt20">This report answers the following questions:</p>
                    <ul>
                        <li>What is the current size, growth trajectory, and market share of credit cards in comparison
                            to other circulating payment instruments in Vietnam?
                        </li>
                        <li>What are the usage patterns of credit cards, particularly between credit-based purchases and
                            cash advances, and how are they utilized across various acceptance points such as QR codes,
                            POS terminals, mPOS, e-commerce, etc.?</li>
                        <li>How quickly is card payment infrastructure expanding, and how do card-based transactions
                            compare with cash usage among Vietnamese consumers?</li>
                        <li>What key factors are expected to drive the expansion of the credit card market in the coming
                            years?</li>
                        <li>Which major development trends are anticipated to influence future changes in the credit
                            card market?</li>
                        <li>What is the competitive landscape among leading credit card issuers in Vietnam?</li>
                        <li>From an in-depth perspective, what factors shape the market for bank-issued credit cards
                            versus those offered by FinCos?</li>
                        <li>How does the Vietnamese government regulate and support the adoption of cashless payments,
                            especially card transactions, through legal and policy frameworks?</li>
                    </ul>

                    <p class="tag">
                        Tags: Credit card, card finance report, banks, Thẻ tín dụng, Báo cáo thẻ tín dụng, Thị trường
                        thẻ tín dụng Việt Nam, BNPL, digital payment, cashless, contactless, virtual credit card, credit
                        purchase, cash advance, cash withdrawal, e-commerce, ecom, POS, mPOS,
                    </p>
                </div>

                <div class="report-contact">
                    <h4>Expert Assistance & More Information</h4>
                    <p>Our expert will help you find what you need. Contact our Customer Support for more information:
                    </p>
                    <div class="contact-grid">
                        <div class="contact-box">
                            <h5>Trụ sở chính</h5>
                            <p><i class="fas fa-envelope"></i> <a href="#">research.support@fiingroup.vn</a></p>
                            <p><i class="fas fa-phone-alt"></i> (84) 24 3562 6962</p>
                            <p><i class="fas fa-clock"></i> Thứ 2 - Thứ 6, Từ 8:30 đến 18:00 (Giờ Việt Nam)</p>
                        </div>
                        <div class="contact-box">
                            <h5>Chi nhánh TP Hồ Chí Minh</h5>
                            <p><i class="fas fa-envelope"></i> <a href="#">research.hcm@fiingroup.vn</a></p>
                            <p><i class="fas fa-phone-alt"></i> (84) 329 813 686 </p>
                            <p><i class="fas fa-clock"></i> Thứ 2 - Thứ 6, Từ 8:30 đến 18:00 (Giờ Việt Nam)</p>
                        </div>
                    </div>
                </div>
            </div>
        </section>
', 1, N'en', 1, 0, N'PubliscationsDetailReportDetail', NULL, 2);
