INSERT INTO [dbo].[StaticInformation] ([Id], [Name], [Content], [Status], [Language], [Delete], [ParentId], [Code], [Data], [PortalId]) VALUES (3001079, N'AboutUs - StoryFiin', N'<div class="narbarstory">
  <a href="#StoryFinn" class="active">Giới thiệu</a> 
  <a href="#TimeLine">Dấu mốc phát triển</a> 
  <a href="#UserTeam">Đội ngũ quản lý</a> 
  <a href="#WordEnvironment">Môi trường làm việc</a>
</div>
<div class="why pb-4 mt-0">
			<h2 class="price-title mb-3"><span style="color: #0066CC;"> Câu chuyện </span> của chúng tôi</h2>
			<div class="about-wrap">
				<div class="about-main-box">
					<p>
						<span style="color: #0066CC;"><strong>FiinRatings, đối tác chiến lược của S&P Global,</strong></span> là tổ chức xếp hạng tín nhiệm được Bộ Tài chính cấp phép và là một trong những đơn vị tiên phong thúc đẩy sự minh bạch và bền vững của thị trường vốn Việt Nam. Chúng tôi cung cấp dịch vụ <span style="color: #0066CC;"><strong> xếp hạng tín nhiệm độc lập</strong></span> cho các doanh nghiệp nhằm hỗ trợ hoạt động huy động vốn hiệu quả. FiinRatings cũng cung cấp các dịch vụ <span style="color: #0066CC;"><strong>nghiên cứu rủi ro, phân tích tín dụng</strong></span> chuyên sâu và <span style="color: #0066CC;"><strong>xác nhận trái phiếu xanh</strong></span> theo các chuẩn mực quốc tế như ICMA và Climate Bonds Initiative (CBI), qua đó hỗ trợ nhà đầu tư đánh giá rủi ro và ra quyết định đầu tư một cách toàn diện.  
					</p>
					<p>
						FiinRatings là một trong các công ty thành viên của <span style="color: #0066CC;"><strong>FiinGroup</strong></span> – đơn vị dẫn đầu tại Việt Nam trong lĩnh vực dữ liệu tài chính, nghiên cứu thị trường và giải pháp công nghệ tài chính. Sự hậu thuẫn về dữ liệu, công nghệ và chuyên môn từ FiinGroup giúp FiinRatings duy trì năng lực phân tích mạnh mẽ, mô hình xếp hạng chuẩn hóa và uy tín ngày càng cao trên thị trường.  
                    </p>
					
				</div>
			</div>
		
		</div>', 1, N'vi', 0, 0, N'FRAboutUsStoryFiin', NULL, 1);
INSERT INTO [dbo].[StaticInformation] ([Id], [Name], [Content], [Status], [Language], [Delete], [ParentId], [Code], [Data], [PortalId]) VALUES (3001080, N'AboutUs - TimeLine', N'<section id="TimeLine" class="timeline-section">
	<style>
		.nav-btn,.year-tab{cursor:pointer;transition:.2s}#TimeLine{background:url(/Data/FR/about_hisbanner.jpg) top/cover no-repeat}.timeline-title{text-align:center;font-size:32px;font-weight:700;margin-bottom:32px;color:#fff;padding-top:60px}.timeline-tabs{display:flex;justify-content:center;gap:32px;margin-bottom:32px;flex-wrap:nowrap;overflow-x:auto;padding-bottom:10px}.year-tab{padding:10px 28px;border-radius:30px;border:none;font-size:18px;font-weight:600;background:rgba(255,255,255,.15);color:#fff;white-space:nowrap}.nav-btn,.year-tab.active{background:#fff;color:#06c}.year-tab.active{box-shadow:0 4px 15px rgba(255,255,255,.3)}.timeline-slider{background:#fff;border-radius:16px;padding:50px;display:flex;align-items:center;position:relative;gap:20px}.timeline-content{display:grid;grid-template-columns:1fr 1fr;gap:24px}.timeline-text{display:flex;flex-direction:column;justify-content:space-between}.timeline-text h3{font-size:24px;font-weight:600;margin:0 0 -25px;color:#06c}.gach{border-bottom:1px solid #093461;width:60px;margin:0 0 12px}.timeline-text p{font-size:28px;font-weight:600;line-height:1.5;color:#093461;text-align:justify}.timeline-img{object-fit:cover;border-radius:12px}.timeline-text .img-his{margin-top:0}.nav-btn{width:46px;height:46px;border-radius:50%;border:2px solid #fff;font-size:20px;box-shadow:0 4px 12px rgba(0,0,0,.12),0 0 8px rgba(255,255,255,.6)}.nav-btn:hover{background:#1c98ef;color:#fff}.prev-btn{position:absolute;left:-25px}.next-btn{position:absolute;right:-25px}
	</style>
	<div class="container pb-5">
		<h2 class="timeline-title">Lịch sử hình thành và phát triển</h2>
		<!-- TAB YEARS -->
		<div class="timeline-tabs" id="yearTabs">
			<div class="tab-spacer"></div> <!-- spacer -->
			<button class="year-tab active" data-index="0">2008</button>
			<button class="year-tab" data-index="1">2020</button>
			<button class="year-tab" data-index="2">2021</button>
			<button class="year-tab" data-index="3">2022</button>
			<button class="year-tab" data-index="4">2025</button>
		</div>

		<!-- SLIDER CONTENT -->
		<div class="timeline-slider">
			<button class="nav-btn prev-btn" id="prevBtn">
				<i class="fa fa-arrow-left"></i>
			</button>

			<div class="timeline-content" id="timelineContent">
				<!-- CONTENT WILL BE LOADED BY JS -->
			</div>

			<button class="nav-btn next-btn" id="nextBtn">
				<i class="fa fa-arrow-right"></i>
			</button>
		</div>
	</div>

    <script>
		const timelineData = [
			{
				year: "2008",
				title: "",
				text: `<span style="color: #0066CC;">FiinGroup (tiền thân là StoxPlus)</span> được thành lập, ban đầu tập trung cung cấp dữ liệu thị trường chứng khoán.`,
				img: "/Data/FR/about_hisdetail.jpg"
			},
			{
				year: "2020",
				title: "",
				text: `FiinGroup được Bộ Tài chính cấp phép và chính thức ra mắt dịch vụ <span style="color: #0066CC;">Xếp hạng Tín nhiệm FiinRatings</span>.`,
				img: "/Data/FR/about_hisdetail.jpg"
			},
			{
				year: "2021",
				title: "",
				text: `Thiết lập quan hệ đối tác với <span style="color: #d6002a;">S&P Global Ratings</span> và <span style="color: #0066CC;">Asian Development Bank (ADB)</span>.`,
				img: "/Data/FR/about_hisdetail.jpg"
			},
			{
				year: "2022",
				title: "",
				text: `Được <span style="color: #0066CC;">CBI</span> công nhận là đơn vị Ủy quyền Xác nhận Trái phiếu Xanh/ Khoản vay Xanh.<br>Đổi tên thành <span style="color: #0066CC;">Công ty Cổ phần FiinRatings</span> sau khi tổ chức lại mô hình sở hữu.`,
				img: "/Data/FR/about_hisdetail.jpg"
			},
			{
				year: "2025",
				title: "",
				text: `Nâng tầm Hợp tác Quốc tế qua khoản Đầu tư Chiến lược từ <span style="color: #d6002a;">S&P Global</span>, đánh dấu vai trò cổ đông chiến lược với tỷ lệ sở hữu <span style="color: #d6002a;">43,4%</span>.`,
				img: "/Data/FR/about_hisdetail.jpg"
			}
		];

		let currentIndex = 0;

		const contentBox = document.getElementById("timelineContent");
		const yeartabs = document.querySelectorAll(".year-tab");

		function loadSlide(index) {
			currentIndex = index;
			// update tabs
			yeartabs.forEach(tab => tab.classList.remove("active"));
			yeartabs[index].classList.add("active");
			// load content
			const d = timelineData[index];
			contentBox.innerHTML = `
				<div class="timeline-text" style=''justify-content: normal;''>
					<div class="img-his mb-4"><img src="/Data/2025/FR/Logo-dong-tien.png" style=''height: 30px;''></div>
					<p>${d.text}</p>
				</div>
				<img src="${d.img}" alt=''logo-mini'' class="timeline-img">
			`;
		}

		// Tab click
		yeartabs.forEach(tab => {
			tab.addEventListener("click", () => {
				const idx = parseInt(tab.dataset.index);
				loadSlide(idx);
			});
		});
		// Prev / Next
		document.getElementById("prevBtn").onclick = () => {
			const next = (currentIndex - 1 + timelineData.length) % timelineData.length;
			loadSlide(next);
		};
		document.getElementById("nextBtn").onclick = () => {
			const next = (currentIndex + 1) % timelineData.length;
			loadSlide(next);
		};
		// Load first slide
		loadSlide(0);
	</script>
</section>', 1, N'vi', 0, 0, N'FRAboutUsTimeLine', NULL, 1);
INSERT INTO [dbo].[StaticInformation] ([Id], [Name], [Content], [Status], [Language], [Delete], [ParentId], [Code], [Data], [PortalId]) VALUES (3001081, N'AboutUs - Teams', N'<section id="UserTeam" class="py-5">
    <style>
.price-title{margin-bottom:20px}.tab-container{display:inline-flex;justify-content:center;border:1px solid #0078d4;border-radius:6px;overflow:hidden;font-family:Arial,sans-serif;font-size:14px}.tab{padding:8px 20px;border:none;background:#fff;color:#0078d4;cursor:pointer;transition:.2s;min-width:250px}.tab.active{background:#0078d4;color:#fff}.tab:not(.active):hover{background:#e6f0fb}.team-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(320px,1fr));gap:30px;justify-content:center;align-items:start}.member-card{align-items:center;text-align:center;padding:15px;border-radius:16px;overflow:hidden;transition:transform .3s,box-shadow .3s;width:100%;height:100%;border:1px solid transparent}.member-card:hover{transform:translateY(-8px);box-shadow:0 12px 24px rgba(0,0,0,.12)}.member-card img{max-width:100%}.member-info{padding:26px 0;text-align:left}.member-name{font-size:19px;font-weight:600;color:#06c;margin-bottom:6px}.member-title{font-size:16px;font-weight:500}.member-desc{margin-top:10px;text-align:justify;font-style:italic}
	.member-card .member-desc {
		display: none;
	}
	 .member-card,.narbarstory a,.team-grid>.team-grid{cursor:pointer}.about-main-box,.about-wrap{position:relative;z-index:1}.about-box p,.about-main-box p{line-height:1.6;text-align:justify}.narbarstory{padding:50px 0;display:flex;justify-content:space-around;align-items:center}.narbarstory a{color:#093461;text-decoration:none;font-size:18px;padding:8px 0;display:flex;justify-content:center;min-width:25%;transition:color .3s,border-bottom .3s;border-bottom:3px solid transparent}.narbarstory a.active,.narbarstory a:hover{color:#06c}.narbarstory a.active span,.narbarstory a:hover span{border-bottom:3px solid #06c;min-width:170px;text-align:center}.about-main-box{padding:15px 0;border-radius:12px;margin-bottom:20px}.about-main-box::before{content:"";position:absolute;inset:0;border-radius:inherit;z-index:-1}.about-main-box p{margin-bottom:12px;color:#093461;font-size:15px;padding-top:20px}.corner-decor{position:absolute;top:-65px;right:17%;width:110px;z-index:3;pointer-events:none}.about-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:25px}.about-box{background:border-box padding-box,border-box #fff;padding:25px;border-radius:12px;border:1px solid transparent;box-shadow:0 4px 12px rgba(0,76,152,.08);text-align:left;transition:transform .3s;background-image:linear-gradient(#f5f9ff,#f2f7ff),linear-gradient(to right,#034ea2,#53dfff)}.about-box:hover{transform:translateY(-5px)}.about-box .why-title{font-size:30px!important;height:42px!important}.about-box h3{font-size:20px;color:#064a9d;margin:15px 0}.about-box p{color:#093461}.abt-icon{width:40px;height:auto}.member-card img{width:100%}.member-card:hover .member-info,.team-grid>.team-grid:hover .member-info{height:100%;background:#fffffff5;position:absolute;left:0;right:0;bottom:0;top:0;padding:20px}.member-card:hover .member-info .member-desc{display:block}.member-card:hover .member-desc,.team-grid>.team-grid:hover .member-desc{opacity:1;max-height:400px}.tab-container{display:inline-flex;justify-content:center;border:1px solid #0066cf!important;border-radius:26px;overflow:hidden;font-size:16px}.tab.active{background:#0066cf!important}.testimonial-media .img{width:100%!important;height:420px}.testimonial-card{padding:0!important}.testimonial-card .align-items-stretch{background:#034ea2}.testimonial-card .testimonial-copy{padding:43px}.testimonial-card .testimonial-copy .quote{font-size:20px;color:#fff!important;height:auto}.testimonial-card .testimonial-copy .name{color:#fff!important}.owl-prev{margin-left:4px!important}.owl-theme .owl-nav [class*=owl-]{font-size:22px}.owl-next,.owl-prev{border:none!important}
    #Partner
    {
        height: 200px!important;
    }
    </style>
    <div class="container">
        <h2 id="team-title" style="text-align: center;" class="price-title mb-5">Đội ngũ quản lý</h2>
        <div style="text-align: center;">
            <div class="tab-container mb-5">
                <button class="tab active">Hội đồng quản trị</button>
                <button class="tab">Ban điều hành</button>
            </div>
        </div>
        <div id="hdqt" class="tab-content">
            <div class="team-grid">
                <div class="member-card">
                    <img src="/Data/Banner/about_us1.png" alt="why" />
                    <div class="member-info">
                        <div class="member-name">Nguyễn Quang Thuân, FCCA</div>
                        <div class="member-title">
                            Chủ tịch kiêm Tổng Giám đốc
                        </div>
                        <div class="member-desc">
                          Ông là đồng sáng lập của FiinGroup và FiinRatings. Ông  từng là Chuyên viên Phân tích Đầu tư tại Vietnam Holding Asset Management Ltd và Quản lý tại bộ phận Dịch vụ Giao dịch của PwC tại Việt Nam và Sydney, Úc. 
                        </div>
                    </div>
                </div>
                <div class="member-card">
                    <img src="/Data/2025/FR/Doi-ngu-nhan-su/ritesh.png" alt="why" />
                    <div class="member-info">
                        <div class="member-name">Ritesh Maheshwari</div>
                        <div class="member-title">Thành viên HĐQT</div>
                        <div class="member-desc">
                            Ông có hơn 30 năm kinh nghiệm trong lĩnh vực thị trường vốn châu Á – Thái Bình Dương, xếp hạng tín nhiệm và xây dựng chiến lược. Ông từng dẫn dắt việc thành lập S&P Global (China) Ratings, Hiện tại, ông là thành viên Hội đồng Quản trị của TRIS Ratings (Thái Lan), Taiwan Ratings Corp., RAM Holdings (Malaysia) và PEFINDO (Indonesia).
