INSERT INTO [dbo].[StaticInformation] ([Id], [Name], [Content], [Status], [Language], [Delete], [ParentId], [Code], [Data], [PortalId]) VALUES (3001084, N'Product - Xếp hạng Tín nhiệm', N'<section id="FiinTrust" class="mb-5">
            <style>
                .narbartrust {
                    padding: 50px 0;
                    display: flex;
                    justify-content: space-around;
                    align-items: center;
                }

                .narbartrust a {
                    color: #093461;
                    text-decoration: none;
                    font-size: 18px;
                    padding: 8px 10px;
                    display: flex;
                    justify-content: center;
                    min-width: 20%;
                    transition: color 0.3s, border-bottom 0.3s;
                    cursor: pointer;
                    border-bottom: 3px solid transparent;
                }

                .narbartrust a.active,
                .narbartrust a:hover {
                    color: #0066CC;
                    border-bottom: 3px solid #093461;
                }

                .info-fiinrate p {
                    color: #093461;
                }

                /* ===== Các box xếp hạng ===== */
                .method-grid {
                    display: grid;
                    grid-template-columns: repeat(auto-fit, minmax(350px, 1fr));
                    gap: 50px;
                    margin-top: 60px;
                }

                .bg-method1 {
                    background: url(''/Data/2025/FR/banner-metho/op2.png'') no-repeat center center;
                    background-size: cover;
                    border-radius: 12px;
                    position: relative;
                }

                .bg-method2 {
                    background: url(''/Data/2025/FR/banner-metho/op4.png'') no-repeat center center;
                    background-size: cover;
                    border-radius: 12px;
                    position: relative;
                }

                .method-box {
                    position: relative;
                    z-index: 2;
                    height: 260px;
                    display: flex;
                    flex-direction: column;
                    justify-content: flex-end;
                    padding: 0px 20px;
                    color: #fff;
                    border: none;
                    box-shadow: 0 4px 10px rgba(0, 76, 152, 0.05);
                }

                .bg-method1,
                .bg-method2 {
                    position: relative;
                    background-size: cover;
                    background-position: center;
                    border-radius: 12px;
                    overflow: hidden;
                }

                /* Overlay sáng hơn */
                .bg-method1::before,
                .bg-method2::before {
                    content: "";
                    position: absolute;
                    inset: 0;
                    /* background: rgba(0, 0, 0, 0.25); */
                    /* từ 0.55 → 0.25 */
                    z-index: 1;
                }

                /* Nội dung nổi lên trên overlay */
                .method-box {
                    position: relative;
                    z-index: 2;
                }

                .method-box h2 {
                    color: #fff;
                    font-size: 28px;
                    font-weight: 700;
                    z-index: 2;
                }
                .method-box:hover {
                    transform: translateY(-5px);
                }


                .method-box .method-title {
                    font-size: 24px;
                    margin-top: 15%;
                }
              	.method-grid p {
                  font-size: 14px;
                  font-weight: 400;
                  color: #093461;
				}
              	.bg-method1:hover, .bg-method2:hover {
                    background: linear-gradient(180deg, rgba(255, 255, 255, 0) 26.44%, #C3E4F6 100%), #FFFFFF;
                    border-radius: 10px;
                }
                    .bg-method1:hover h2, .bg-method2:hover h2 {
                        color: #093461;
                    }
                    .bg-method1:hover .method-none, .bg-method2:hover .method-none {
                        display: block;
                    }
                .method-none{display:none;}
            </style>
            <div class="container">
                <div class="narbartrust">
                  <a href="#FiinTrust" class="active">Tổng quan</a>
                  <a href="#OutStand">Dấu ấn thị trường</a>
                  <a href="#WhyLastest">Giá trị nổi bật</a>
                  <a href="#Customer">Khách hàng của chúng tôi</a>
                  <a href="#UserTeam">Đội ngũ chuyên môn</a>
                </div>
                <div class="whylastest pb-4">
                    <h2 class="price-title mb-2 text-center"><span style="color: #0066CC;">Xếp hạng Tín nhiệm </span> là gì?</h2>
                    <div class="row row2 pt-5">
                        <div class="col-sm-4 mb-2">
                          	<div class="why-header"><div class="icon-box"><img src="/Data/Banner/why1.png" alt="why" loading="lazy"></div><h2 class="why-title w700">Ý kiến về rủi ro tín dụng</h2></div>
                            <img src="/Data/Icon/icon-line.svg" alt="line">
                            <p class="why-desc">Xếp hạng tín nhiệm phản ánh ý kiến độc lập về khả năng tổ chức phát hành thực hiện đầy đủ, đúng hạn nghĩa vụ nợ, không phải cam kết tránh vỡ nợ.
                            </p>
                        </div>
                        <div class="col-sm-4 mb-2 pr-2">
                          	<div class="why-header"><div class="icon-box"><img src="/Data/Banner/why2.png" alt="why" loading="lazy"></div><h2 class="why-title w700">Hệ thống thang điểm</h2></div>
                            <img src="/Data/Icon/icon-line.svg" alt="line">
                            <p class="why-desc">Thang điểm xếp hạng tín nhiệm gồm nhiều mức từ ''AAA'' đến ''C'', thể hiện các cấp độ rủi ro khác nhau liên quan đến khả năng thanh toán nghĩa vụ nợ của Tổ chức phát hành.
                        </div>
                        <div class="col-sm-4 mb-2">
                          	<div class="why-header"><div class="icon-box"><img src="/Data/Banner/why3.png" alt="why" loading="lazy"></div><h2 class="why-title w700">Ký hiệu trong mức điểm</h2></div>
                            <img src="/Data/Icon/icon-line.svg" alt="line">
                            <p class="why-desc">Ký hiệu cộng và trừ được sử dụng để phân biệt chi tiết hơn trong cùng một mức xếp hạng; dấu trừ không mang ý nghĩa tiêu cực về hoạt động hay khả năng trả nợ.
                            </p>
                        </div>
                      </div>
                  
                      <div class="row row2 pt-3">
                        <div class="col-sm-4 mb-2">
                          	<div class="why-header"><div class="icon-box"><img src="/Data/Banner/product_why3.png" alt="why" loading="lazy"></div><h2 class="why-title w700">Cơ chế theo dõi xếp hạng</h2></div>
                            <img src="/Data/Icon/icon-line.svg" alt="line">
                            <p class="why-desc">Điểm và triển vọng xếp hạng được theo dõi, rà soát định kỳ tối thiểu 6 tháng một lần, hoặc cập nhật khi xuất hiện sự kiện trọng yếu ảnh hưởng đến khả năng trả nợ.
                            </p>
                        </div>
                        <div class="col-sm-4 mb-2 pr-2">
                          	<div class="why-header"><div class="icon-box"><img src="/Data/Banner/product_why6.png" alt="why" loading="lazy"></div><h2 class="why-title w700">Khung tiêu chí đánh giá</h2></div>
                            <img src="/Data/Icon/icon-line.svg" alt="line">
                            <p class="why-desc">Xếp hạng tín nhiệm được đánh giá dựa trên nhiều nhóm tiêu chí, gồm ngành và triển vọng, rủi ro kinh doanh, sức khỏe tài chính, quản trị, cùng các mối liên kết liên quan.
                        </div>
                        <div class="col-sm-4 mb-2">
                          	<div class="why-header"><div class="icon-box"><img src="/Data/Banner/solution_why.png" alt="why" loading="lazy"></div><h2 class="why-title w700">Sự độc lập và khách quan</h2></div>
                            <img src="/Data/Icon/icon-line.svg" alt="line">
                            <p class="why-desc">Hoạt động xếp hạng tín nhiệm được thực hiện nguyên tắc độc lập, tuân thủ quy tắc đạo đức, kiểm soát xung đột lợi ích và tiêu chuẩn đảm bảo chất lượng.
                            </p>
                        </div>

                        <div class="method-grid">
                          <!-- <a href="/vi/san-pham-va-dich-vu.html" title="Xếp hạng Tổ chức phát hành"> !-->
                            <div class="method-box bg-method1">
                                <h2 class="method-title">Xếp hạng Tổ chức phát hành</h2>
                              	<img class="method-none" src="/Data/Icon/icon-line.svg" height="2" width="156" alt="line">
                                <p class="pt-2 method-none">
                                    Xếp hạng tín nhiệm Tổ chức phát hành là một ý kiến đánh giá về mức độ tín nhiệm tổng thể của Tổ chức phát hành. Ý kiến này tập trung vào năng lực và sự sẵn sàng đáp ứng các cam kết tài chính khi đến hạn của Tổ chức phát hành, và không áp dụng cho bất kỳ nghĩa vụ tài chính cụ thể nào.
                                </p>
                            </div>
                          </a>

                          <!-- <a href="/vi/san-pham-va-dich-vu.html" title="Xếp hạng Công cụ nợ"> !-->
                            <div class="method-box bg-method2">
                                <h2 class="method-title">Xếp hạng Công cụ nợ</h2>
                              	<img class="method-none" src="/Data/Icon/icon-line.svg" height="2" width="156" alt="line">
                                <p class="pt-2 method-none">
                                    Xếp hạng tín nhiệm Công cụ nợ là một ý kiến đánh giá về mức độ tín nhiệm đối với một nghĩa vụ tài chính cụ thể, hoặc một chương trình tài trợ cụ thể (bao gồm xếp hạng đối với các khoản nợ ngắn, trung và dài hạn). Ý kiến này phản ánh quan điểm của FiinRatings về năng lực và sự sẵn sàng đáp ứng các cam kết tài chính của Tổ chức phát hành phát hành khi nghĩa vụ nợ đến hạn.
                                </p>
                            </div>
                           </a>

                        </div>

                    </div>
                </div>
            </div>
            <script>
                document.addEventListener(''DOMContentLoaded'', () => {
            const links = document.querySelectorAll(''.narbartrust a'');
		            links.forEach(link => {
			            link.addEventListener(''click'', (e) => {
				            e.preventDefault();
				            // Xóa class active
				            links.forEach(l => l.classList.remove(''active''));
				            link.classList.add(''active'');
				            // Lấy ID mục tiêu
				            const targetId = link.getAttribute(''href'')?.trim();
				            // Nếu href null hoặc không phải id hợp lệ thì thoát
				            if (!targetId || !targetId.startsWith("#")) {
					            return;
				            }
				            const targetEl = document.querySelector(targetId);
				            if (targetEl) {
					            targetEl.scrollIntoView({
						            behavior: "smooth",
						            block: "start"
					            });
				            }
			            });
		            });
	            });
            </script>
        </section>', 1, N'vi', 0, 0, N'FRProductXepHang', NULL, 1);
INSERT INTO [dbo].[StaticInformation] ([Id], [Name], [Content], [Status], [Language], [Delete], [ParentId], [Code], [Data], [PortalId]) VALUES (3001085, N'Product - Banner', N'<section id="SliderBanner">
