INSERT INTO [dbo].[StaticInformation] ([Id], [Name], [Content], [Status], [Language], [Delete], [ParentId], [Code], [Data], [PortalId]) VALUES (3001086, N'Methodology - Phương pháp luận', N'<section id="Report" class="py-10 mb-5">
