INSERT INTO [dbo].[StaticInformation] ([Id], [Name], [Content], [Status], [Language], [Delete], [ParentId], [Code], [Data], [PortalId]) VALUES (3001088, N'Methodology - FiinMethod', N'<section id="FiinMethod" class="mb-5">
	<style>
		.narbarmodel{padding:50px 0;display:flex;justify-content:space-around;align-items:center}.narbarmodel a{color:#093461;text-decoration:none;font-size:18px;padding:8px 0;display:flex;justify-content:center;min-width:33%;transition:color .3s,border-bottom .3s;cursor:pointer;border-bottom:3px solid transparent}.narbarmodel a.active,.narbarmodel a:hover{color:#06c;font-weight:600;border-bottom:3px solid #093461}.bg-method1:hover h2,.bg-method2:hover h2,.info-fiinrate p{color:#093461}.method-wrap{position:relative;z-index:1}.method-box,.method-box h2,.method-box p{z-index:2;color:#fff}.method-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(350px,1fr))!important;gap:50px;margin-top:60px}.bg-method1{background:url(''/Data/2025/FR/banner-metho/op2.png'') center center/cover no-repeat}.bg-method2{background:url(''/Data/2025/FR/banner-metho/op4.png'') center center/cover no-repeat}.method-box{height:300px;display:flex;flex-direction:column;justify-content:flex-end;padding:0 20px;border:none;box-shadow:0 4px 10px rgba(0,76,152,.05);position:relative}.bg-method1,.bg-method2{position:relative;background-size:cover;background-position:center;border-radius:12px;overflow:hidden}.bg-method1::before,.bg-method2::before{content:"";position:absolute;inset:0;z-index:1}.gach{border-bottom:2px solid #c3e4f6;width:30%}.gach2{border-bottom:2px solid #fff;width:30%}.method-box h2{font-size:28px;font-weight:700}.method-box p{font-size:14px;text-align:justify;text-justify:inter-word}.method-box:hover{transform:translateY(-5px)}.method-box .sub-section{display:flex;align-items:flex-start;margin-bottom:15px;padding-top:15px}.method-box .sub-section p{color:#fff;margin:0}.method-box .method-title{font-size:24px;margin:15% 0 15px}.method-grid p{font-size:14px;font-weight:400;color:#093461}.bg-method1:hover,.bg-method2:hover{background:linear-gradient(180deg,rgba(255,255,255,0) 26.44%,#c3e4f6 100%),#fff;border-radius:10px}.bg-method1:hover .method-none,.bg-method2:hover .method-none{display:block}.method-none{display:none}
	</style>
	<div class="container">
		<div class="narbarmodel">
			<a href="#FiinMethod" class="active">Chi tiết mô hình</a>
			<a href="#Model">Mô hình xếp hạng tổng thể</a>
			<a href="#MethodNews">Phương pháp luận xếp hạng tín nhiệm</a>
		</div>
		<div class="why pb-4">
			<h2 class="price-title mb-4">Chi tiết <span style="color: #0066CC;"> Phương pháp </span></h2>
			<div class="method-wrap">
				<div class="info-fiinrate">
					<p>
						Phương pháp xếp hạng tín nhiệm mô tả cách tiếp cận của FiinRatings trong việc đánh giá
						rủi ro tín dụng của các Tổ chức phát hành và các công cụ nợ, cũng như giải thích chi
						tiết cách đánh giá đối với các yếu tố trong khung xếp hạng tín nhiệm cho các đối tượng
						khác nhau.
					</p>
				</div>
			</div>
			<div class="method-grid">
				<div class="method-box bg-method1">
					<h2 class="method-title">
						Xếp hạng Tổ chức phát hành
					</h2>
					<img class="method-none" src="https://fr.ept.io.vn/Data/Icon/icon-line.svg" height="2" width="156" alt="line">
						<p class="pt-2 method-none">
							Mốc xếp hạng tín nhiệm cơ bản: được xác định bằng việc đánh giá kết hợp hồ sơ rủi ro kinh doanh và hồ sơ rủi ro tài chính của đơn vị phát hành (đối với doanh nghiệp phi tài chính), hoặc đánh giá các yếu tố rủi ro chung của ngành (đối với các định chế tài chính).
                          <br>Điểm xếp hạng tín nhiệm đơn lẻ (“SACP”): là mốc xếp hạng tín nhiệm cơ bản được điều chỉnh theo tác động của các yếu tố điều chỉnh. Việc phân tích các yếu tố này có thể dẫn đến việc nâng, hạ hoặc không ảnh hưởng đến mốc xếp hạng tín nhiệm cơ bản.
                          <br>Điểm xếp hạng tín nhiệm Tổ chức phát hành (“ICR”): là kết quả của sự kết hợp giữa điểm XHTN đơn lẻ và các yếu tố ảnh hưởng từ bên ngoài, ví dụ như Chính phủ hoặc Tập đoàn.
						</p>
	
				</div>

				<div class="method-box bg-method2">
					<h2 class="method-title">
						Xếp hạng Công cụ nợ
					</h2>
					<img class="method-none" src="https://fr.ept.io.vn/Data/Icon/icon-line.svg" height="2" width="156" alt="line">
						<p class="pt-2 method-none">
							Xếp hạng công cụ nợ có thời hạn phụ thuộc vào kỳ hạn của công cụ nợ. Ngắn hạn được hiểu là dưới 1 năm, trung hạn từ 1-5 năm, dài hạn trên 5 năm. Điểm xếp hạng của công cụ nợ được theo dõi và cập nhật căn cứ vào sức mạnh tài chính, rủi ro thanh khoản của Tổ chức phát hành và các yếu tố ảnh hưởng đến khả năng thanh toán khi nghĩa vụ tài chính đến hạn.
                          <br>Khi thực hiện xếp hạng tín nhiệm công cụ nợ, FiinRatings thực hiện điều chỉnh tăng hoặc giảm so với điểm xếp hạng tín nhiệm Tổ chức phát hành tùy theo ảnh hưởng bởi các yếu tố đặc thù liên quan đến công cụ nợ, ví dụ như các giao ước tài chính, tài sản bảo đảm, thứ tự ưu tiên trả nợ,…
						</p>
				</div>

			</div>

		</div>
	</div>
	<script>
		document.addEventListener(''DOMContentLoaded'', () => {
			const links = document.querySelectorAll(''.narbarmodel a'');
					links.forEach(link => {
						link.addEventListener(''click'', (e) => {
							e.preventDefault();
							// Xóa class active
							links.forEach(l => l.classList.remove(''active''));
							link.classList.add(''active'');
							// Lấy ID mục tiêu
							const targetId = link.getAttribute(''href'')?.trim();
							// Nếu href null hoặc không phải id hợp lệ thì thoát
							if (!targetId || !targetId.startsWith("#")) {
								return;
							}
							const targetEl = document.querySelector(targetId);
							if (targetEl) {
								targetEl.scrollIntoView({
									behavior: "smooth",
									block: "start"
								});
							}
						});
					});
				});
	</script>
</section>', 1, N'vi', 0, 0, N'FRMethodologyFiinMethod', NULL, 1);
