INSERT INTO [dbo].[StaticInformation] ([Id], [Name], [Content], [Status], [Language], [Delete], [ParentId], [Code], [Data], [PortalId]) VALUES (3001094, N'Business - FiinMethod', N'<section id="FiinMethod" class="mb-5">
    <style>
        .narbarprocess {
            padding: 50px 0;
            display: flex;
            justify-content: space-around;
            align-items: center;
        }

            .narbarprocess a {
                color: #093461;
                text-decoration: none;
                font-size: 18px;
                padding: 8px 0;
                display: flex;
                justify-content: center;
                min-width: 33.3%;
                transition: color 0.3s, border-bottom 0.3s;
                cursor: pointer;
                border-bottom: 3px solid transparent;
            }

                .narbarprocess a.active,
                .narbarprocess a:hover {
                    color: #0066CC;
                    font-weight: 600;
                    border-bottom: 3px solid #093461;
                }

        .company-box {
            border: 1px solid #bcd7ff;
            border-radius: 12px;
            padding: 20px 25px;
            margin: 20px 0;
            /* border gradient bo góc mượt */
            border: 1px solid transparent;
            background-image: linear-gradient(#fff, #fff), linear-gradient(to right, #0018A8, #166BF2, #3B7EEE);
            background-origin: border-box;
            background-clip: padding-box, border-box;
        }

        .item-box {
            margin-bottom: 20px;
        }

        .item-title {
            font-size: 14px;
            color: #093461;
            margin-bottom: 4px;
        }

        .item-value {
            font-size: 16px;
            font-weight: 500;
            color: #0066CC;
        }

        .table-wrapper {
            width: 100%;
            overflow-x: auto;
            margin-top: 20px;
        }

        .info-table {
            width: 100%;
            border-collapse: collapse;
            background: #fff;
            font-size: 15px;
        }

            .info-table th {
                text-align: left;
                padding: 14px 12px;
                color: #034EA2;
                font-weight: 700;
                border-bottom: 1px solid #e4e6e9;
                background: #F7F8F9;
            }

            .info-table td {
                padding: 14px 12px;
                border-bottom: 1px solid #e7eef9;
            }

                .info-table td:first-child {
                    width: 60px;
                    font-weight: 600;
                    text-align: center;
                }

                .info-table td a {
                    color: #0066cc;
                    font-weight: 500;
                    text-decoration: none;
                }

                    .info-table td a:hover {
                        text-decoration: underline;
                    }

                .info-table td .cell-item {
                    margin-bottom: 5px;
                    padding: 10px 0;
                    border-bottom: 1px solid #e7eef9;
                }

                    .info-table td .cell-item:last-child {
                        margin-bottom: 0;
                        border-bottom: none;
                    }



        .strong-money {
            color: #0066cc;
            font-weight: 700;
        }

        .link {
            border-bottom: 1px solid;
            color: #2E90FA;
        }

        @media (max-width: 768px) {
            .narbarprocess {
                padding: 20px 0;
                display: flex;
                flex-wrap: nowrap;
                overflow-x: auto;
                /* scroll ngang */
                gap: 20px;
                scrollbar-width: none;
            }

                .narbarprocess::-webkit-scrollbar {
                    display: none;
                }

                .narbarprocess a {
                    flex: 0 0 auto;
                    min-width: max-content;
                    font-size: 16px;
                    padding: 10px 5px;
                    border-bottom: 2px solid transparent;
                }

                    .narbarprocess a.active,
                    .narbarprocess a:hover {
                        border-bottom: 2px solid #0066CC;
                        color: #0066CC;
                        font-weight: 600;
                    }

            .company-box {
                padding: 16px;
            }

            .item-box {
                margin-bottom: 16px;
            }
        }
    </style>
    <div class="container">
        <div class="narbarprocess">
            <a href="#FiinMethod" class="active">Hồ sơ pháp lý</a>
            <a href="#ShareholderTable">Cơ cấu cổ đông</a>
            <a href="#FinancialReport">Báo cáo tài chính</a>
        </div>

        <h2 class="price-title mb-5">Hồ sơ pháp lý</h2>
