INSERT INTO [dbo].[StaticInformation] ([Id], [Name], [Content], [Status], [Language], [Delete], [ParentId], [Code], [Data], [PortalId]) VALUES (3001096, N'Business - Báo cáo tài chính', N'<section id="FinancialReport" class="mb-5">
    <style>
        .report-grid {
            display: grid;
            grid-template-columns: repeat(5, 1fr);
            gap: 24px;
        }

        .report-card {
            border-radius: 12px;
            background: #fff;
            border: 1px solid #e1ecff;
            padding: 10px;
            transition: 0.2s ease;
        }

            .report-card:hover {
                box-shadow: 0 4px 20px rgba(0, 0, 0, 0.06);
            }

            .report-card img {
                width: 100%;
                border-radius: 12px 12px 0 0;
              display:none;
            }

        .report-title {
            font-size: 16px;
            font-weight: 600;
            padding: 20px 0 0;
            color: #1D2939;
        }

        .tag-year {
            display: inline-block;
            background: #E8F5FF;
            color: #0066CC;
            padding: 4px 12px;
            border-radius: 12px;
            font-size: 13px;
            font-weight: 600;
        }

        .link-detail {
            display: inline-block;
            margin-top: 10px;
            color: #0066CC;
            font-weight: 600;
            text-decoration: none;
            padding: 15px 0;
            font-size: 16px;
        }

            .link-detail:hover {
                text-decoration: underline;
            }

        .main-title {
            font-size: 25px;
            font-weight: 700;
            color: #093461;
            margin-bottom: 20px;
            line-height: 1.5;
            padding-top: 60px;
        }

        .year-tabs {
            display: flex;
            width: 100%;
            margin-bottom: 25px;
            padding-bottom: 8px;
        }

        .tab-item {
            flex: 1;
            /* mỗi tab = 25% */
            text-align: center;
            background: none;
            border: none;
            font-size: 18px;
            font-weight: 600;
            color: #7A8CA5;
            cursor: pointer;
            transition: 0.2s;
            padding-bottom: 8px;
        }

            .tab-item.active {
                color: #0066CC;
                border-bottom: 3px solid #0066CC;
            }

            .tab-item:hover {
                color: #0066CC;
            }

        .sub-title {
            font-size: 20px;
            font-weight: 600;
            color: #093461;
            margin-bottom: 20px;
        }

        .ranking-table {
            width: 100%;
            border-collapse: collapse;
        }

            .ranking-table th {
                background: #F5F8FF;
                padding: 14px;
                font-size: 14px;
                color: #093461;
                text-align: left;
                border-bottom: 1px solid #E4EEF9;
            }

            .ranking-table td {
                padding: 14px;
                font-size: 14px;
                border-bottom: 1px solid #EEF3FB;
            }

            .ranking-table tbody td {
                background-color: #fff;
            }

            .ranking-table .header-row th {
                background-color: #F7F8F9;
                color: #034EA2;
                font-weight: 600;
                padding: 10px 8px;
            }

            .ranking-table .col-number,
            .ranking-table .col-percent {
                color: #326fb3;
            }

            .ranking-table .col-name {
                color: #093461;
                text-align: left;
                padding-left: 15px;
                font-weight: 500;
            }

        .col-stt {
            width: 60px;
            text-align: center;
            font-weight: 600;
            color: #093461;
        }

        .nav-buttons {
            display: flex;
            gap: 20px;
            padding-top: 15px;
        }

        .circle-btn {
            width: 48px;
            height: 48px;
            border-radius: 50%;
            border: 1px solid #0066CC;
            background: transparent;
            color: #0066CC;
            font-size: 18px;
            display: flex;
            align-items: center;
            justify-content: center;
            cursor: pointer;
            transition: 0.2s ease;
        }

            .circle-btn:hover {
                background: #0066CC;
                color: #fff;
            }

        @media (max-width: 576px) {
            .report-grid {
                grid-template-columns: repeat(2, 1fr);
                gap: 16px;
            }
        }
    </style>
    <div class="container">
        <h2 class="price-title">Báo cáo tài chính</h2>

        <div class="report-grid">
            <div class="report-card">
                <a href="https://fiinratings.vn/upload/docs/Company_Disclosure/FiinRating_AuditedFS_2024_VN.pdf" target="_blank" title="Báo cáo">
                    <img src="/Data/FR/2020.png" alt="report">
                    <h4 class="report-title">Báo cáo tài chính đã được kiểm toán</h4>
                    <span class="tag-year">2024</span><br>
                    <span class="link-detail"href="https://fiinratings.vn/upload/docs/Company_Disclosure/FiinRating_AuditedFS_2024_VN.pdf" target="_blank" >Xem chi tiết <i class="fa fa-arrow-right"></i></span>
                </a>
            </div>

            <div class="report-card">
                <a href="https://fiinratings.vn/upload/docs/Company_Disclosure/FiinGroup_AuditedFS2023_VN.pdf" target="_blank" title="Báo cáo">
                    <img src="/Data/FR/2020.png" alt="report">
                    <h4 class="report-title">Báo cáo tài chính đã được kiểm toán</h4>
                    <span class="tag-year">2023</span><br>
                    <span class="link-detail">Xem chi tiết <i class="fa fa-arrow-right"></i></span>
                </a>
            </div>

            <div class="report-card">
                <a href="https://fiinratings.vn/upload/docs/Company_Disclosure/FiinRatings_AuditedFS2022_VN_27March2023.pdf" target="_blank" title="Báo cáo">
                    <img src="/Data/FR/2020.png" alt="report">
                    <h4 class="report-title">Báo cáo tài chính đã được kiểm toán</h4>
                    <span class="tag-year">2022</span><br>
                    <span class="link-detail">Xem chi tiết <i class="fa fa-arrow-right"></i></span>
                </a>
            </div>

            <div class="report-card">
                <a href="https://fiinratings.vn/upload/docs/Company_Disclosure/FiinGroup_AuditedFS2021_VN.pdf" target="_blank" title="Báo cáo">
                    <img src="/Data/FR/2020.png" alt="report">
                    <h4 class="report-title">Báo cáo tài chính đã được kiểm toán</h4>
                    <span class="tag-year">2021</span><br>
                    <span class="link-detail">Xem chi tiết <i class="fa fa-arrow-right"></i></span>
                </a>
            </div>
          
           <div class="report-card">
                <a href="https://fiinratings.vn/upload/docs/Company_Disclosure/FiinGroup_AuditedFS2020_VN.pdf" target="_blank" title="Báo cáo">
                    <img src="/Data/FR/2020.png" alt="report">
                    <h4 class="report-title">Báo cáo tài chính đã được kiểm toán</h4>
                    <span class="tag-year">2020</span><br>
                    <span class="link-detail">Xem chi tiết <i class="fa fa-arrow-right"></i></span>
                </a>
            </div>

        </div>

        <div class="nav-buttons">
            <button class="circle-btn">
                <i class="fa fa-arrow-left"></i>
            </button>

            <button class="circle-btn">
                <i class="fa fa-arrow-right"></i>
            </button>
        </div>

        <h2 class="main-title">
            Danh sách các tổ chức được xếp hạng tín nhiệm có mức chi phí dịch vụ xếp hạng tín nhiệm
            chiếm trên 5% tổng doanh thu từ hoạt động xếp hạng tín nhiệm của doanh nghiệp.
        </h2>

        <!-- Tabs năm -->
        <div class="year-tabs" id="reportTabs">
            <button class="tab-item active" data-tab="report_2024">2024</button>
            <button class="tab-item" data-tab="report_2023">2023</button>
            <button class="tab-item" data-tab="report_2022">2022</button>
            <button class="tab-item" data-tab="report_2021">2021</button>
        </div>
        <div id="report_2024" class="report-content">
            <h3 class="sub-title">Năm tài chính kết thúc ngày 31/12/2024</h3>
            <table class="ranking-table">
                <thead>
                    <tr class="header-row">
                        <th>STT</th>
                        <th style="width: 55%;">
                            Tổ chức được xếp hạng tín nhiệm có mức phí chiếm trên 5% tổng doanh thu từ hoạt động xếp
                            hạng tín nhiệm của doanh nghiệp trong năm tài chính liền kề trước thời điểm công bố
                            thông tin
                        </th>
                        <th>% tổng doanh thu từ hoạt động XHTN (2024)</th>
                        <th>% tổng doanh thu từ hoạt động XHTN (2023)</th>
                    </tr>
                </thead>
                <tbody>
                    <tr>
                        <td class="col-stt">1</td>
                        <td class="col-name">Ngân hàng Thương mại Cổ phần Quốc tế Việt Nam</td>
