INSERT INTO [dbo].[StaticInformation] ([Id], [Name], [Content], [Status], [Language], [Delete], [ParentId], [Code], [Data], [PortalId]) VALUES (3001098, N'Process - Quy trình xếp hạng', N'<section id="FiinMethod" class="mb-5">
    <style>
        .narbarprocess {
