        }

        .step-item {
            background: transparent;
        }

        .step-header {
            display: flex;
            align-items: center;
            gap: 12px;
        }


        .step-title {
            font-size: 22px;
            font-weight: 700;
            color: #0066CC;
            line-height: 1.5;
            margin: 0;
        }

        .step-text {
            margin-top: 10px;
            color: #093461;
            font-size: 15px;
            line-height: 150%;
            text-align: justify;
        }

        .custom-pagination-wrapper {
            display: flex;
            justify-content: space-between;
            /* mũi tên bên trái, dots bên phải */
            align-items: center;
            width: 100%;
            margin-top: 20px;
        }

        .pagination-arrows {
            display: flex;
            gap: 12px;
        }

        .arrow-btn {
            width: 48px;
            height: 48px;
            border-radius: 50%;
            border: 1.5px solid #0b6bd3;
            background: transparent;
            color: #0b6bd3;
            display: flex;
            align-items: center;
            justify-content: center;
            cursor: pointer;
            font-size: 16px;
        }

            .arrow-btn:hover {
                background: #e8f3ff;
            }

        .pagination-dots {
            display: flex;
            gap: 8px;
            align-items: center;
        }

            .pagination-dots .dot {
                width: 6px;
                height: 6px;
                border-radius: 50%;
                background: #c9c9c9;
            }

                .pagination-dots .dot.active {
                    width: 35px;
