INSERT INTO [dbo].[StaticInformation] ([Id], [Name], [Content], [Status], [Language], [Delete], [ParentId], [Code], [Data], [PortalId]) VALUES (3001100, N'Process - Các yêu cầu thông tin cơ bản', N'<section id="BasicInfo" class="mb-5">
    <style>
        .subtitle {
            margin-top: 20px;
            font-size: 18px;
            line-height: 150%;
            color: #093461;
            text-align: justify;
        }


        .acc-item {
            padding: 18px 0;
        }

        .acc-header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            cursor: pointer;
            font-size: 18px;
            font-weight: 600;
            color: #093461;
            padding: 10px 0;
            border-bottom: 1px solid #d6e4f5;
        }

        .acc-icon {
            width: 22px;
            height: 22px;
        }

        .acc-content {
            display: none;
            padding: 14px 0 5px 20px;
        }

        .acc-item.open .acc-content {
            display: block;
        }

        .acc-item.open .acc-icon {
            content: url("/Data/FR/minus-circle.png?v=1");
        }

        .acc-item:not(.open) .acc-icon {
            content: url("/Data/FR/add-circle.png?v=1");
        }

        .acc-content ul {
            list-style: none;
        }

        .acc-content li {
            position: relative;
            padding-left: 20px;
            margin-bottom: 6px;
        }

            .acc-content li::before {
                content: "";
                position: absolute;
                left: 0;
                top: 9px;
                width: 6px;
                height: 6px;
                background: #0B66C3;
                border-radius: 50%;
            }
    </style>
    <div class="container">
        <h2 class="price-title">
            Các <span style="color: #0066CC;">yêu cầu thông tin</span> cơ bản
        </h2>
        <p class="subtitle">
            Dưới đây là danh mục các thông tin cơ bản Tổ chức phát hành cần cung cấp cho FiinRatings để thực
            hiện xếp hạng tín nhiệm. Danh mục chi tiết sẽ được trao đổi cụ thể trong quá trình làm việc giữa hai
            bên
        </p>

        <div class="acc-item open">
            <div class="acc-header">
                <span>Thông tin về Hồ sơ Doanh nghiệp</span>
                <img class="acc-icon" src="/Data/FR/minus-circle.png?v=1" alt="close">
            </div>
            <ul class="acc-content">
                <li>Các hồ sơ pháp lý liên quan đến thành lập doanh nghiệp, chứng nhận đầu tư</li>
                <li>Thông tin về Hội đồng Quản trị/ Hội đồng Thành viên, Ban Điều hành</li>
                <li>Điều lệ, Quy chế hoạt động, Cơ cấu tổ chức</li>
                <li>Thông tin về các sản phẩm, dịch vụ chính</li>
            </ul>
        </div>

        <div class="acc-item">
            <div class="acc-header">
                <span>Thông tin về định hướng chiến lược và kế hoạch kinh doanh</span>
                <img class="acc-icon" src="/Data/FR/plus-circle.png?v=1" alt="open">
            </div>
            <ul class="acc-content">
                <li>Các nghiên cứu, phân tích và báo cáo đánh giá về ngành nghề, lĩnh vực kinh doanh chính mà doanh nghiệp hoạt động</li>
                <li>Chiến lược phát triển công ty và kế hoạch kinh doanh</li>
            </ul>
        </div>

        <div class="acc-item">
            <div class="acc-header">
                <span>Thông tin về tình hình tài chính của doanh nghiệp</span>
                <img class="acc-icon" src="/Data/FR/plus-circle.png?v=1" alt="open">
            </div>
            <ul class="acc-content">
                <li>Báo cáo tài chính kiểm toán</li>
                <li>Mô hình dự phóng tài chính</li>
                <li>Các chính sách về quản trị tài chính và báo cáo quản trị</li>
                <li>Các khoản nợ và lịch trả nợ</li>
            </ul>
        </div>

        <div class="acc-item">
            <div class="acc-header">
                <span>Thông tin khác</span>
                <img class="acc-icon" src="/Data/FR/plus-circle.png?v=1" alt="open">
            </div>
            <ul class="acc-content">
                <li>Hồ sơ pháp lý các dự án quan trọng</li>
                <li>Các hợp đồng, cam kết quan trọng</li>
            </ul>
        </div>
    </div>
    <script>
        document.querySelectorAll(''.acc-header'').forEach(header => {
            header.addEventListener(''click'', () => {
                const item = header.parentElement;
                const isOpen = item.classList.contains("open");

                // Đóng tất cả mục khác (nếu muốn accordion dạng chỉ mở 1)
                // document.querySelectorAll(".acc-item").forEach(i => i.classList.remove("open"));

                // Toggle chính nó
                if (!isOpen) {
                    item.classList.add("open");
                } else {
                    item.classList.remove("open");
                }
            });
        });
    </script>
</section>', 1, N'vi', 0, 0, N'FRProcessCacYeuCau', NULL, 1);
