INSERT INTO [dbo].[StaticInformation] ([Id], [Name], [Content], [Status], [Language], [Delete], [ParentId], [Code], [Data], [PortalId]) VALUES (3001102, N'Scorescale - Tổng quan', N' <section id="FiinMethod" class="mb-5">
     <style>
         .narbarmodel {
             padding: 50px 0;
             display: flex;
             justify-content: space-around;
             align-items: center;
         }

