            </div>

        </div>

        <div class="lost-nav">
            <button class="nav-btn prev-btn"><i class="fa fa-arrow-left"></i></button>
            <button class="nav-btn next-btn"><i class="fa fa-arrow-right"></i></button>
        </div>

        <div class="about-wrap pt-4">
            <div class="join-box">
                <p>
                    Tham khảo chi tiết: Chính sách Nhận diện và Định nghĩa về Mất Khả Năng Thanh Toán của
                    FiinRatings <a href="https://fiingroup.vn/upload/docs/FiinRatings-Definition-of-Default-VIE-Publicversion.pdf" target="_blank" style="color:#0066CC; border-bottom: 1px solid; font-weight: 500;">TẠI
                        ĐÂY</a>
                </p>


            </div>
        </div>
    </div>
</section>
<script>
(function () {
    const cards = document.querySelectorAll(".lost-card");
    const prevBtn = document.querySelector(".lost-nav .prev-btn");
    const nextBtn = document.querySelector(".lost-nav .next-btn");

    if (!cards.length) return;

    let currentIndex = 0;

    function getPageSize() {
        return window.innerWidth <= 576 ? 1 : 4;
    }

    function render() {
        const pageSize = getPageSize();

        cards.forEach((card, index) => {
            card.style.display =
                index >= currentIndex && index < currentIndex + pageSize
                    ? "block"
                    : "none";
        });

        prevBtn.disabled = currentIndex === 0;
        nextBtn.disabled = currentIndex + pageSize >= cards.length;
    }

    nextBtn.addEventListener("click", () => {
        const pageSize = getPageSize();
        if (currentIndex + pageSize < cards.length) {
            currentIndex += pageSize;
            render();
        }
    });

    prevBtn.addEventListener("click", () => {
        const pageSize = getPageSize();
        if (currentIndex > 0) {
            currentIndex -= pageSize;
            render();
        }
    });

    window.addEventListener("resize", () => {
        currentIndex = 0; // reset khi đổi màn hình
        render();
    });

    // Init
    render();
})();
</script>
', 1, N'vi', 0, 0, N'FRScorescaleEvent', NULL, 1);
