INSERT INTO [dbo].[StaticInformation] ([Id], [Name], [Content], [Status], [Language], [Delete], [ParentId], [Code], [Data], [PortalId]) VALUES (3001110, N'Services - FiinRatings thấu hiểu khách hàng', N'<section id="FiinTrust" class="mb-3">
            <style>
                .narbartrust {
                    padding: 50px 0;
                    display: flex;
                    justify-content: space-around;
                    align-items: center;
                }

                .narbartrust a {
                    color: #093461;
                    text-decoration: none;
                    font-size: 18px;
                    padding: 8px 10px;
                    display: flex;
                    justify-content: center;
                    min-width: 20%;
                    transition: color 0.3s, border-bottom 0.3s;
                    cursor: pointer;
                    border-bottom: 3px solid transparent;
                }

                .narbartrust a.active,
                .narbartrust a:hover {
                    color: #0066CC;
                    border-bottom: 3px solid #093461;
                }

                .info-fiinrate p {
                    color: #093461;
                }

                /* ===== Các box xếp hạng ===== */
                .method-grid {
                    display: grid;
                    grid-template-columns: repeat(auto-fit, minmax(350px, 1fr));
                    gap: 50px;
                    margin-top: 60px;
                }

                .bg-method1 {
                    background: url(''/Data/FR/method_detail1.jpg'') no-repeat center center;
                    background-size: cover;
                    border-radius: 12px;
                    position: relative;
                }

                .bg-method2 {
                    background: url(''/Data/FR/method_detail2.jpg'') no-repeat center center;
                    background-size: cover;
                    border-radius: 12px;
                    position: relative;
                }

                .method-box {
                    position: relative;
                    z-index: 2;
                    height: 260px;
                    display: flex;
                    flex-direction: column;
                    justify-content: flex-end;
                    padding: 0px 20px;
                    color: #fff;
                    border: none;
                    box-shadow: 0 4px 10px rgba(0, 76, 152, 0.05);
                }

                .bg-method1,
                .bg-method2 {
                    position: relative;
                    background-size: cover;
                    background-position: center;
                    border-radius: 12px;
                    overflow: hidden;
                }

                /* Overlay sáng hơn */
                .bg-method1::before,
                .bg-method2::before {
                    content: "";
                    position: absolute;
                    inset: 0;
                    background: rgba(0, 0, 0, 0.25);
                    /* từ 0.55 → 0.25 */
                    z-index: 1;
                }

                /* Nội dung nổi lên trên overlay */
                .method-box {
                    position: relative;
                    z-index: 2;
                }

                .method-box h2 {
                    color: #fff;
                    font-size: 28px;
                    font-weight: 700;
                    z-index: 2;
                }
                .method-box:hover {
                    transform: translateY(-5px);
                }


                .method-box .method-title {
                    font-size: 24px;
                    margin-top: 15%;
                }
            </style>
            <div class="container">
                <div class="whylastest pt-5">
                    <h2 class="price-title mb-4 text-center">FiinRatings <span style="color: #0066CC;">hỗ trợ khách hàng</span></h2>
                    <div class="row row2 pt-5">
                        <div class="col-12 col-sm-6 col-lg-4 mb-5">
                          	<div class="why-header"><div class="icon-box"><img src="/Data/FR/rating1.png" alt="why" loading="lazy"></div><h2 class="why-title w700">Phân tích độc lập<br>và chuyên sâu</h2></div>
                            <img src="/Data/Icon/icon-line.svg" alt="line">
                            <p class="why-desc">Cung cấp phân tích khách quan và chuyên sâu về các doanh nghiệp trong danh mục đầu tư, giúp nhà đầu tư đánh giá rủi ro và khả năng thực hiện nghĩa vụ tài chính.</p>
                        </div>
                        <div class="col-12 col-sm-6 col-lg-4 mb-5 pr-2">
                          	<div class="why-header"><div class="icon-box"><img src="/Data/FR/rating2.png" alt="why" loading="lazy"></div><h2 class="why-title w700">Đánh giá và so sánh<br>cơ hội đầu tư</h2></div>
                            <img src="/Data/Icon/icon-line.svg" alt="line">
                            <p class="why-desc">Hỗ trợ tìm kiếm, đánh giá và so sánh các cơ hội đầu tư, giúp nhà đầu tư lựa chọn phương án phù hợp với khẩu vị rủi ro và mục tiêu đầu tư.</p>
                        </div>
                        <div class="col-12 col-sm-6 col-lg-4 mb-5">
                          	<div class="why-header"><div class="icon-box"><img src="/Data/FR/rating3.png" alt="why" loading="lazy"></div><h2 class="why-title w700">Cơ sở cho định giá<br>và điều khoản tín dụng</h2></div>
                            <img src="/Data/Icon/icon-line.svg" alt="line">
                            <p class="why-desc">Phân tích và xếp hạng tín nhiệm của FiinRatings là cơ sở tham chiếu đáng tin cậy cho việc thiết lập điều khoản tín dụng, định giá trái phiếu và hỗ trợ giao dịch công cụ nợ.</p>
                        </div>
                      	<div class="col-12 col-sm-6 col-lg-4 mb-5">
                          	<div class="why-header"><div class="icon-box"><img src="/Data/FR/rating4.png" alt="why" loading="lazy"></div><h2 class="why-title w700">Quản lý và giám sát<br>danh mục đầu tư</h2></div>
                            <img src="/Data/Icon/icon-line.svg" alt="line">
                            <p class="why-desc">Hỗ trợ theo dõi và giám sát rủi ro tín dụng danh mục thông qua các báo cáo cập nhật về doanh nghiệp, công cụ nợ, ngành và thị trường.</p>
                        </div>
                        <div class="col-12 col-sm-6 col-lg-4 mb-5 pr-2">
                          	<div class="why-header"><div class="icon-box"><img src="/Data/FR/rating5.png" alt="why" loading="lazy"></div><h2 class="why-title w700">Hiểu sâu ngành<br>và xu hướng thị trường</h2></div>
                            <img src="/Data/Icon/icon-line.svg" alt="line">
                            <p class="why-desc">Cung cấp phân tích về quy mô, cấu trúc ngành, triển vọng tín dụng và xu hướng mới nổi, giúp nhà đầu tư nhận diện sớm rủi ro và cơ hội theo lĩnh vực.</p>
                        </div>
                        <div class="col-12 col-sm-6 col-lg-4 mb-5">
                          	<div class="why-header"><div class="icon-box"><img src="/Data/Banner/product_why5.png" alt="why" loading="lazy"></div><h2 class="why-title w700">Tối ưu chi phí<br>và nguồn lực phân tích</h2></div>
                            <img src="/Data/Icon/icon-line.svg" alt="line">
                            <p class="why-desc">Dựa trên cơ sở dữ liệu phong phú, các mô hình tín dụng chuyên sâu và đội ngũ chuyên gia am hiểu thị trường, FiinRatings giúp nhà đầu tư tối ưu chi phí và nguồn lực phân tích.</p>
                        </div>
                      </div>
                </div>
            </div>
</section>', 1, N'vi', 0, 0, N'FRServicesFiinRatings', NULL, 1);
