stify-content:center;border:1px solid #0066cf!important;border-radius:26px;overflow:hidden;font-size:16px}.tab.active{background:#0066cf!important}.testimonial-media .img{width:100%!important;height:420px}.testimonial-card{padding:0!important}.testimonial-card .align-items-stretch{background:#034ea2}.testimonial-card .testimonial-copy{padding:43px}.testimonial-card .testimonial-copy .quote{font-size:20px;color:#fff!important;height:auto}.testimonial-card .testimonial-copy .name{color:#fff!important}.owl-prev{margin-left:4px!important}.owl-theme .owl-nav [class*=owl-]{font-size:22px}.owl-next,.owl-prev{border:none!important}
