</section>', 1, N'vi', 0, 0, N'FRFinanceBanner', NULL, 1);
INSERT INTO [dbo].[StaticInformation] ([Id], [Name], [Content], [Status], [Language], [Delete], [ParentId], [Code], [Data], [PortalId]) VALUES (3001114, N'Finance - Các con số nổi bật', N'<section id="OutStand" class="py-5">
