INSERT INTO [dbo].[StaticInformation] ([Id], [Name], [Content], [Status], [Language], [Delete], [ParentId], [Code], [Data], [PortalId]) VALUES (3001115, N'Finance - FiinRatings thấu hiểu khách hàng', N'<section id="FiinTrust">
            <style>
                .narbartrust {
                    padding: 50px 0;
                    display: flex;
                    justify-content: space-around;
                    align-items: center;
                }

                .narbartrust a {
                    color: #093461;
                    text-decoration: none;
                    font-size: 18px;
                    padding: 8px 10px;
                    display: flex;
                    justify-content: center;
                    min-width: 20%;
                    transition: color 0.3s, border-bottom 0.3s;
                    cursor: pointer;
                    border-bottom: 3px solid transparent;
                }

                .narbartrust a.active,
                .narbartrust a:hover {
                    color: #0066CC;
                    border-bottom: 3px solid #093461;
                }

                .info-fiinrate p {
                    color: #093461;
                }

                /* ===== Các box xếp hạng ===== */
                .method-grid {
                    display: grid;
                    grid-template-columns: repeat(auto-fit, minmax(350px, 1fr));
                    gap: 50px;
                    margin-top: 60px;
                }

                .bg-method1 {
                    background-size: cover;
                    border-radius: 12px;
                    position: relative;
                }

                .bg-method2 {
                    background-size: cover;
                    border-radius: 12px;
                    position: relative;
                }

                .method-box {
                    position: relative;
                    z-index: 2;
                    height: 260px;
                    display: flex;
                    flex-direction: column;
                    justify-content: flex-end;
                    padding: 0px 20px;
                    color: #fff;
                    border: none;
                    box-shadow: 0 4px 10px rgba(0, 76, 152, 0.05);
                }

                .bg-method1,
                .bg-method2 {
                    position: relative;
                    background-size: cover;
                    background-position: center;
                    border-radius: 12px;
                    overflow: hidden;
                }

                /* Overlay sáng hơn */
                .bg-method1::before,
                .bg-method2::before {
                    content: "";
                    position: absolute;
                    inset: 0;
                    background: rgba(0, 0, 0, 0.25);
                    /* từ 0.55 → 0.25 */
                    z-index: 1;
                }

                /* Nội dung nổi lên trên overlay */
                .method-box {
                    position: relative;
                    z-index: 2;
                }

                .method-box h2 {
                    color: #fff;
                    font-size: 28px;
                    font-weight: 700;
                    z-index: 2;
                }
                .method-box:hover {
                    transform: translateY(-5px);
                }


                .method-box .method-title {
                    font-size: 24px;
                    margin-top: 15%;
                }
              .why h3{
              		font-weight: 700;
               	 	font-size: 32px;
                	color: #093461;
              }
            </style>
            <div class="container">
                <div class="whylastest py-5">
                    <h2 class="price-title text-center" style=''margin-bottom:0px!important;''>FiinRatings <span style="color: #0066CC;">hỗ trợ khách hàng</span></h2>
                    <div class="row row2 pt-4">
                      	<h3 class="text-center pb-5" style="color: #0066CC;">Tổ chức phát hành</h3>
                        <div class="col-sm-6 mb-2">
                          	<div class="why-header"><div class="icon-box"><img src="/Data/FR/fi1.png" alt="why" loading="lazy"></div><h2 class="why-title w700">Mở rộng khả năng<br>tiếp cận nguồn vốn</h2></div>
                            <img src="/Data/Icon/icon-line.svg" alt="line">
                            <p class="why-desc">Hỗ trợ doanh nghiệp tiếp cận hiệu quả hơn các nhà đầu tư quốc tế và trong nước có định hướng liên quan đến Môi trường, Xã hội và Quản trị (ESG).</p>
                        </div>
                        
                        <div class="col-sm-6 mb-2">
                          	<div class="why-header"><div class="icon-box"><img src="/Data/FR/fi3.png" alt="why" loading="lazy"></div><h2 class="why-title w700">Củng cố uy tín<br>và tính minh bạch</h2></div>
                            <img src="/Data/Icon/icon-line.svg" alt="line">
                            <p class="why-desc">Hỗ trợ doanh nghiệp khẳng định cam kết phát triển bền vững thông qua các đánh giá độc lập, được xây dựng trên những nguyên tắc và chuẩn mực quốc tế được áp dụng rộng rãi trên toàn cầu.</p>
                        </div>
                      
                      <div class="row row2 pt-4">
                        <h3 class="text-center pb-5" style="color: #0066CC;">Nhà đầu tư</h3>
                        <div class="col-sm-4 mb-2">
                          	<div class="why-header"><div class="icon-box"><img src="/Data/FR/fi4.png" alt="why" loading="lazy"></div><h2 class="why-title w700">Nâng cao<br>hiệu quả thẩm định</h2></div>
                            <img src="/Data/Icon/icon-line.svg" alt="line">
                            <p class="why-desc">Cung cấp các báo cáo đánh giá toàn diện, giúp nhà đầu tư tối ưu nguồn lực và rút ngắn thời gian trong quá trình ra quyết định.</p>
                        </div>
                        <div class="col-sm-4 mb-2 pr-2">
                          	<div class="why-header"><div class="icon-box"><img src="/Data/FR/fi5.png" alt="why" loading="lazy"></div><h2 class="why-title w700">Tăng khả năng<br>so sánh và lựa chọn</h2></div>
                            <img src="/Data/Icon/icon-line.svg" alt="line">
                            <p class="why-desc">Tạo cơ sở để so sánh khách quan giữa các công cụ tài chính bền vững trong cùng lĩnh vực hoặc thị trường.</p>
                        </div>
                        
                        <div class="col-sm-4 mb-2 pr-2">
                          	<div class="why-header"><div class="icon-box"><img src="/Data/FR/fi2.png" alt="why" loading="lazy"></div><h2 class="why-title w700">Đầu tư tạo giá trị bền vững</h2></div>
                            <img src="/Data/Icon/icon-line.svg" alt="line">
                            <p class="why-desc">Đóng góp vào nền kinh tế carbon thấp thông qua các khoản đầu tư trách nhiệm có thanh khoản cao, kết hợp hiệu quả giữa lợi nhuận tài chính và giảm thiểu tác động của biến đổi khí hậu.</p>
                        </div>
                        
                    </div>
                </div>
            </div>
  </div>   
</section>

					', 1, N'vi', 0, 0, N'FRFinanceFiinRatings ', NULL, 1);
INSERT INTO [dbo].[StaticInformation] ([Id], [Name], [Content], [Status], [Language], [Delete], [ParentId], [Code], [Data], [PortalId]) VALUES (3001116, N'Finance - Phương pháp luận', N'<style>
    .timeline {
        position: relative;
    }

    /* Line ngang nối 01-02-03 */
    .timeline-horizontal {
        position: absolute;
        top: 42px;
        left: calc(16.666% + 28px);
        width: calc(66.666% - 56px);
        height: 1px;
        background: #0d6efd;
        z-index: 1;
    }

    /* Item */
    .timeline-item {
        position: relative;
        z-index: 2;
    }

    /* Vòng chấm */
    .circle-wrap {
        width: 72px;
        height: 72px;
        margin: 0 auto;
        border-radius: 50%;
        border: 2px dotted #7fb0ff;
        display: flex;
        align-items: center;
        justify-content: center;
        background: #f7fbff;
    }

    /* Circle chính */
    .timeline-circle {
        width: 56px;
        height: 56px;
        border-radius: 50%;
        background: linear-gradient(119.22deg, #0018A8 19.92%, #166BF2 56.45%, #3B7EEE 99.27%);
        color: #fff;
        font-weight: 600;
        display: flex;
        align-items: center;
        justify-content: center;
    }

    /* Line dọc từ circle xuống box */
    .timeline-vertical {
        width: 1px;
        height: 28px;
        background: #0d6efd;
        margin: 0 auto;
    }

    /* Box */
    .timeline-box {
        background: #ffffff;
        border: 1.5px solid #0066CC;
        border-radius: 12px;
        padding: 22px;
        font-weight: 500;
        height: 180px;
        line-height: 1.7;
        box-shadow: 0 6px 14px rgba(0, 0, 0, 0.05);
      text-align: justify;
    }
    .FiinPP p{
        font-weight: 500;
    }
</style>
<section id="FiinPP">
    <div class="container py-4">
        <div class="row mb-5">
            <h2 class="price-title mb-4" style="text-align: center;">Phương pháp luận</h2>
            <p>
                FiinRatings xây dựng phương pháp luận trên cơ sở kết hợp các tiêu chuẩn quốc tế và các đặc trưng của thị trường nội địa nhằm cung cấp các ý kiến đánh giá độc lập đáng tin cậy, minh bạch và phù hợp với nhu cầu phát triển bền vững.
            </p>
        </div>
        <div class="timeline row position-relative">
            <div class="timeline-horizontal"></div>

            <!-- Step 1 -->
            <div class="col-md-4 text-center timeline-item">
                <div class="circle-wrap">
                    <div class="timeline-circle">01</div>
                </div>
                <div class="timeline-vertical"></div>
                <div class="timeline-box">
                    Xem xét các yếu tố bền vững mang tính đặc thù ngành với các tiêu chí
                    và chuẩn đối sánh bền vững đặc thù, dựa trên thông lệ tốt nhất và
                    xu hướng ngành, tuỳ chỉnh về các rủi ro và cơ hội ESG trọng yếu.
                </div>
            </div>

            <!-- Step 2 -->
            <div class="col-md-4 text-center timeline-item">
                <div class="circle-wrap">
                    <div class="timeline-circle">02</div>
                </div>
                <div class="timeline-vertical"></div>
                <div class="timeline-box">
                    Thực hành báo cáo và công bố thông tin minh bạch, cung cấp những
                    hiểu biết rõ ràng, toàn diện và mang tính hành động làm cơ sở ra
                    quyết định cho nhà đầu tư.
                </div>
            </div>

            <!-- Step 3 -->
            <div class="col-md-4 text-center timeline-item">
                <div class="circle-wrap">
                    <div class="timeline-circle">03</div>
                </div>
                <div class="timeline-vertical"></div>
                <div class="timeline-box">
                    Kịp thời thích ứng với các thay đổi thông qua việc cập nhật phương
                    pháp luận dựa trên các tiêu chuẩn và nguyên tắc mới nhất, phản ánh
                    thị trường và nghiên cứu chuyên sâu để tối ưu hóa quy trình đánh giá.
                </div>
            </div>

        </div>
        <div class="view-now-wrapper my-5">
            <a href="https://fiinratings.vn/Upload/[VI]_FiinRatings_SPO_Methodology_15092024.pdf" target="_blank" class="btn btn-primary btn-join">
                Xem chi tiết
            </a>
        </div>
    </div>
</section>
<div>
 <div class="container">
    <div class="why mb-4">
        <h2 class="price-title text-center">Kết quả xác nhận</h2>
	</div>
</div>	
</div>', 1, N'vi', 0, 0, N'FRFinancePhuongPhap', NULL, 1);
INSERT INTO [dbo].[StaticInformation] ([Id], [Name], [Content], [Status], [Language], [Delete], [ParentId], [Code], [Data], [PortalId]) VALUES (3001117, N'Finance - Tổng quan', N'<style>
