                    border: none;
                    box-shadow: 0 4px 10px rgba(0, 76, 152, 0.05);
                }

                .bg-method1,
                .bg-method2,.bg-method3,.bg-method4 {
                    position: relative;
                    background-size: cover;
                    background-position: center;
                    border-radius: 12px;
                    overflow: hidden;
                }

                /* Overlay sáng hơn */
                .bg-method1::before,
                .bg-method2::before, .bg-method3::before,
                .bg-method4::before {
                    content: "";
                    position: absolute;
                    inset: 0;
                  	background:none !important;
                    /* background: rgba(0, 0, 0, 0.25); */
                    /* từ 0.55 → 0.25 */
                    z-index: 1;
                }

                /* Nội dung nổi lên trên overlay */
                .method-box {
                    position: relative;
                    z-index: 2;
                }

                .method-box h2 {
                    color: #fff;
