INSERT INTO [dbo].[StaticInformation] ([Id], [Name], [Content], [Status], [Language], [Delete], [ParentId], [Code], [Data], [PortalId]) VALUES (3001122, N'Home - Slider Banner', N'<section id="SliderBanner">
    <style>
        #SliderBanner img{max-height:100%;}.event-box{position:absolute;bottom:30px;left:30px;width:26%;padding:30px;border-radius:12px;background:url(''Data/FR/bg-joinnew.jpg'') no-repeat center/cover;background-blend-mode:overlay;box-shadow:0 4px 15px rgba(0, 0, 0, 0.15);border:1px solid rgba(255, 255, 255, 0.6);animation:fadeInUp 0.8s ease;transition:opacity 0.3s ease,transform 0.3s ease;z-index:10;}@keyframes fadeInUp{from{opacity:0;transform:translateY(15px);}to{opacity:1;transform:translateY(0);}}.event-box h4{font-size:18px;color:#1D2939;font-weight:600;margin-bottom:5px;}.event-box p{font-size:28px;color:#034EA2;font-weight:500;margin-bottom:12px;}.event-btn{display:inline-block;background:linear-gradient(135deg, #034EA2, #53DFFF);color:white;font-size:14px;font-weight:500;padding:6px 18px;border-radius:6px;text-decoration:none;transition:all 0.3s ease;}.event-btn:hover{transform:translateY(-2px);box-shadow:0 4px 8px rgba(3, 78, 162, 0.3);}.event-close{position:absolute;top:8px;right:8px;background:transparent;border:none;color:#004b8d;font-size:16px;cursor:pointer;transition:color 0.2s ease,transform 0.2s ease;}.event-close:hover{color:#0078d4;transform:rotate(90deg);}.event-box.hidden{opacity:0;transform:translateY(10px);pointer-events:none;}@media(max-width: 992px){.event-box{width:60%;padding:20px;bottom:20px;left:20px;}.event-box p{font-size:22px;}}@media(max-width: 576px){.event-box{display:none;}}
    </style>

    <div id="carouselExampleCaptions" class="carousel slide carousel-fade" data-bs-touch="true">
        <div class="carousel-inner">
            <div class="carousel-item active" data-bs-interval="3000">
              	<h1 class="w700 d-none">FiinRatings</h1>
                <img src="/Data/2025/FR/Banner-Homepage.jpg" fetchpriority="high" alt="FiinRatings" class="d-block w-100" alt="Banner">
                <!--<div class="event-box" id="eventBox">
                    <button class="event-close" id="closeEventBox">
                        <i class="fa fa-times"></i>
                    </button>
                    <h4>Event of the year</h4>
                    <p>Light your way</p>
                    <a href="#" class="event-btn">Join now!</a>
                </div>-->
            </div>
        </div>
    </div>
    <script>
        document.getElementById("closeEventBox")?.addEventListener("click", function () {
            const box = document.getElementById("eventBox");
            box.classList.add("hidden");
            setTimeout(() => {
                box.style.display = "none";
            }, 300); // khớp với transition
        });
    </script>
</section>', 1, N'en', 0, 0, N'FRHomeSliderBanner', NULL, 1);
