INSERT INTO [dbo].[StaticInformation] ([Id], [Name], [Content], [Status], [Language], [Delete], [ParentId], [Code], [Data], [PortalId]) VALUES (3001125, N'Home - FiinRatings', N'<section id="WhyLastest" class="mb-5">
   <div class="whylastest mt-5">
      <div class="container">
         <div class="why pb-4">
            <h2 class="price-title mb-5">Why <span style="color: #0066CC;">FiinRatings</span>?</h2>
            <div class="row row2">
               <div class="col-sm-4 mb-5">
                  <div class="why-header">
                     <div class="icon-box"><img src="/Data/Banner/why1.png" alt="why" loading="lazy"></div>
                     <h2 class="why-title w700">Comprehensive <br>analytical ecosystem</h2>
                  </div>
                  <img src="/Data/Icon/icon-line.svg" alt="line">
                  <p class="why-desc" style="text-align: left;"><span style="color: #0066CC;">FiinRatings’ credit ratings and risk analyses </span>help issuers strengthen market confidence while providing investors with comprehensive and objective insights. </p>
               </div>
               <div class="col-sm-4 mb-5 pr-2">
                  <div class="why-header">
                     <div class="icon-box"><img src="/Data/Banner/why2.png" alt="why" loading="lazy"></div>
                     <h2 class="why-title w700">Powerful <br> in-depth data</h2>
                  </div>
                  <img src="/Data/Icon/icon-line.svg" alt="line">
                  <p class="why-desc" style="text-align: left;">Leveraging <span style="color: #0066CC;">FiinGroup’s large-scale database and standardized methodologies</span>, FiinRatings delivers credible assessments to support more informed decisions by issuers and investors.</p>
               </div>
               <div class="col-sm-4 mb-5">
                  <div class="why-header">
                     <div class="icon-box"><img src="/Data/Banner/why2.png" alt="why" loading="lazy"></div>
                     <h2 class="why-title w700">Expert team with <br> deep local market insights</h2>
                  </div>
                  <img src="/Data/Icon/icon-line.svg" alt="line">
                  <p class="why-desc" style="text-align: left;">An analytical team combines extensive hands-on experience,<span style="color: #0066CC;">with deep understanding of the Vietnamese market</span>, ensuring accurate and reliable credit assessments. </p>
               </div>
               <div class="col-sm-4 mb-5">
                  <div class="why-header">
                     <div class="icon-box"><img src="/Data/Banner/why4.png" alt="why" loading="lazy"></div>
                     <h2 class="why-title w700">Globally aligned <br> methodologies</h2>
                  </div>
                  <img src="/Data/Icon/icon-line.svg" alt="line">
                  <p class="why-desc" style="text-align: left;">Built on <span style="color: #0066CC;">methodologies transferred from S&P Global Ratings, </span>FiinRatings ensures transparency and consistency, enabling issuers to confidently align with global best practices.</p>
               </div>
               <div class="col-sm-4 mb-5">
			    <div class="why-header">
                  <div class="icon-box"><img src="/Data/Banner/why5.png" alt="why"/></div>
                  <h2 class="why-title w700">Pioneering international-standard green capital</h2>
  				</div>
                  <img src="/Data/Icon/icon-line.svg" alt="line">
                  <p class="why-desc" style="text-align: left;">As <span style="color: #0066CC;">the only CBI-authorized bond labeling verifier in Vietnam</span>, FiinRatings helps issuers reinforce market trust and expand access to sustainable capital..</p>
               </div>
               <div class="col-sm-4 mb-5">
                  <div class="why-header">
                     <div class="icon-box"><img src="/Data/Banner/why3.png" alt="why" loading="lazy"></div>
                     <h2 class="why-title w700">Extensive <br>investor network</h2>
                  </div>
                  <img src="/Data/Icon/icon-line.svg" alt="line">
                  <p class="why-desc" style="text-align: left;">With extensive connections to <span style="color: #0066CC;">domestic and international funds, insurers, banks, and institutional investors</span>, FiinRatings helps issuers effectively diversify funding sources.</p>
               </div>
            </div>
         </div>
         <div class="text-center mb-5"><button class="btn btn-primary btn-join" onclick="window.open(''https://fiinratings.vn/upload/FiinRatings_Issuer-Pay-Service-Brochure.pdf?v=05092025'', ''_blank'')">View Brochure</button></div>
      </div>
   </div>
</section>', 1, N'en', 0, 0, N'FRHomeFiinRatings', NULL, 1);
INSERT INTO [dbo].[StaticInformation] ([Id], [Name], [Content], [Status], [Language], [Delete], [ParentId], [Code], [Data], [PortalId]) VALUES (3001126, N'Home - What We Do', N' <style>
