INSERT INTO [dbo].[StaticInformation] ([Id], [Name], [Content], [Status], [Language], [Delete], [ParentId], [Code], [Data], [PortalId]) VALUES (3001129, N'AboutUs - StoryFiin', N'		<style>
		.narbarstory {
			padding: 50px 0;
			display: flex;
			justify-content: space-around;
			align-items: center;
		}

			.narbarstory a {
				color: #093461;
				text-decoration: none;
				font-size: 18px;
				padding: 8px 0;
				display: flex;
				justify-content: center;
				min-width: 20%;
				transition: color 0.3s, border-bottom 0.3s;
				cursor: pointer;
				border-bottom: 3px solid transparent;
			}

				.narbarstory a.active,
				.narbarstory a:hover {
					color: #0066CC;
					border-bottom: 3px solid #093461;
				}

		.about-main-box {
			padding: 15px 0;
			border-radius: 12px;
			margin-bottom: 40px;
		}


			.about-main-box::before {
				content: "";
				position: absolute;
				inset: 0;
				border-radius: inherit;
				z-index: -1;
			}

		.about-main-box {
			position: relative;
			z-index: 1;
		}

			.about-main-box p {
				margin-bottom: 0;
				line-height: 1.6;
				color: #093461;
				font-size: 15px;
				padding-top: 20px;
				text-align: justify;
			}

		.about-wrap {
			position: relative;
			z-index: 1;
		}


		.about-grid {
			display: grid;
			grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
			gap: 25px;
		}

		.about-box {
			background: #ffffff;
			padding: 25px;
			border-radius: 12px;
			border: 1px solid #d5e4ff;
			box-shadow: 0 4px 12px rgba(0, 76, 152, 0.08);
			text-align: left;
			transition: transform 0.3s ease;
			border: 1px solid transparent;
			background-image: linear-gradient(#f5f9ff, #f2f7ff), linear-gradient(to right, #034EA2, #53DFFF);
			background-origin: border-box;
			background-clip: padding-box, border-box;
		}

			.about-box:hover {
				transform: translateY(-5px);
			}

			.about-box .why-title {
				font-size: 30px !important;
				height: 42px !important;
			}

			.about-box h3 {
				font-size: 20px;
				color: #064A9D;
				margin: 15px 0;
			}

			.about-box p {
				color: #093461;
				line-height: 1.6;
				text-align: justify;
			}

		.link {
			border-bottom: 1px solid;
			color: #2E90FA;
		}
	</style>
	<div class="narbarstory">
			<a href="#StoryFinn" class="active">Overview</a>
			<a href="#TimeLine">Milestones</a>
			<a href="#UserTeam">Leadership</a>
			<a href="#WordEnvironment">Work Environment</a>
		</div>
<section id="StoryFinn">

	<div class="container">
	
		<div class="why pb-4">
			<h2 class="price-title mb-3">Our <span style="color: #0066CC;"> Story </span></h2>
			<div class="about-wrap">
				<div class="about-main-box">
					<p>
						<span style="color: #0066CC;"><strong>FiinRatings - a strategic partner of S&P Global -</strong></span> is a credit rating agency licensed by the Vietnam Ministry of Finance and one of the pioneers in promoting transparency and sustainability in Vietnam’s capital markets. We provide <span style="color: #0066CC;"><strong>independent credit rating</strong></span> services for domestic corporates to support efficient and well-informed capital-raising activities. FiinRatings also offers <span style="color: #0066CC;"><strong>risk research, in-depth credit analysis</strong></span>, and <span style="color: #0066CC;"><strong>green bond verification</strong></span> in accordance with international standards such as ICMA and the Climate Bonds Initiative (CBI), thereby enabling investors to assess risks and make well-rounded investment decisions.
					</p>
					<p>
						FiinRatings is a member of <span style="color: #0066CC;"><strong> FiinGroup</strong></span> – the leading provider in Vietnam of financial data analytics, market research, and financial technology solutions. The data capabilities, technology platforms, and domain expertise of FiinGroup provide a strong foundation for FiinRatings to maintain robust analytical capacity, standardized rating methodologies, and an increasingly recognized reputation in the market.  
                    </p>
					
				</div>
			</div>
			

		</div>
	</div>
</section>
	<script>
$(function(){
  document.addEventListener(''DOMContentLoaded'', () => {
			const links = document.querySelectorAll(''.narbarstory a'');
			links.forEach(link => {
				link.addEventListener(''click'', (e) => {
					e.preventDefault();
					// Xóa class active
					links.forEach(l => l.classList.remove(''active''));
					link.classList.add(''active'');
					// Lấy ID mục tiêu
					const targetId = link.getAttribute(''href'')?.trim();
					// Nếu href null hoặc không phải id hợp lệ thì thoát
					if (!targetId || !targetId.startsWith("#")) {
						return;
					}
					const targetEl = document.querySelector(targetId);
					if (targetEl) {
						targetEl.scrollIntoView({
							behavior: "smooth",
							block: "start"
						});
					}
				});
			});
		});
});
	</script>', 1, N'en', 0, 0, N'FRAboutUsStoryFiin', NULL, 1);
INSERT INTO [dbo].[StaticInformation] ([Id], [Name], [Content], [Status], [Language], [Delete], [ParentId], [Code], [Data], [PortalId]) VALUES (3001130, N'AboutUs - TimeLine', N'<section id="TimeLine" class="timeline-section">
	<style>
		.nav-btn,.year-tab{cursor:pointer;transition:.2s}#TimeLine{background:url(/Data/FR/about_hisbanner.jpg) top/cover no-repeat}.timeline-title{text-align:center;font-size:32px;font-weight:700;margin-bottom:32px;color:#fff;padding-top:60px}.timeline-tabs{display:flex;justify-content:center;gap:32px;margin-bottom:32px;flex-wrap:nowrap;overflow-x:auto;padding-bottom:10px}.year-tab{padding:10px 28px;border-radius:30px;border:none;font-size:18px;font-weight:600;background:rgba(255,255,255,.15);color:#fff;white-space:nowrap}.nav-btn,.year-tab.active{background:#fff;color:#06c}.year-tab.active{box-shadow:0 4px 15px rgba(255,255,255,.3)}.timeline-slider{background:#fff;border-radius:16px;padding:50px;display:flex;align-items:center;position:relative;gap:20px}.timeline-content{display:grid;grid-template-columns:1fr 1fr;gap:24px}.timeline-text{display:flex;flex-direction:column;justify-content:space-between}.timeline-text h3{font-size:24px;font-weight:600;margin:0 0 -25px;color:#06c}.gach{border-bottom:1px solid #093461;width:60px;margin:0 0 12px}.timeline-text p{font-size:28px;font-weight:600;line-height:1.5;color:#093461;text-align:justify}.timeline-img{object-fit:cover;border-radius:12px}.timeline-text .img-his{margin-top:0}.nav-btn{width:46px;height:46px;border-radius:50%;border:2px solid #fff;font-size:20px;box-shadow:0 4px 12px rgba(0,0,0,.12),0 0 8px rgba(255,255,255,.6)}.nav-btn:hover{background:#1c98ef;color:#fff}.prev-btn{position:absolute;left:-25px}.next-btn{position:absolute;right:-25px}
	</style>
	<div class="container pb-5">
		<h2 class="timeline-title">Our Key Milestones</h2>
		<!-- TAB YEARS -->
		<div class="timeline-tabs" id="yearTabs">
			<div class="tab-spacer"></div> <!-- spacer -->
			<button class="year-tab active" data-index="0">2008</button>
			<button class="year-tab" data-index="1">2020</button>
			<button class="year-tab" data-index="2">2021</button>
			<button class="year-tab" data-index="3">2022</button>
			<button class="year-tab" data-index="4">2025</button>
		</div>

		<!-- SLIDER CONTENT -->
		<div class="timeline-slider">
			<button class="nav-btn prev-btn" id="prevBtn">
				<i class="fa fa-arrow-left"></i>
			</button>

			<div class="timeline-content" id="timelineContent">
				<!-- CONTENT WILL BE LOADED BY JS -->
			</div>

			<button class="nav-btn next-btn" id="nextBtn">
				<i class="fa fa-arrow-right"></i>
			</button>
		</div>
	</div>

	<script>
		const timelineData = [
			{
				year: "2008",
				title: "",
				text: `<span style="color: #0066CC;">FiinGroup (previously known as StoxPlus)</span> was founded as a stock market information provider.`,
				img: "/Data/FR/about_hisdetail.jpg"
			},
			{
				year: "2020",
				title: "",
				text: `Expanded and start operating as <span style="color: #0066CC;">a local licensed Credit Rating Agency</span>.`,
				img: "/Data/FR/about_hisdetail.jpg"
			},
			{
				year: "2021",
				title: "",
				text: `Received Technical Assistant from <span style="color: #d6002a;">S&P Global Ratings</span> and <span style="color: #0066CC;">Asian Development Bank (ADB)</span>.`,
				img: "/Data/FR/about_hisdetail.jpg"
			},
			{
				year: "2022",
				title: "",
				text: `Authorized by <span style="color: #0066CC;">CBI</span> to be an Approved Verifier for Green Bonds & Green Loans.<br>Corporate reorganization and renamed as <span style="color: #0066CC;">FiinRatings JSC</span>.`,
				img: "/Data/FR/about_hisdetail.jpg"
			},
			{
				year: "2025",
				title: "",
				text: `Formed a strategic partnership with <span style="color: #d6002a;">S&P Global</span>, which acquired a <span style="color: #d6002a;">43,4%</span> minority stake in FiinRatings on 25th February.`,
				img: "/Data/FR/about_hisdetail.jpg"
			}
		];

		let currentIndex = 0;

		const contentBox = document.getElementById("timelineContent");
		const yeartabs = document.querySelectorAll(".year-tab");

		function loadSlide(index) {
			currentIndex = index;
			// update tabs
			yeartabs.forEach(tab => tab.classList.remove("active"));
			yeartabs[index].classList.add("active");
			// load content
			const d = timelineData[index];
			contentBox.innerHTML = `
				<div class="timeline-text" style=''justify-content: normal;''>
					<div class="img-his mb-4"><img src="/Data/2025/FR/Logo-dong-tien.png" style=''height: 30px;''></div>
					<p>${d.text}</p>
				</div>
				<img src="${d.img}" alt=''logo-mini'' class="timeline-img">
			`;
		}

		// Tab click
		yeartabs.forEach(tab => {
			tab.addEventListener("click", () => {
				const idx = parseInt(tab.dataset.index);
				loadSlide(idx);
			});
		});
		// Prev / Next
		document.getElementById("prevBtn").onclick = () => {
			const next = (currentIndex - 1 + timelineData.length) % timelineData.length;
			loadSlide(next);
		};
		document.getElementById("nextBtn").onclick = () => {
			const next = (currentIndex + 1) % timelineData.length;
			loadSlide(next);
		};
		// Load first slide
		loadSlide(0);
	</script>
</section>', 1, N'en', 0, 0, N'FRAboutUsTimeLine', NULL, 1);
INSERT INTO [dbo].[StaticInformation] ([Id], [Name], [Content], [Status], [Language], [Delete], [ParentId], [Code], [Data], [PortalId]) VALUES (3001131, N'AboutUs - Teams', N'<section id="UserTeam" class="py-5">
    <style>
