INSERT INTO [dbo].[StaticInformation] ([Id], [Name], [Content], [Status], [Language], [Delete], [ParentId], [Code], [Data], [PortalId]) VALUES (3001133, N'Product - Xếp hạng Tín nhiệm', N'<section id="FiinTrust" class="mb-5">
            <style>
                .narbartrust {
                    padding: 50px 0;
                    display: flex;
                    justify-content: space-around;
                    align-items: center;
                }

                .narbartrust a {
                    color: #093461;
                    text-decoration: none;
                    font-size: 18px;
                    padding: 8px 10px;
                    display: flex;
                    justify-content: center;
                    min-width: 20%;
                    transition: color 0.3s, border-bottom 0.3s;
                    cursor: pointer;
                    border-bottom: 3px solid transparent;
                }

                .narbartrust a.active,
                .narbartrust a:hover {
                    color: #0066CC;
                    border-bottom: 3px solid #093461;
                }

                .info-fiinrate p {
                    color: #093461;
                }

                /* ===== Các box xếp hạng ===== */
                .method-grid {
                    display: grid;
                    grid-template-columns: repeat(auto-fit, minmax(350px, 1fr));
                    gap: 50px;
                    margin-top: 60px;
                }

                .bg-method1 {
                    background: url(''/Data/2025/FR/banner-metho/op2.png'') no-repeat center center;
                    background-size: cover;
                    border-radius: 12px;
                    position: relative;
                }

                .bg-method2 {
                    background: url(''/Data/2025/FR/banner-metho/op4.png'') no-repeat center center;
                    background-size: cover;
                    border-radius: 12px;
                    position: relative;
                }

                .method-box {
                    position: relative;
                    z-index: 2;
                    height: 260px;
                    display: flex;
                    flex-direction: column;
                    justify-content: flex-end;
                    padding: 0px 20px;
                    color: #fff;
                    border: none;
                    box-shadow: 0 4px 10px rgba(0, 76, 152, 0.05);
                }

                .bg-method1,
                .bg-method2 {
                    position: relative;
                    background-size: cover;
                    background-position: center;
                    border-radius: 12px;
                    overflow: hidden;
                }

                /* Overlay sáng hơn */
                .bg-method1::before,
                .bg-method2::before {
                    content: "";
                    position: absolute;
                    inset: 0;
                    /* background: rgba(0, 0, 0, 0.25); */
                    /* từ 0.55 → 0.25 */
                    z-index: 1;
                }

                /* Nội dung nổi lên trên overlay */
                .method-box {
                    position: relative;
                    z-index: 2;
                }

                .method-box h2 {
                    color: #fff;
                    font-size: 28px;
                    font-weight: 700;
                    z-index: 2;
                }
                .method-box:hover {
                    transform: translateY(-5px);
                }


                .method-box .method-title {
                    font-size: 24px;
                    margin-top: 15%;
                }
              	.method-grid p {
                  font-size: 14px;
                  font-weight: 400;
                  color: #093461;
				}
              	.bg-method1:hover, .bg-method2:hover {
                    background: linear-gradient(180deg, rgba(255, 255, 255, 0) 26.44%, #C3E4F6 100%), #FFFFFF;
                    border-radius: 10px;
                }
                    .bg-method1:hover h2, .bg-method2:hover h2 {
                        color: #093461;
                    }
                    .bg-method1:hover .method-none, .bg-method2:hover .method-none {
                        display: block;
                    }
                .method-none{display:none;}
            </style>
            <div class="container">
                <div class="narbartrust">
                  <a href="#FiinTrust" class="active">Overview</a>
                  <a href="#OutStand">Track Records</a>
                  <a href="#WhyLastest">Key Values</a>
                  <a href="#Customer">Our Clients</a>
                  <a href="#UserTeam">Professional Team</a>
                </div>
                <div class="why pb-4">
                    <h2 class="price-title mb-2 text-center">What is <span style="color: #0066CC;">Credit Rating</span>?</h2>
                    <div class="row row2 pt-5">
                        <div class="col-sm-4 mb-2">
<div class=''why-header''>
                            <img src="/Data/Banner/why1.png" alt="why" />
                            <div class="why-title">Opinion on credit risk</div>
</div>  
                            <img src="/Data/Icon/icon-line.svg" alt="line">
                            <p class="why-desc" style="text-align: left;">A credit rating represents an independent opinion on an issuer’s ability and willingness to meet its financial obligations in full and on time. Not a guarantee against default.
                            </p>
                        </div>
                        <div class="col-sm-4 mb-2 pr-2">
                          <div class=''why-header''>
                    <img src="/Data/Banner/why2.png" alt="why" />
                            <div class="why-title">Rating scale</div>
                                  </div>  
                            <img src="/Data/Icon/icon-line.svg" alt="line">
                            <p class="why-desc" style="text-align: left;">A multi-level rating scale from ‘AAA’ to ‘C’ reflecting different degrees of credit risk related to an issuer’s capacity to meet its debt obligations.
                        </div>
                        <div class="col-sm-4 mb-2">
                          <div class=''why-header''>
                    <img src="/Data/Banner/why3.png" alt="why" />
                            <div class="why-title">Rating modifiers
                              </div>  
                            </div>
                            <img src="/Data/Icon/icon-line.svg" alt="line">
                            <p class="why-desc" style="text-align: left;">Plus and minus modifiers provide greater differentiation within a rating category. A minus sign does not indicate weaker operations or repayment capacity.
                            </p>
                        </div>
                          </div>
                      <div class="row row2 pt-3">
                        <div class="col-sm-4 mb-2">
                          <div class=''why-header''>
                            <img src="/Data/Banner/product_why3.png" alt="why" />
                            <div class="why-title">Rating surveillance</div>
                            </div>  
                            <img src="/Data/Icon/icon-line.svg" alt="line">
                            <p class="why-desc" style="text-align: left;">Ongoing monitoring of ratings and outlooks, with reviews conducted at least every six months or following material credit events.
                            </p>
                        </div>
                        <div class="col-sm-4 mb-2 pr-2">
                          <div class=''why-header''>
                    <img src="/Data/Banner/product_why6.png" alt="why" />
                            <div class="why-title">Rating criteria framework</div>
                            </div>  
                            <img src="/Data/Icon/icon-line.svg" alt="line">
                            <p class="why-desc" style="text-align: left;">Ratings are based on multiple criteria categories, including industry and outlook, business risk, financial strength, governance, and relevant linkages.
                        </div>
                        <div class="col-sm-4 mb-2">
                          <div class=''why-header''>
                    <img src="/Data/Banner/solution_why.png" alt="why" />
                            <div class="why-title">Independence & objectivity</div>
                            </div>  
                            <img src="/Data/Icon/icon-line.svg" alt="line">
                            <p class="why-desc" style="text-align: left;">Rating activities adhere to principles of independence, ethical standards, conflict-of-interest controls, and quality assurance.
                            </p>
                        </div>

                        <div class="method-grid">
                          <!--- <a href="/vi/san-pham-va-dich-vu.html" title="Xếp hạng Tổ chức phát hành"> </a>!-->
                            <div class="method-box bg-method1">
                                <h2 class="method-title">Issuer credit rating</h2>
                              	<img class="method-none" src="/Data/Icon/icon-line.svg" height="2" width="156" alt="line">
                                <p class="pt-2 method-none">
                                    An assessment of a company''s overall creditworthiness. This opinion focuses on the issuer''s capacity and willingness to meet its financial commitments as they come due, and does not apply to any specific financial obligation.
                                </p>
                            </div>
                          

                          <!--- <a href="/vi/san-pham-va-dich-vu.html" title="Xếp hạng Công cụ nợ"> </a>!--->
                            <div class="method-box bg-method2">
                                <h2 class="method-title">Issue credit rating</h2>
                              	<img class="method-none" src="/Data/Icon/icon-line.svg" height="2" width="156" alt="line">
                                <p class="pt-2 method-none">
                                   An assessment of the creditworthiness of a particular financial obligation, or a particular financing program (including ratings for short-, medium- and long-term debt). This opinion reflects FiinRatings'' view of the issuer''s capacity and willingness to meet its financial commitments when the obligation becomes due.
                                </p>
                            </div>
                           

                        </div>

                    </div>
                </div>
            </div>
            <script>
                document.addEventListener(''DOMContentLoaded'', () => {
            const links = document.querySelectorAll(''.narbartrust a'');
		            links.forEach(link => {
			            link.addEventListener(''click'', (e) => {
				            e.preventDefault();
				            // Xóa class active
				            links.forEach(l => l.classList.remove(''active''));
				            link.classList.add(''active'');
				            // Lấy ID mục tiêu
				            const targetId = link.getAttribute(''href'')?.trim();
				            // Nếu href null hoặc không phải id hợp lệ thì thoát
				            if (!targetId || !targetId.startsWith("#")) {
					            return;
				            }
				            const targetEl = document.querySelector(targetId);
				            if (targetEl) {
					            targetEl.scrollIntoView({
						            behavior: "smooth",
						            block: "start"
					            });
				            }
			            });
		            });
	            });
            </script>
        </section>', 1, N'en', 0, 0, N'FRProductXepHang', NULL, 1);
