</section>', 1, N'en', 0, 0, N'FRMethodologyPhuongPhapLuan', NULL, 1);
INSERT INTO [dbo].[StaticInformation] ([Id], [Name], [Content], [Status], [Language], [Delete], [ParentId], [Code], [Data], [PortalId]) VALUES (3001136, N'Methodology - Mô hình', N'<section id="Model">
