INSERT INTO [dbo].[StaticInformation] ([Id], [Name], [Content], [Status], [Language], [Delete], [ParentId], [Code], [Data], [PortalId]) VALUES (3001143, N'Business - FiinMethod', N'<section id="FiinMethod" class="mb-5">
    <style>
        .narbarprocess {
            padding: 50px 0;
            display: flex;
            justify-content: space-around;
            align-items: center;
        }

            .narbarprocess a {
                color: #093461;
                text-decoration: none;
                font-size: 18px;
                padding: 8px 0;
                display: flex;
                justify-content: center;
                min-width: 33.3%;
                transition: color 0.3s, border-bottom 0.3s;
                cursor: pointer;
                border-bottom: 3px solid transparent;
            }

                .narbarprocess a.active,
                .narbarprocess a:hover {
                    color: #0066CC;
                    font-weight: 600;
                    border-bottom: 3px solid #093461;
                }

        .company-box {
            border: 1px solid #bcd7ff;
            border-radius: 12px;
            padding: 20px 25px;
            margin: 20px 0;
            /* border gradient bo góc mượt */
            border: 1px solid transparent;
            background-image: linear-gradient(#fff, #fff), linear-gradient(to right, #0018A8, #166BF2, #3B7EEE);
            background-origin: border-box;
            background-clip: padding-box, border-box;
        }

        .item-box {
            margin-bottom: 20px;
        }

        .item-title {
            font-size: 14px;
            color: #093461;
            margin-bottom: 4px;
        }

        .item-value {
            font-size: 16px;
            font-weight: 500;
            color: #0066CC;
        }

        .table-wrapper {
            width: 100%;
            overflow-x: auto;
            margin-top: 20px;
        }

        .info-table {
            width: 100%;
            border-collapse: collapse;
            background: #fff;
            font-size: 15px;
        }

            .info-table th {
                text-align: left;
                padding: 14px 12px;
                color: #034EA2;
                font-weight: 700;
                border-bottom: 1px solid #e4e6e9;
                background: #F7F8F9;
            }

            .info-table td {
                padding: 14px 12px;
                border-bottom: 1px solid #e7eef9;
            }

                .info-table td:first-child {
                    width: 60px;
                    font-weight: 600;
                    text-align: center;
                }

                .info-table td a {
                    color: #0066cc;
                    font-weight: 500;
                    text-decoration: none;
                }

                    .info-table td a:hover {
                        text-decoration: underline;
                    }

                .info-table td .cell-item {
                    margin-bottom: 5px;
                    padding: 10px 0;
                    border-bottom: 1px solid #e7eef9;
                }

                    .info-table td .cell-item:last-child {
                        margin-bottom: 0;
                        border-bottom: none;
                    }



        .strong-money {
            color: #0066cc;
            font-weight: 700;
        }

        .link {
            border-bottom: 1px solid;
            color: #2E90FA;
        }

        @media (max-width: 768px) {
            .narbarprocess {
                padding: 20px 0;
                display: flex;
                flex-wrap: nowrap;
                overflow-x: auto;
                /* scroll ngang */
                gap: 20px;
                scrollbar-width: none;
            }

                .narbarprocess::-webkit-scrollbar {
                    display: none;
                }

                .narbarprocess a {
                    flex: 0 0 auto;
                    min-width: max-content;
                    font-size: 16px;
                    padding: 10px 5px;
                    border-bottom: 2px solid transparent;
                }

                    .narbarprocess a.active,
                    .narbarprocess a:hover {
                        border-bottom: 2px solid #0066CC;
                        color: #0066CC;
                        font-weight: 600;
                    }

            .company-box {
                padding: 16px;
            }

            .item-box {
                margin-bottom: 16px;
            }
        }
    </style>
    <div class="container">
        <div class="narbarprocess">
            <a href="#FiinMethod" class="active">Corporate Legal Documents</a>
            <a href="#ShareholderTable">Shareholder Structure</a>
            <a href="#FinancialReport">Financial Statements</a>
        </div>

        <h2 class="price-title mb-5">Corporate Legal Documents</h2>
        <div class="company-box row">
            <div class="col-lg-4 col-md-4 col-12 item-box mb-0">
                <div class="item-title"><b>Company name</b> (in Vietnamese)</div>
                <div class="item-value">CÔNG TY CỔ PHẦN FIINRATINGS</div>
            </div>

            <div class="col-lg-4 col-md-4 col-12 item-box mb-0">
                <div class="item-title"><b>Company name</b> (in English)</div>
                <div class="item-value">FIINRATINGS JOINT STOCK COMPANY</div>
            </div>

            <div class="col-lg-4 col-md-4 col-12 item-box mb-0">
                <div class="item-title"><b>Abbreviated name of the company</b></div>
                <div class="item-value">FIINRATINGS</div>
            </div>
        </div>

        <div class="table-wrapper">
            <table class="info-table">
                <thead>
                    <tr>
                        <th style="text-align: center;">No.</th>
                        <th style="width: 35%;">Item</th>
                        <th>Content</th>
                    </tr>
                </thead>
                <tbody>
                    <tr>
                        <td>1</td>
                        <td>Head office address</td>
                        <td>
                            10th Floor, Peakview Tower, 36 Hoang Cau, O Cho Dua Ward, Hanoi City, Vietnam
                        </td>
                    </tr>
                    <tr>
                        <td>2</td>
                        <td>Website address</td>
                        <td><a href="#">https://fiinratings.vn/</a></td>
                    </tr>
                    <tr>
                        <td>3</td>
                        <td>Business eligibility certificate regarding credit rating services</td>
                        <td>
                            <div class="cell-item">
                                <a href="https://cdn.fiingroup.vn/medialib/261746/F/2025/12/24/19243018325220700_1.-GCN_CRA_FiinGroup_20March2020.pdf" target="_blank" >
                                    Certificate No. 02/GCN-DVXHTN issued by the Ministry of Finance on March 20, 2020
                                </a><br>
                            </div>
                            <div class="cell-item">
                                <a href="/Data/pdf/FR/2.GCN_CRA_FiinRatings_6March2023_revised.pdf" target="_blank" >First amended in accordance with Amended Certificate No. 02/GCNĐC1-DVXHTN dated 06 March 2025</a>
                            </div>
                          
                           <div class="cell-item">
                                <a href="https://cdn.fiingroup.vn/medialib/261746/F/2025/12/25/09563160135940700_3.-GCN_CRA_FiinRatings_11Dec2025_revised-2.pdf" target="_blank" >Second amended in accordance with Amended Certificate No. 02/GCNĐC2-DVXHTN dated 11 December 2025</a>
                            </div>

                        </td>

                    </tr>

                    <tr>
                        <td>4</td>
                        <td>Enterprise registration certificate</td>
                        <td>
                            <div class="cell-item">
                                <a href="https://fiinratings.vn/Upload/FR_ERC_251112_22nd_Amendment.pdf" target="_blank" >No. 0102674865</a>, first issued on 11 March 2008 by the Business Registration Office of the Hanoi Department of Planning and Investment, and most recently amended on 12 November 2025.
                          </div>  
                        </td>
                    </tr>
                    <tr>
                        <td>5</td>
                        <td>Company charter</td>
                        <td><a href="/Data/pdf/FR/FR_Company-Charter_EN.pdf" target="_blank">Access here</a></td>
                    </tr>
                    <tr>
                        <td>6</td>
                        <td>Paid-in charter capital</td>
                        <td>
                            <strong class="strong-money">VND 28,998,040,000</strong><br>(In words: Twenty-eight billion nine hundred and ninety-eight million forty thousand Vietnamese dong)
                        </td>
                    </tr>
                    <tr>
                        <td>7</td>
                        <td>Legal representative</td>
                        <td>Nguyen Quang Thuan</td>
                    </tr>
                    <tr>
                        <td>8</td>
                        <td>Date of credit rating operation commencement</td>
                        <td>05/06/2020</td>
                    </tr>
                    <tr>
                        <td>9</td>
                        <td>CBI’s climate bond verifier certificate</td>
                        <td><a href="https://fiinratings.vn/images/home/company-info/certificate-3.png" target="_blank">Access here</a></td>
                    </tr>
                </tbody>
            </table>
        </div>
    </div>

    <script>
        document.addEventListener(''DOMContentLoaded'', () => {
            const links = document.querySelectorAll(''.narbarprocess a'');
            links.forEach(link => {
                link.addEventListener(''click'', (e) => {
                    e.preventDefault();
                    // Xóa class active
                    links.forEach(l => l.classList.remove(''active''));
                    link.classList.add(''active'');
                    // Lấy ID mục tiêu
                    const targetId = link.getAttribute(''href'')?.trim();
                    // Nếu href null hoặc không phải id hợp lệ thì thoát
                    if (!targetId || !targetId.startsWith("#")) {
                        return;
                    }
                    const targetEl = document.querySelector(targetId);
                    if (targetEl) {
                        targetEl.scrollIntoView({
                            behavior: "smooth",
                            block: "start"
                        });
                    }
                });
            });
        });
    </script>
</section>', 1, N'en', 0, 0, N'FRBusinessFiinMethod', NULL, 1);
INSERT INTO [dbo].[StaticInformation] ([Id], [Name], [Content], [Status], [Language], [Delete], [ParentId], [Code], [Data], [PortalId]) VALUES (3001144, N'Business - Cơ cấu cổ đông', N'<section id="ShareholderTable" class="mb-5">
