            /* Header */
            .shareholder-table .header-row th {
                background-color: #0066CC;
                color: #fff;
                font-weight: 600;
                padding: 10px 8px;
            }

            .shareholder-table .sub-header th {
                background-color: #ebedf0;
                color: #034ea2;
                font-weight: 600;
                font-size: 13px;
                padding: 10px 8px;
            }

            /* Ô dữ liệu */
            .shareholder-table td {
                padding: 18px 8px;
                color: #093461;
                border-bottom: 1px solid #e5ebf5;
            }

            .shareholder-table .col-name {
                text-align: left;
                padding-left: 15px;
                font-weight: 500;
            }

            .shareholder-table .col-stt {
                width: 40px;
                font-weight: 600;
            }

            .shareholder-table .col-number,
            .shareholder-table .col-percent {
                text-align: center;
                padding-right: 12px;
                color: #326fb3;
            }

            .shareholder-table .col-year {
                background-color: #034ea2;
                color: #fff;
