INSERT INTO [dbo].[StaticInformation] ([Id], [Name], [Content], [Status], [Language], [Delete], [ParentId], [Code], [Data], [PortalId]) VALUES (3001145, N'Business - Báo cáo tài chính', N'<section id="FinancialReport" class="mb-5">
    <style>
        .report-grid {
            display: grid;
            grid-template-columns: repeat(5, 1fr);
            gap: 24px;
        }

        .report-card {
            border-radius: 12px;
            background: #fff;
            border: 1px solid #e1ecff;
            padding: 10px;
            transition: 0.2s ease;
        }

            .report-card:hover {
                box-shadow: 0 4px 20px rgba(0, 0, 0, 0.06);
            }

            .report-card img {
                width: 100%;
                border-radius: 12px 12px 0 0;
   display:none;
            }

        .report-title {
            font-size: 16px;
            font-weight: 600;
            padding: 20px 0 0;
            color: #1D2939;
        }

        .tag-year {
            display: inline-block;
            background: #E8F5FF;
            color: #0066CC;
            padding: 4px 12px;
            border-radius: 12px;
            font-size: 13px;
            font-weight: 600;
        }

        .link-detail {
            display: inline-block;
            margin-top: 10px;
            color: #0066CC;
            font-weight: 600;
            text-decoration: none;
            padding: 15px 0;
            font-size: 16px;
        }

            .link-detail:hover {
                text-decoration: underline;
            }

        .main-title {
            font-size: 25px;
            font-weight: 700;
            color: #093461;
            margin-bottom: 20px;
            line-height: 1.5;
            padding-top: 60px;
        }

        .year-tabs {
            display: flex;
            width: 100%;
            margin-bottom: 25px;
            padding-bottom: 8px;
        }

        .tab-item {
            flex: 1;
            /* mỗi tab = 25% */
            text-align: center;
            background: none;
            border: none;
            font-size: 18px;
            font-weight: 600;
            color: #7A8CA5;
            cursor: pointer;
            transition: 0.2s;
            padding-bottom: 8px;
        }

            .tab-item.active {
                color: #0066CC;
                border-bottom: 3px solid #0066CC;
            }

            .tab-item:hover {
                color: #0066CC;
            }

        .sub-title {
            font-size: 20px;
            font-weight: 600;
            color: #093461;
            margin-bottom: 20px;
        }

        .ranking-table {
            width: 100%;
            border-collapse: collapse;
        }

            .ranking-table th {
                background: #F5F8FF;
                padding: 14px;
                font-size: 14px;
                color: #093461;
                text-align: left;
