INSERT INTO [dbo].[StaticInformation] ([Id], [Name], [Content], [Status], [Language], [Delete], [ParentId], [Code], [Data], [PortalId]) VALUES (3001147, N'Process - Quy trình xếp hạng', N'<section id="FiinMethod" class="mb-5">
    <style>
        .narbarprocess {
            padding: 50px 0;
            display: flex;
            justify-content: space-around;
            align-items: center;
        }

            .narbarprocess a {
                color: #093461;
                text-decoration: none;
                font-size: 18px;
                padding: 8px 0;
                display: flex;
                justify-content: center;
                min-width: 33.3%;
                transition: color 0.3s, border-bottom 0.3s;
                cursor: pointer;
                border-bottom: 3px solid transparent;
            }

                .narbarprocess a.active,
                .narbarprocess a:hover {
                    color: #0066CC;
                    font-weight: 600;
                    border-bottom: 3px solid #093461;
                }

        .rp-desc {
            margin-top: 20px;
            font-size: 18px;
            line-height: 150%;
            color: #093461;
            text-align: justify;
        }

        .chart-box img {
            width: 100%;
            margin-top: 30px;
        }

        .step-item {
            background: transparent;
        }

        .step-header {
            display: flex;
            align-items: center;
            gap: 12px;
        }


        .step-title {
            font-size: 22px;
            font-weight: 700;
            color: #0066CC;
            line-height: 1.5;
            margin: 0;
        }

        .step-text {
            margin-top: 10px;
            color: #093461;
            font-size: 15px;
            line-height: 150%;
            text-align: justify;
        }

        .custom-pagination-wrapper {
            display: flex;
            justify-content: space-between;
            /* mũi tên bên trái, dots bên phải */
            align-items: center;
            width: 100%;
            margin-top: 20px;
        }

        .pagination-arrows {
            display: flex;
            gap: 12px;
        }

        .arrow-btn {
            width: 48px;
            height: 48px;
            border-radius: 50%;
            border: 1.5px solid #0b6bd3;
            background: transparent;
            color: #0b6bd3;
            display: flex;
            align-items: center;
            justify-content: center;
            cursor: pointer;
            font-size: 16px;
        }

            .arrow-btn:hover {
                background: #e8f3ff;
            }

        .pagination-dots {
            display: flex;
            gap: 8px;
            align-items: center;
        }

            .pagination-dots .dot {
                width: 6px;
                height: 6px;
                border-radius: 50%;
                background: #c9c9c9;
            }

                .pagination-dots .dot.active {
                    width: 35px;
                    height: 6px;
                    background: #0b6bd3;
                    border-radius: 4px;
                }
              .step-col {
                  display: none;
              }

                  .step-col.active {
                      display: block;
                  }
              .circle-wrap {
                  width: 50px;
                  height: 50px;
                  border-radius: 50%;
                  border: 2px dotted #7fb0ff;
                  display: flex;
                  align-items: center;
                  justify-content: center;
                  background: #f7fbff;
              }
              .timeline-circle {
                  width: 40px;
                  height: 40px;
                  border-radius: 50%;
                  background: linear-gradient(119.22deg, #0018A8 19.92%, #166BF2 56.45%, #3B7EEE 99.27%);
                  color: #fff;
                  font-weight: 600;
                  display: flex;
                  align-items: center;
                  justify-content: center;
              }

        @media (max-width: 768px) {
            .narbarstory {
                gap: 20px;
            }

            .method-box {
                padding: 20px;
            }

            .narbarprocess {
                padding: 20px 0;
                display: flex;
                flex-wrap: nowrap;
                overflow-x: auto;
                /* scroll ngang */
                gap: 20px;
                scrollbar-width: none;
            }

                .narbarprocess::-webkit-scrollbar {
                    display: none;
                }

                .narbarprocess a {
                    flex: 0 0 auto;
                    min-width: max-content;
                    font-size: 16px;
                    padding: 10px 5px;
                    border-bottom: 2px solid transparent;
                }

                    .narbarprocess a.active,
                    .narbarprocess a:hover {
                        border-bottom: 2px solid #0066CC;
                        color: #0066CC;
                        font-weight: 600;
                    }
            .left-box{
                padding-right:40px;
            }
        }
    </style>
    <div class="container">
        <div class="narbarprocess">
            <a href="#FiinMethod" class="active">Rating Process</a>
            <a href="#Policy">Policies</a>
            <a href="#BasicInfo">Basic Requirements</a>
        </div>
        <div class="row">
            <div class="col-lg-4 col-md-12 left-box">
                <h2 class="price-title">Rating <span style="color: #0066CC;">Process</span></h2>
                <p class="rp-desc">
                    FiinRatings’s credit rating process begins upon receipt of a client’s request, includes due diligence, analysis, decision and publication of the results, followed by periodic updates every six months. Typically, an initial credit rating process takes approximately 6–8 weeks, depending on the level of complexity and the client’s ability to provide information.
                </p>

                <div class="chart-box">
                    <img src="/Data/FR/process_rank.png" alt="chart" />
                </div>
            </div>

            <div class="col-lg-8 col-md-12 right-box">
                <div class="row steps-wrapper">
                    <div class="col-lg-6 col-md-6 col-sm-12 step-col">
                        <div class="step-item">
                            <div class="step-header">
                              	<div class="circle-wrap">
                                    <div class="timeline-circle">01</div>
                                </div>
                                <h4 class="step-title">
                                    Finalize contracts and provide
                                    <br>information as requested
                                </h4>
                            </div>
                            <img src="/Data/Icon/icon-line.svg" alt="line">
                            <p class="step-text">
                                Receive rating requests from issuer and and sign the contract. Issuer prepares and submits the information and documents as required by FiinRatings.
                            </p>
                        </div>
                    </div>

                    <div class="col-lg-6 col-md-6 col-sm-12 step-col">
                        <div class="step-item">
                            <div class="step-header">
                                <div class="circle-wrap">
                                    <div class="timeline-circle">02</div>
                                </div>
                                <h4 class="step-title">
                                    Due diligence <br>
                                    and analysis
                                </h4>
                            </div>
                            <img src="/Data/Icon/icon-line.svg" alt="line">
                            <p class="step-text">
                                Perform preliminary analysis, in-depth interview with the Management Team of the Issuer, and conduct other information-gathering activities.
                            </p>
                        </div>
                    </div>

                    <div class="col-lg-6 col-md-6 col-sm-12 step-col">
                        <div class="step-item">
                            <div class="step-header">
                                <div class="circle-wrap">
                                    <div class="timeline-circle">03</div>
                                </div>
                                <h4 class="step-title">
                                    Identify Principal Risk <br>
                                    Components (PRC)
                                </h4>
                            </div>
                            <img src="/Data/Icon/icon-line.svg" alt="line">
                            <p class="step-text">
                                Analyze key risks from information obtained and conduct peer comparison to identify risks affecting the issuer’s ability to fulfil debt obligations.
                            </p>
                        </div>
                    </div>
                    <div class="col-lg-6 col-md-6 col-sm-12 step-col">
                        <div class="step-item">
                            <div class="step-header">
                                <div class="circle-wrap">
                                    <div class="timeline-circle">04</div>
                                </div>
                                <h4 class="step-title">
                                    Propose preliminary Rating to <br>
                                    the Credit Rating Committee
                                </h4>
                            </div>
                            <img src="/Data/Icon/icon-line.svg" alt="line">
                            <p class="step-text">
                                The Analyst team presents their opinion and propose a rating score to FiinRatings’ Rating Committee.
                            </p>
                        </div>
                    </div>
                  
                  	<div class="col-lg-6 col-md-6 col-sm-12 step-col">
                        <div class="step-item">
                            <div class="step-header">
                              	<div class="circle-wrap">
                                    <div class="timeline-circle">05</div>
                                </div>
                                <h4 class="step-title">
                                    Review the Rating proposal
                                    <br>from the Analytical Team
                                </h4>
                            </div>
                            <img src="/Data/Icon/icon-line.svg" alt="line">
                            <p class="step-text">
                                CRC members review documents provided by the analysts.
                            </p>
                        </div>
                    </div>

                    <div class="col-lg-6 col-md-6 col-sm-12 step-col">
                        <div class="step-item">
                            <div class="step-header">
                                <div class="circle-wrap">
                                    <div class="timeline-circle">06</div>
                                </div>
                                <h4 class="step-title">
                                    Discuss the <br>
                                    Proposal
                                </h4>
                            </div>
                            <img src="/Data/Icon/icon-line.svg" alt="line">
                            <p class="step-text">
                                CRC discusses and evaluates the rating proposal by the analysts.
                            </p>
                        </div>
                    </div>

                    <div class="col-lg-6 col-md-6 col-sm-12 step-col">
                        <div class="step-item">
                            <div class="step-header">
                                <div class="circle-wrap">
                                    <div class="timeline-circle">07</div>
                                </div>
                                <h4 class="step-title">
                                    Finalize the <br>
                                    Proposed Credit Rating
                                </h4>
                            </div>
                            <img src="/Data/Icon/icon-line.svg" alt="line">
                            <p class="step-text">
                                CRC casts their votes on the credit rating result.
                            </p>
                        </div>
                    </div>
                    <div class="col-lg-6 col-md-6 col-sm-12 step-col">
                        <div class="step-item">
                            <div class="step-header">
                                <div class="circle-wrap">
                                    <div class="timeline-circle">08</div>
                                </div>
                                <h4 class="step-title">
                                    Inform the result to the Issuer and <br>
                                    request a review from the CRC (if needed)
                                </h4>
                            </div>
                            <img src="/Data/Icon/icon-line.svg" alt="line">
                            <p class="step-text">
                                Notify the Issuer with a pre-publication rationale for its credit rating result. In case the Issuer appeals and provides further information, CRC discusses further and agrees on the final rating result.
                            </p>
                        </div>
                    </div>
                  
                  	<div class="col-lg-6 col-md-6 col-sm-12 step-col">
                        <div class="step-item">
                            <div class="step-header">
                              	<div class="circle-wrap">
                                    <div class="timeline-circle">09</div>
                                </div>
                                <h4 class="step-title">
                                    Publish the
                                    <br>rating result
                                </h4>
                            </div>
                            <img src="/Data/Icon/icon-line.svg" alt="line">
                            <p class="step-text">
                                Announcing the rating result and archiving the documents related to the rating action.
                            </p>
                        </div>
                    </div>

                    <div class="col-lg-6 col-md-6 col-sm-12 step-col">
                        <div class="step-item">
                            <div class="step-header">
                                <div class="circle-wrap">
                                    <div class="timeline-circle">10</div>
                                </div>
                                <h4 class="step-title">
                                    Surveillance <br>
                                    and update
                                </h4>
                            </div>
                            <img src="/Data/Icon/icon-line.svg" alt="line">
                            <p class="step-text">
                                Conduct periodic surveillance to re-evaluate the credit rating at least every 06 months or immediately upon occurrence of events that affect the issuer’s credit rating result.
                            </p>
                        </div>
                    </div>

                    <!--<div class="col-lg-12 col-md-6 col-sm-12 step-col">
                        <div class="step-item">
                            <div class="step-header">
                                <div class="circle-wrap">
                                    <div class="timeline-circle">11</div>
                                </div>
                                <h4 class="step-title">
                                    Thành lập nhóm CV Phân tích và bổ nhiệm hội đồng XHTN
                                </h4>
                            </div>
                            <img src="/Data/Icon/icon-line.svg" alt="line">
                            <p class="step-text">
                                Ban Điều hành sẽ thành lập nhóm Chuyên viên Phân tích và chỉ định thành viên Hội
                                đồng XHTN. Tất cả các thành viên tham gia vào quá trình XHTN có trách nhiệm tuân
                                thủ tuyệt đối Quy định nghiệp vụ và Chính sách giám sát nội bộ của FiinRatings
                            </p>
                        </div>
                    </div> -->
                                       
                  
                </div>
              	<div class="row">
                    <div class="custom-pagination-wrapper">
                        <div class="pagination-arrows">
                            <button class="arrow-btn">
                                <i class="fa fa-arrow-left"></i>
                            </button>
                            <button class="arrow-btn">
                                <i class="fa fa-arrow-right"></i>
                            </button>
                        </div>

                        <div class="pagination-dots">
                            <span class="dot active"></span>
                            <span class="dot"></span>
                            <span class="dot"></span>
                        </div>
                    </div>
                </div>
              
            </div>
        </div>
    </div>
    <script>
          document.addEventListener("DOMContentLoaded", function () {
              const steps = document.querySelectorAll(".step-col");
              const dotsWrapper = document.querySelector(".pagination-dots");
              const prevBtn = document.querySelector(".arrow-btn:first-child");
              const nextBtn = document.querySelector(".arrow-btn:last-child");
              const swipeArea = document.querySelector(".steps-wrapper");

              let itemsPerPage = 4;
              let currentPage = 0;
              let totalPages = 0;

              /* ===== XÁC ĐỊNH ITEMS / PAGE ===== */
              function calcItemsPerPage() {
                  const w = window.innerWidth;
                  if (w < 768) return 1;        // mobile
                  if (w < 992) return 2;        // tablet
                  return 4;                     // desktop
              }

              function buildDots() {
                  dotsWrapper.innerHTML = "";
                  for (let i = 0; i < totalPages; i++) {
                      const dot = document.createElement("span");
                      dot.className = "dot" + (i === currentPage ? " active" : "");
                      dot.addEventListener("click", () => {
                          currentPage = i;
                          render();
                      });
                      dotsWrapper.appendChild(dot);
                  }
              }

              function render() {
                  steps.forEach(step => step.classList.remove("active"));

                  const start = currentPage * itemsPerPage;
                  const end = start + itemsPerPage;

                  steps.forEach((step, index) => {
                      if (index >= start && index < end) {
                          step.classList.add("active");
                      }
                  });

                  document.querySelectorAll(".pagination-dots .dot")
                      .forEach((dot, idx) =>
                          dot.classList.toggle("active", idx === currentPage)
                      );
              }

              function updateLayout() {
                  itemsPerPage = calcItemsPerPage();
                  totalPages = Math.ceil(steps.length / itemsPerPage);
                  currentPage = Math.min(currentPage, totalPages - 1);
                  buildDots();
                  render();
              }

              function next() {
                  currentPage = (currentPage + 1) % totalPages;
                  render();
              }

              function prev() {
                  currentPage = (currentPage - 1 + totalPages) % totalPages;
                  render();
              }

              prevBtn.addEventListener("click", prev);
              nextBtn.addEventListener("click", next);

              /* ===== SWIPE MOBILE ===== */
              let startX = 0;
              swipeArea.addEventListener("touchstart", e => {
                  startX = e.touches[0].clientX;
              }, { passive: true });

              swipeArea.addEventListener("touchend", e => {
                  const endX = e.changedTouches[0].clientX;
                  const diff = startX - endX;
                  if (Math.abs(diff) > 50) diff > 0 ? next() : prev();
              }, { passive: true });

              window.addEventListener("resize", updateLayout);

              /* INIT */
              updateLayout();
          });
          </script>
</section>', 1, N'en', 0, 0, N'FRProcessQuyTrinh', NULL, 1);
INSERT INTO [dbo].[StaticInformation] ([Id], [Name], [Content], [Status], [Language], [Delete], [ParentId], [Code], [Data], [PortalId]) VALUES (3001148, N'Process - Chính sách của FiinRatings', N'<section id="Policy" class="mb-5">
