INSERT INTO [dbo].[StaticInformation] ([Id], [Name], [Content], [Status], [Language], [Delete], [ParentId], [Code], [Data], [PortalId]) VALUES (3001149, N'Process - Các yêu cầu thông tin cơ bản', N'<section id="BasicInfo" class="mb-5 ">
    <style>
        .subtitle {
            margin-top: 20px;
            font-size: 18px;
            line-height: 150%;
            color: #093461;
            text-align: justify;
        }


        .acc-item {
            padding: 18px 0;
        }

        .acc-header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            cursor: pointer;
            font-size: 18px;
            font-weight: 600;
            color: #093461;
            padding: 10px 0;
            border-bottom: 1px solid #d6e4f5;
        }

        .acc-icon {
            width: 22px;
            height: 22px;
        }

        .acc-content {
            display: none;
            padding: 14px 0 5px 20px;
        }

        .acc-item.open .acc-content {
            display: block;
        }

        .acc-item.open .acc-icon {
            content: url("/Data/FR/minus-circle.png?v=1");
        }

        .acc-item:not(.open) .acc-icon {
            content: url("/Data/FR/add-circle.png?v=1");
        }

        .acc-content ul {
            list-style: none;
        }

        .acc-content li {
            position: relative;
            padding-left: 20px;
            margin-bottom: 6px;
        }

            .acc-content li::before {
                content: "";
                position: absolute;
                left: 0;
                top: 9px;
                width: 6px;
                height: 6px;
                background: #0B66C3;
                border-radius: 50%;
            }
    </style>
    <div class="container">
        <h2 class="price-title">
            Basic <span style="color: #0066CC;">Information Requirements</span>
        </h2>
        <p class="subtitle">
            Below is a list of basic information that Issuers need to provide to FiinRatings when engaging in a rating action. The detailed list will be discussed during the working process between the two parties.
        </p>

        <div class="acc-item open">
            <div class="acc-header">
                <span>Information about business profile</span>
                <img class="acc-icon" src="/Data/FR/minus-circle.png?v=1" alt="close">
            </div>
            <ul class="acc-content">
                <li>Legal documents related to business establishment, investment registration certificate</li>
                <li>Information about the Board of Directors, Board of Members, and Executive Board</li>
                <li>Charter, Operational Regulations, Organizational Structure</li>
                <li>Information about key products and services</li>
            </ul>
        </div>

        <div class="acc-item">
            <div class="acc-header">
                <span>Information on strategic direction and business plan</span>
                <img class="acc-icon" src="/Data/FR/plus-circle.png?v=1" alt="open">
            </div>
            <ul class="acc-content">
                <li>Research, analysis and evaluation reports on the main lines of business in which the company operates</li>
                <li>Company development strategy and business plan</li>
            </ul>
        </div>

        <div class="acc-item">
            <div class="acc-header">
                <span>Information about the financial position of the enterprise</span>
                <img class="acc-icon" src="/Data/FR/plus-circle.png?v=1" alt="open">
            </div>
            <ul class="acc-content">
                <li>Audited financial statements
                <li>Financial forecasting model</li>
                <li>Financial management policies and management reporting</li>
                <li>Debts and repayment schedule</li>
            </ul>
        </div>

        <div class="acc-item">
            <div class="acc-header">
                <span>Other information</span>
                <img class="acc-icon" src="/Data/FR/plus-circle.png?v=1" alt="open">
            </div>
            <ul class="acc-content">
                <li>Legal documents of important projects</li>
                <li>Important contracts and commitments</li>
            </ul>
        </div>
    </div>
    <script>
        document.querySelectorAll(''.acc-header'').forEach(header => {
            header.addEventListener(''click'', () => {
                const item = header.parentElement;
                const isOpen = item.classList.contains("open");

                // Đóng tất cả mục khác (nếu muốn accordion dạng chỉ mở 1)
                // document.querySelectorAll(".acc-item").forEach(i => i.classList.remove("open"));

                // Toggle chính nó
                if (!isOpen) {
                    item.classList.add("open");
                } else {
                    item.classList.remove("open");
                }
            });
        });
    </script>
</section>', 1, N'en', 0, 0, N'FRProcessCacYeuCau', NULL, 1);
