INSERT INTO [dbo].[StaticInformation] ([Id], [Name], [Content], [Status], [Language], [Delete], [ParentId], [Code], [Data], [PortalId]) VALUES (3001159, N'Services - Tổng quan', N' <style>
 .tilte-card,.tilte-card-center{font-size:28px;font-weight:500}#FiinCard{margin:0 0 5%}.narbartrust{padding:50px 0;display:flex;justify-content:space-around;align-items:center}.box-center,.box-left,.box-right{padding:25px;text-align:center;box-shadow:0 4px 8px #0000001a;border-radius:15px}.narbartrust a{color:#093461;text-decoration:none;font-size:18px;padding:8px 10px;display:flex;justify-content:center;min-width:20%;transition:color .3s,border-bottom .3s;cursor:pointer;border-bottom:3px solid transparent}.narbartrust a.active,.narbartrust a:hover{color:#06c;border-bottom:3px solid #093461}.box-card{text-align:center;align-items:center}.box-left,.box-right{background-color:#fafbfe;margin:45px 0;transition:transform .3s}.box-center{position:relative;background-color:#fff;overflow:hidden}.box-center::before,.box-left::before,.box-right::before{content:"";position:absolute;inset:0;border-radius:15px;padding:2px;-webkit-mask-composite:xor;mask-composite:exclude;pointer-events:none}.tilte-card{margin-bottom:10px;min-height:69px}.noted-card{border-radius:8px}.feature-item{display:flex;align-items:flex-start;margin-bottom:10px}.dang-ky-card,.dang-ky-card-center{padding:7px 70px;cursor:pointer;display:inline-block}.tilte-card-center{margin-bottom:10px!important}.feature-item i.fa.fa-check-circle{color:#28a745;margin-right:15px;font-size:16px;line-height:1}.feature-item span{color:#000;line-height:1.5;text-align:left}.feature-item span span{color:#1d2939;font-weight:700}.fa.fa-check-circle{color:#28a745;margin-right:8px;padding-top:5px;text-align:left; text-align: left}.dang-ky-card{background-color:#fff;color:#06c;border-radius:25px;margin-top:20px;border:1px solid #06c}.dang-ky-card-center{background-color:#06c;color:#fff;border-radius:25px}.box-center:hover::before,.box-left:hover::before,.box-right:hover::before{background:linear-gradient(to right,#034ea2,#53dfff)!important;-webkit-mask:linear-gradient(#fff 0 0) content-box,linear-gradient(#fff 0 0);-webkit-mask-composite:xor;mask-composite:exclude}.box-center:hover,.box-left:hover,.box-right:hover{transform:translateY(-16px);transform:scale(1.1);z-index:9999}
.dang-ky-card, .dang-ky-card-center {padding: 7px 34px;}
</style>

 <section id="FiinCard">
     <div class="container">
         <div class="narbartrust">
             <a href="#FiinTrust" class="active">Overview</a>
             <a href="#OutStand">Track Records</a>
             <a href="#FiinTrust">Key Values</a>
             <a href="#Partner">Our Clients</a>
             <a href="#UserTeam">Analyst Team</a>
         </div>
         <div class="row row2 box-card">
             <h2 class="text-center price-title mb-5">What <span style="color: #0066cc;">Investor services</span> offer?</h2>
             <div class="col-lg-4 col-sm-12">
                 <div class="box-left">
                     <div class="tilte-card"> <span style="color: #0066CC; ">Company Credit </span> Assessment</div>
                     <div class="noted-card">
                         <div class="feature-item">
                             <span style="text-align: left;">
                                 FiinRatings provides credit assessments of individual companies at a specific time or on an ongoing basis, based on company profiles, management quality, business and financial risks, along with credit ratings.
                             </span>
                         </div>
                     </div>
                     <a class="dang-ky-card" href="https://fiinratings.vn/upload/docs/credit-risk-assessment-banks.pdf" target="_blank">Download sample reports</a>
                 </div>
             </div>
             <div class="col-lg-4 col-sm-12">
                 <div class="box-left">
                     <div class="tilte-card">
                         <span style="color: #0066CC; ">Sector Credit </span> <br/>Research
                     </div>
                     <div class="noted-card">
                         <div class="feature-item" style="text-align: left;">
                             <span>Based on credit frameworks and industry standards, FiinRatings delivers comprehensive and periodic reports covering market size, segmentation, sector credit outlook, and key industry trends, helping investors stay ahead of market developments.</span>
                         </div>
                     </div>
                     <a class="dang-ky-card mt-4" href="https://fiinratings.vn/upload/docs/sector-credit-insights-steel-industry.pdf" target="_blank">Download sample reports</a>
                 </div>
             </div>
             <div class="col-lg-4 col-sm-12">
                 <div class="box-right">
                     <div class="tilte-card"><span style="color: #0066CC; ">Portfolio Credit</span><br />Monitoring</div>
                     <div class="noted-card">
                         <div class="feature-item" style="text-align: left;">
                             <span>FiinRatings helps monitor portfolio credit risk through regular reports updating on issuers and debt instruments, including credit assessments, business and financial risk analysis, indicative ratings, as well as sectoral and market changes.</span>
                         </div>
                     </div>
                     <a class="dang-ky-card" href="https://fiinratings.vn/upload/docs/credit-risk-assessment-banks.pdf" target="_blank">Download sample reports</a>
                 </div>
             </div>
         </div>
     </div>
     <script>
         document.addEventListener(''DOMContentLoaded'', () => {
             const links = document.querySelectorAll(''.narbartrust a'');
             links.forEach(link => {
                 link.addEventListener(''click'', (e) => {
                     e.preventDefault();
                     // Xóa class active
                     links.forEach(l => l.classList.remove(''active''));
                     link.classList.add(''active'');
                     // Lấy ID mục tiêu
                     const targetId = link.getAttribute(''href'')?.trim();
                     // Nếu href null hoặc không phải id hợp lệ thì thoát
                     if (!targetId || !targetId.startsWith("#")) {
                         return;
                     }
                     const targetEl = document.querySelector(targetId);
                     if (targetEl) {
                         targetEl.scrollIntoView({
                             behavior: "smooth",
                             block: "start"
                         });
                     }
                 });
             });
         });
     </script>
 </section>', 1, N'en', 0, 0, N'FRServicesTongQuan', NULL, 1);
INSERT INTO [dbo].[StaticInformation] ([Id], [Name], [Content], [Status], [Language], [Delete], [ParentId], [Code], [Data], [PortalId]) VALUES (3001160, N'Finance - Banner', N'<section id="SliderBanner">
