INSERT INTO [dbo].[StaticInformation] ([Id], [Name], [Content], [Status], [Language], [Delete], [ParentId], [Code], [Data], [PortalId]) VALUES (3001163, N'Finance - Phương pháp luận', N'<style>
    .timeline {
        position: relative;
    }

    /* Line ngang nối 01-02-03 */
    .timeline-horizontal {
        position: absolute;
        top: 42px;
        left: calc(16.666% + 28px);
        width: calc(66.666% - 56px);
        height: 1px;
        background: #0d6efd;
        z-index: 1;
    }

    /* Item */
    .timeline-item {
        position: relative;
        z-index: 2;
    }

    /* Vòng chấm */
    .circle-wrap {
        width: 72px;
        height: 72px;
        margin: 0 auto;
        border-radius: 50%;
        border: 2px dotted #7fb0ff;
        display: flex;
        align-items: center;
        justify-content: center;
        background: #f7fbff;
    }

    /* Circle chính */
    .timeline-circle {
        width: 56px;
        height: 56px;
        border-radius: 50%;
        background: linear-gradient(119.22deg, #0018A8 19.92%, #166BF2 56.45%, #3B7EEE 99.27%);
        color: #fff;
        font-weight: 600;
        display: flex;
        align-items: center;
        justify-content: center;
    }

    /* Line dọc từ circle xuống box */
    .timeline-vertical {
        width: 1px;
        height: 28px;
        background: #0d6efd;
        margin: 0 auto;
    }

    /* Box */
    .timeline-box {
        background: #ffffff;
        border: 1.5px solid #0066CC;
        border-radius: 12px;
        padding: 22px;
        font-weight: 500;
        height: 180px;
        line-height: 1.7;
        box-shadow: 0 6px 14px rgba(0, 0, 0, 0.05);
      text-align: justify;
    }
    .FiinPP p{
        font-weight: 500;
    }
</style>
<section id="FiinPP">
    <div class="container py-4">
        <div class="row mb-5">
            <h2 class="price-title mb-4" style="text-align: center;">Methodology</h2>
            <p>
                FiinRatings develop our methodology by combining international standards with the unique traits of the domestic market to provide independent, reliable, transparent assessments that meet sustainable development needs.
            </p>
        </div>
        <div class="timeline row position-relative">
            <div class="timeline-horizontal"></div>

            <!-- Step 1 -->
            <div class="col-md-4 text-center timeline-item">
                <div class="circle-wrap">
                    <div class="timeline-circle">01</div>
                </div>
                <div class="timeline-vertical"></div>
                <div class="timeline-box">
                    Reviewing industry-specific sustainability factors with tailored sustainability criteria and benchmarks, based on best practices and industry trends, and customized to address ESG risks and opportunities.
                </div>
            </div>

            <!-- Step 2 -->
            <div class="col-md-4 text-center timeline-item">
                <div class="circle-wrap">
                    <div class="timeline-circle">02</div>
                </div>
                <div class="timeline-vertical"></div>
                <div class="timeline-box">
                    Delivering clear, comprehensive, and actionable insights through reports and transparent announcements as a foundation for investors decision-making.
                </div>
            </div>

            <!-- Step 3 -->
            <div class="col-md-4 text-center timeline-item">
                <div class="circle-wrap">
                    <div class="timeline-circle">03</div>
                </div>
                <div class="timeline-vertical"></div>
                <div class="timeline-box">
                    Updating our methodology based on the latest standards and principles, reflecting market developments and in-depth research to optimize the assessment process.
                </div>
            </div>

        </div>
        <div class="view-now-wrapper my-5">
            <a href="https://fiinratings.vn/Upload/[EN]_FiinRatings_SPO_Methodology_15092024.pdf" target="_blank" class="btn btn-primary btn-join">
                View Details
            </a>
        </div>
    </div>
</section>
 <div>
 <div class="container">
    <div class="why mb-4">
        <h2 class="price-title text-center">Assessment Results</h2>
	</div>
</div>	
</div>', 1, N'en', 0, 0, N'FRFinancePhuongPhap', NULL, 1);
INSERT INTO [dbo].[StaticInformation] ([Id], [Name], [Content], [Status], [Language], [Delete], [ParentId], [Code], [Data], [PortalId]) VALUES (3001164, N'Finance - Tổng quan', N'<style>
