INSERT INTO [dbo].[StaticInformation] ([Id], [Name], [Content], [Status], [Language], [Delete], [ParentId], [Code], [Data], [PortalId]) VALUES (3001175, N'Product - Why Lastest', N'<section id="WhyLastest" class="py-5">
    <style>
        #WhyLastest {
            width: 100%;
            /*position: relative;
            background: url("/Data/FR/about_bggiatri.jpg") no-repeat center/cover;
             Đổi tên file nếu khác
            color: #ffffff; */
          	    background: radial-gradient(circle at 0% 50%, rgba(0, 150, 255, 0.2), transparent 16%), radial-gradient(circle at 90% 50%, rgba(0, 150, 255, 0.22), transparent 16%), #F5F9FF !important;
            padding: 80px 0;
        }

        /* Nội dung bên trái */
        #WhyLastest .content {
            position: relative;
            width: 60%;
            z-index: 2;
        }

        /* Tiêu đề */
        #WhyLastest h2 {
            font-size: 40px;
            font-weight: 700;
            margin: 25px 0px;
        }

        /* Đoạn mô tả */
        #WhyLastest .content>p {
            font-size: 15px;
            line-height: 1.7;
            margin-bottom: 80px;
            text-align: justify;
        }

        /* Các mục */
        #WhyLastest .value-item {
            margin: 0 10% 40px 0;
        }

        /* Tiêu đề từng mục + gạch */
        #WhyLastest .value-item h3 {
            font-size: 30px;
            font-weight: 600;
            margin-bottom: 6px;
            padding-bottom: 6px;
            position: relative;
          	color:#0066CC;
        }


        /* Văn bản mô tả từng giá trị */
        #WhyLastest .value-item p {
            font-size: 15px;
            font-weight: 500;
            line-height: 1.6;
            opacity: 0.95;
            text-align: justify;
          	color:#093461;
        }
    </style>
    <div class="container">
      	<div class="row">
          	<div class="col-lg-7 col-sm-12 mb-4">
          		<h2 class="mb-6">How we <span style="color:#0066CC;">support clients </span></h2>
			</div>
        <div class="col-lg-7 col-sm-12 mb-4">
            <div class="value-item">
                <h3>Independent & credible assessment</h3>
                <p>Deliver independent credit opinions, enabling companies to clearly assess their credit standing and shaping effective capital strategies.
                </p>
            </div>

            <div class="value-item">
                <h3>Enhancing credit profile</h3>
                <p>Credit ratings highlight financial strength, enhancing negotiating power on interest rates, tenors, and access to higher-quality funding sources.</p>
            </div>

            <div class="value-item">
                <h3>Regulatory compliance</h3>
                <p>Support transparent disclosure and compliance with state regulations, facilitating a smooth and standards-compliant bond issuance process.</p>
            </div>

            <div class="value-item">
                <h3>Proactive access to the investor network</h3>
                <p>Enable issuers to connect with a network of over 1,000 institutional investors and 60,000+ professional investors, broadening capital-raising opportunities.</p>
            </div>

            <div class="value-item">
                <h3>Not constrained by the sovereign ceiling</h3>
                <p>FiinRatings’ national rating scale allows qualified issuers to achieve AAA ratings, accurately reflecting creditworthiness without being capped by the sovereign ceiling (BB+/Ba2).
                </p>
            </div>
        </div>
      	<div class="col-lg-5 col-sm-12 text-center">
				<img src="/Data/FR/sp-1.jpg" class="img-fluid solution-img" alt="Lĩnh vực Đầu tư Tài chính">
			</div>
          </div>
    </div>

</section>', 1, N'en', 0, 0, N'FRProductWhyLastest', NULL, 1);
