INSERT INTO [dbo].[StaticInformation] ([Id], [Name], [Content], [Status], [Language], [Delete], [ParentId], [Code], [Data], [PortalId]) VALUES (3001189, N'Form nhận tin tức - thông báo', N'<div class="col-sm-12 mb-3">
      <div class="form-check">
         <input class="form-check-input" type="checkbox" id="agreeTerms2">
         <label style="font-size: 13px;" class="form-check-label" for="agreeTerms2">
           <strong class="error">*</strong> Tôi đồng ý với 
           <a target="_blank" href="/vi/dieu-khoan-va-dieu-kien.html">Điều khoản và Điều kiện</a> và 
           <a target="_blank" href="https://staging-be.fiingroup.vn/Data/pdf/fgvn-chinh-sach-bao-ve-du-lieu-ca-nhan-vi.pdf#viewer.action=download">Chính sách Bảo vệ Dữ liệu cá nhân</a> của FiinGroup.
         </label>
         <span data-value="Vui lòng đồng ý với điều khoản và chính sách để tiếp tục" class="validate-style d-block" id="agreeTermsError"></span>
     </div>
  <div id="thankYouModal2">
           <div class="thank-you-content">
               <button class="thank-you-close-x" onclick="closeThankYouModal2()">&times;</button>

               <div class="thank-you-icon">
                   <svg viewBox="0 0 52 52">
                       <path d="M14 27l7.5 7.5L38 18" />
                   </svg>
               </div>

               <h2 class="thank-you-title">Gửi yêu cầu thành công</h2>

               <p class="thank-you-message">
                   <div>Cảm ơn bạn đã quan tâm và đăng kí!</div>
                   <div>Đội ngũ của FiinGroup sẽ liên hệ trong thời gian sớm nhất!</div>
               </p>

               <button class="thank-you-close-btn" onclick="closeThankYouModal2()">
                   Đóng
               </button>
           </div>
       </div>
</div>      
<script>
  $(document).ready(function () {
    const agreeTerms = $("#formLienHe2 #agreeTerms2");
    const submitBtn = $("#formLienHe2 .btn-yeucau");
    // Hàm bật/tắt nút gửi
    function toggleSubmitButton() {
      if (agreeTerms.is(":checked")) {
        submitBtn.prop("disabled", false);
      } else {
        submitBtn.prop("disabled", true);
      }
    }
    // Gọi hàm ngay khi load
    toggleSubmitButton();
    // Lắng nghe sự kiện thay đổi checkbox
    agreeTerms.on("change", toggleSubmitButton);
  });
</script>


 ', 1, N'vi', 0, 0, N'ContactFormMsg2', NULL, 1);
